do $$
begin
  if exists (
    select 1
    from _recipe_cooking_step_recipe_keys k
    left join public.recipes r on r.recipe_key = k.recipe_key
    where r.id is null
  ) then
    raise exception 'recipe_cooking_steps_v1 contains recipe_key values missing from public.recipes';
  end if;
end $$;

