create temp table _recipe_steps_seed (
  recipe_key text not null,
  step_number integer not null,
  title text not null,
  body text not null,
  estimated_minutes integer null,
  timer_seconds integer null,
  ingredient_keys text[] not null,
  equipment_keys text[] not null,
  tips text null
) on commit drop;

