  ('lemon_garlic_white_fish', 2, '先做底味', '按柠檬蒜香白鱼的做法先处理香味、汤底或主料，让基础味道出来。', 5, null, array['white_fish', 'lemon', 'garlic']::text[], array['pan', 'spatula', 'knife', 'cutting_board']::text[], null),
  ('lemon_garlic_white_fish', 3, '完成主流程', '继续加热到鱼肉由透明转白，能轻轻推动但不碎，再合入剩余食材。', 8, null, array['white_fish', 'lemon', 'garlic']::text[], array['pan', 'spatula', 'knife', 'cutting_board']::text[], null),
  ('lemon_garlic_white_fish', 4, '调味收尾', '根据柠檬蒜香白鱼补足咸淡，看到蒜香明显但蒜末没有发黑即可。', 3, null, array['white_fish', 'lemon', 'garlic']::text[], array['pan', 'spatula', 'knife', 'cutting_board']::text[], null)
;

