values
  ('tomato_egg_stir_fry', 1, '处理食材', '鸡蛋打散到蛋清蛋黄融合，番茄切成大小接近的块或段，看一遍顺序，番茄炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['tomato', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('tomato_egg_stir_fry', 2, '热锅下油', '锅面热后加油，油能流动铺开，说明番茄炒蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('tomato_egg_stir_fry', 3, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让番茄炒蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tomato_egg_stir_fry', 4, '加入配菜', '加入番茄翻炒，看到颜色变亮、边缘开始变软但还保留形状，让番茄炒蛋状态更稳定。', 'stir_fry', array['tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tomato_egg_stir_fry', 5, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄炒蛋状态更稳定。', 'combine_ingredients', array['tomato', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tomato_egg_stir_fry', 6, '装盘检查', '确认番茄炒蛋蛋液边缘刚凝固、中间仍柔软，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['tomato', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('scallion_egg_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，葱花鸡蛋炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('scallion_egg_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，葱花切好备用，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['egg', 'scallion']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('scallion_egg_fried_rice', 3, '先炒配料', '锅热加油后先处理鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，再离火，让葱花鸡蛋炒饭状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('scallion_egg_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让葱花鸡蛋炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('scallion_egg_fried_rice', 5, '合入配料', '把鸡蛋、葱花和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('scallion_egg_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，葱花鸡蛋炒饭不出现湿团。', 'season', array['rice', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('scallion_egg_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让葱花鸡蛋炒饭状态更稳定。', 'check_doneness', array['rice', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('scallion_egg_fried_rice', 8, '盛出炒饭', '把葱花鸡蛋炒饭盛入碗中，表面能看到配料均匀分布，外观整齐后上桌。', 'plate_dish', array['rice', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('garlic_broccoli', 1, '备好配料', '西兰花切成大小接近的块或段，蒜切好备用，看一遍顺序，蒜香西兰花下锅后就不用临时找东西。', 'prep_ingredients', array['broccoli', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('garlic_broccoli', 2, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让蒜香西兰花状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('garlic_broccoli', 3, '加入配菜', '加入西兰花翻炒，看到颜色变亮、边缘开始变软但还保留形状，让蒜香西兰花状态更稳定。', 'stir_fry', array['broccoli']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('garlic_broccoli', 4, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让蒜香西兰花状态更稳定。', 'combine_ingredients', array['broccoli', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('garlic_broccoli', 5, '出锅确认', '确认蒜香西兰花蔬菜颜色变亮，边缘开始变软但仍有支撑感，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['broccoli', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
