  ('tofu_mushroom_stir_fry', 1, '整理食材', '豆腐切块后轻轻吸掉表面水分，蘑菇切成大小接近的块或段，蒜切好备用，看一遍顺序，蘑菇烧豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['tofu', 'mushroom', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
