  ('tofu_mushroom_stir_fry', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让蘑菇烧豆腐状态更稳定。', 'combine_ingredients', array['tofu', 'mushroom', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
