  ('chicken_broccoli_stir_fry', 1, '备好配料', '鸡胸肉切成薄片或小块，西兰花切成大小接近的块或段，蒜切好备用，看一遍顺序，鸡胸西兰花快炒下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_breast', 'broccoli', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
