  ('ginger_scallion_chicken_thigh', 7, '回锅收味', '把边缘食材推回锅心，姜葱鸡腿肉味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('ginger_scallion_chicken_thigh', 8, '整理出餐', '确认姜葱鸡腿肉肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_thigh', 'ginger', 'scallion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('beef_onion_stir_fry', 1, '处理食材', '牛肉片切成薄片或小块，洋葱切好备用，看一遍顺序，洋葱牛肉片下锅后就不用临时找东西。', 'prep_ingredients', array['beef_slice', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('beef_onion_stir_fry', 2, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让洋葱牛肉片状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('beef_onion_stir_fry', 3, '处理主料', '放入牛肉片摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让洋葱牛肉片状态更稳定。', 'sear_meat', array['beef_slice']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('beef_onion_stir_fry', 4, '合炒入味', '把锅中食材合在一起，调味后看到洋葱牛肉片的主味均匀裹在食材上。', 'combine_ingredients', array['beef_slice', 'onion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('beef_onion_stir_fry', 5, '调整火候', '转中火让洋葱牛肉片继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_onion_stir_fry', 6, '观察主料', '夹起主要食材看颜色和质地，洋葱牛肉片没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_onion_stir_fry', 7, '回锅收味', '把边缘食材推回锅心，洋葱牛肉片味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_onion_stir_fry', 8, '装盘检查', '确认洋葱牛肉片肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['beef_slice', 'onion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('ground_beef_tomato_tofu', 1, '整理食材', '豆腐切块吸水，牛肉碎拨散，番茄切小块，确认三样都方便快速下锅。', 'prep_ingredients', array['ground_beef', 'tomato', 'tofu']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('ground_beef_tomato_tofu', 2, '清洗沥水', '番茄冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低，让番茄牛肉碎豆腐状态更稳定。', 'wash_ingredients', array['tomato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('ground_beef_tomato_tofu', 3, '起锅加油', '锅面热后加油，油能流动铺开，说明番茄牛肉碎豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('ground_beef_tomato_tofu', 4, '处理主料', '放入牛肉碎、豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边。', 'sear_meat', array['ground_beef', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('ground_beef_tomato_tofu', 5, '加入配菜', '加入番茄翻炒，看到颜色变亮、边缘开始变软但还保留形状，让番茄牛肉碎豆腐状态更稳定。', 'stir_fry', array['tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('ground_beef_tomato_tofu', 6, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄牛肉碎豆腐状态更稳定。', 'combine_ingredients', array['ground_beef', 'tomato', 'tofu']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('ground_beef_tomato_tofu', 7, '调整火候', '转中火让番茄牛肉碎豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('ground_beef_tomato_tofu', 8, '盛出收尾', '确认番茄牛肉碎豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['ground_beef', 'tomato', 'tofu']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('pork_cabbage_stir_fry', 1, '备好配料', '猪肉片切成薄片或小块，卷心菜切成大小接近的块或段，蒜切好备用，看一遍顺序，猪肉片炒卷心菜下锅后就不用临时找东西。', 'prep_ingredients', array['pork_slice', 'cabbage', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('pork_cabbage_stir_fry', 2, '清洗沥水', '卷心菜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['cabbage']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('pork_cabbage_stir_fry', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让猪肉片炒卷心菜状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('pork_cabbage_stir_fry', 4, '处理主料', '放入猪肉片摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['pork_slice']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('pork_cabbage_stir_fry', 5, '加入配菜', '加入卷心菜翻炒，看到颜色变亮、边缘开始变软但还保留形状，让猪肉片炒卷心菜状态更稳定。', 'stir_fry', array['cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('pork_cabbage_stir_fry', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让猪肉片炒卷心菜状态更稳定。', 'combine_ingredients', array['pork_slice', 'cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('pork_cabbage_stir_fry', 7, '调整火候', '转中火让猪肉片炒卷心菜继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('pork_cabbage_stir_fry', 8, '出锅确认', '确认猪肉片炒卷心菜肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['pork_slice', 'cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('shrimp_egg_stir_fry', 1, '备齐食材', '鸡蛋打散到蛋清蛋黄融合，虾仁沥干到表面不挂水，葱花切好备用，看一遍顺序，虾仁滑蛋下锅后就不用临时找东西。', 'prep_ingredients', array['shrimp', 'egg', 'scallion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('shrimp_egg_stir_fry', 2, '爆出香味', '锅热加油后放葱花，闻到香气、边缘微微变色就进入下一步。', 'saute_aromatics', array['scallion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('shrimp_egg_stir_fry', 3, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让虾仁滑蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shrimp_egg_stir_fry', 4, '处理主料', '放入虾仁摊开受热，看到虾仁由半透明转粉并自然卷起再翻动或拨到锅边，让虾仁滑蛋状态更稳定。', 'sear_meat', array['shrimp']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('shrimp_egg_stir_fry', 5, '合炒入味', '把锅中食材合在一起，调味后看到葱姜香气出来，锅里没有生辛味，让虾仁滑蛋状态更稳定。', 'combine_ingredients', array['shrimp', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shrimp_egg_stir_fry', 6, '调整火候', '转中火让虾仁滑蛋继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('shrimp_egg_stir_fry', 7, '观察主料', '夹起主要食材看颜色和质地，虾仁滑蛋没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('shrimp_egg_stir_fry', 8, '整理出餐', '确认虾仁滑蛋虾仁由半透明转粉并自然卷起，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['shrimp', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('white_fish_ginger_scallion', 1, '处理食材', '白鱼擦干并切成厚度接近的块，姜、葱花切好备用，看一遍顺序，姜葱白鱼下锅后就不用临时找东西。', 'prep_ingredients', array['white_fish', 'ginger', 'scallion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('white_fish_ginger_scallion', 2, '爆出香味', '锅热加油后放姜、葱花，闻到香气、边缘微微变色就进入下一步。', 'saute_aromatics', array['ginger', 'scallion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('white_fish_ginger_scallion', 3, '处理主料', '放入白鱼摊开受热，看到鱼肉由透明转白，能轻轻推动但不碎再翻动或拨到锅边。', 'pan_fry', array['white_fish']::text[], array['pan', 'spatula']::text[], 5, null, '鱼类步骤提醒轻推，避免频繁翻面导致散碎。'),
  ('white_fish_ginger_scallion', 4, '合炒入味', '把锅中食材合在一起，调味后看到葱姜香气出来，锅里没有生辛味，让姜葱白鱼状态更稳定。', 'combine_ingredients', array['white_fish', 'ginger', 'scallion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('white_fish_ginger_scallion', 5, '调整火候', '转中火让姜葱白鱼继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('white_fish_ginger_scallion', 6, '观察主料', '夹起主要食材看颜色和质地，姜葱白鱼没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('white_fish_ginger_scallion', 7, '回锅收味', '把边缘食材推回锅心，姜葱白鱼味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('white_fish_ginger_scallion', 8, '装盘检查', '确认姜葱白鱼鱼肉由透明转白，能轻轻推动但不碎，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['white_fish', 'ginger', 'scallion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('tofu_bok_choy', 1, '整理食材', '豆腐切块后轻轻吸掉表面水分，小白菜切成大小接近的块或段，蒜切好备用，看一遍顺序，小白菜豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['tofu', 'bok_choy', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('tofu_bok_choy', 2, '清洗沥水', '小白菜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['bok_choy']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tofu_bok_choy', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让小白菜豆腐状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('tofu_bok_choy', 4, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让小白菜豆腐状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('tofu_bok_choy', 5, '加入配菜', '加入小白菜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['bok_choy']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tofu_bok_choy', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让小白菜豆腐状态更稳定。', 'combine_ingredients', array['tofu', 'bok_choy', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tofu_bok_choy', 7, '调整火候', '转中火让小白菜豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('tofu_bok_choy', 8, '盛出收尾', '确认小白菜豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['tofu', 'bok_choy', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('green_beans_ground_pork', 1, '备好配料', '猪肉末拨散，四季豆切成大小接近的块或段，蒜切好备用，看一遍顺序，肉末四季豆下锅后就不用临时找东西。', 'prep_ingredients', array['green_beans', 'ground_pork', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('green_beans_ground_pork', 2, '清洗沥水', '四季豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['green_beans']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('green_beans_ground_pork', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让肉末四季豆状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('green_beans_ground_pork', 4, '处理主料', '放入猪肉末摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['ground_pork']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('green_beans_ground_pork', 5, '加入配菜', '加入四季豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['green_beans']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('green_beans_ground_pork', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让肉末四季豆状态更稳定。', 'combine_ingredients', array['green_beans', 'ground_pork', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('green_beans_ground_pork', 7, '调整火候', '转中火让肉末四季豆继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('green_beans_ground_pork', 8, '出锅确认', '确认肉末四季豆肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['green_beans', 'ground_pork', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('mapo_tofu_student', 1, '备齐食材', '豆腐切块后轻轻吸掉表面水分，猪肉末拨散，看一遍顺序，留学生版麻婆豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['tofu', 'ground_pork', 'doubanjiang']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('mapo_tofu_student', 2, '热锅铺油', '锅面热后加油，油能流动铺开，说明留学生版麻婆豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('mapo_tofu_student', 3, '处理主料', '放入豆腐、猪肉末摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边。', 'sear_meat', array['tofu', 'ground_pork']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('mapo_tofu_student', 4, '合炒入味', '把锅中食材合在一起，调味后看到红亮酱香散开但没有糊底。', 'combine_ingredients', array['tofu', 'ground_pork', 'doubanjiang']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('mapo_tofu_student', 5, '调整火候', '转中火让留学生版麻婆豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('mapo_tofu_student', 6, '观察主料', '夹起主要食材看颜色和质地，留学生版麻婆豆腐没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('mapo_tofu_student', 7, '回锅收味', '把边缘食材推回锅心，留学生版麻婆豆腐味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('mapo_tofu_student', 8, '整理出餐', '确认留学生版麻婆豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['tofu', 'ground_pork', 'doubanjiang']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('spicy_eggplant_tofu', 1, '处理食材', '豆腐切块后轻轻吸掉表面水分，茄子切成大小接近的块或段，看一遍顺序，豆瓣茄子豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['eggplant', 'tofu', 'doubanjiang']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('spicy_eggplant_tofu', 2, '清洗沥水', '茄子冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['eggplant']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('spicy_eggplant_tofu', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明豆瓣茄子豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('spicy_eggplant_tofu', 4, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让豆瓣茄子豆腐状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('spicy_eggplant_tofu', 5, '加入配菜', '加入茄子翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['eggplant']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('spicy_eggplant_tofu', 6, '合炒入味', '把锅中食材合在一起，调味后看到红亮酱香散开但没有糊底。', 'combine_ingredients', array['eggplant', 'tofu', 'doubanjiang']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('spicy_eggplant_tofu', 7, '调整火候', '转中火让豆瓣茄子豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('spicy_eggplant_tofu', 8, '装盘检查', '确认豆瓣茄子豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['eggplant', 'tofu', 'doubanjiang']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('celery_beef_slice', 1, '整理食材', '牛肉片切成薄片或小块，芹菜切成大小接近的块或段，蒜切好备用，看一遍顺序，芹菜牛肉片下锅后就不用临时找东西。', 'prep_ingredients', array['beef_slice', 'celery', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('celery_beef_slice', 2, '清洗沥水', '芹菜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['celery']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('celery_beef_slice', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让芹菜牛肉片状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('celery_beef_slice', 4, '处理主料', '放入牛肉片摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让芹菜牛肉片状态更稳定。', 'sear_meat', array['beef_slice']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('celery_beef_slice', 5, '加入配菜', '加入芹菜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['celery']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('celery_beef_slice', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让芹菜牛肉片状态更稳定。', 'combine_ingredients', array['beef_slice', 'celery', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('celery_beef_slice', 7, '调整火候', '转中火让芹菜牛肉片继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('celery_beef_slice', 8, '盛出收尾', '确认芹菜牛肉片肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['beef_slice', 'celery', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('shandong_garlic_cabbage', 1, '备好配料', '卷心菜切成大小接近的块或段，蒜切好备用，看一遍顺序，醋香蒜炒卷心菜下锅后就不用临时找东西。', 'prep_ingredients', array['cabbage', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('shandong_garlic_cabbage', 2, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让醋香蒜炒卷心菜状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('shandong_garlic_cabbage', 3, '加入配菜', '加入卷心菜翻炒，看到颜色变亮、边缘开始变软但还保留形状，让醋香蒜炒卷心菜状态更稳定。', 'stir_fry', array['cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shandong_garlic_cabbage', 4, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让醋香蒜炒卷心菜状态更稳定。', 'combine_ingredients', array['cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shandong_garlic_cabbage', 5, '出锅确认', '确认醋香蒜炒卷心菜蔬菜颜色变亮，边缘开始变软但仍有支撑感，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('huaiyang_tofu_pea_mushroom', 1, '备齐食材', '豆腐切块后轻轻吸掉表面水分，豌豆、蘑菇切成大小接近的块或段，看一遍顺序，豆腐豌豆蘑菇下锅后就不用临时找东西。', 'prep_ingredients', array['tofu', 'peas', 'mushroom']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('huaiyang_tofu_pea_mushroom', 2, '清洗沥水', '豌豆、蘑菇冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['peas', 'mushroom']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('huaiyang_tofu_pea_mushroom', 3, '热锅铺油', '锅面热后加油，油能流动铺开，说明豆腐豌豆蘑菇可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('huaiyang_tofu_pea_mushroom', 4, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让豆腐豌豆蘑菇状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('huaiyang_tofu_pea_mushroom', 5, '加入配菜', '加入豌豆、蘑菇翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['peas', 'mushroom']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('huaiyang_tofu_pea_mushroom', 6, '合炒入味', '把锅中食材合在一起，调味后看到豆腐豌豆蘑菇的主味均匀裹在食材上。', 'combine_ingredients', array['tofu', 'peas', 'mushroom']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('huaiyang_tofu_pea_mushroom', 7, '调整火候', '转中火让豆腐豌豆蘑菇继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('huaiyang_tofu_pea_mushroom', 8, '整理出餐', '确认豆腐豌豆蘑菇豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['tofu', 'peas', 'mushroom']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('huaiyang_shrimp_tofu', 1, '处理食材', '虾仁沥干到表面不挂水，豆腐切块后轻轻吸掉表面水分，豌豆沥干，看一遍顺序，虾仁豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['shrimp', 'tofu', 'peas']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('huaiyang_shrimp_tofu', 2, '清洗沥水', '豌豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['peas']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('huaiyang_shrimp_tofu', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明虾仁豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('huaiyang_shrimp_tofu', 4, '处理主料', '放入虾仁、豆腐摊开受热，看到虾仁由半透明转粉并自然卷起再翻动或拨到锅边。', 'sear_meat', array['shrimp', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('huaiyang_shrimp_tofu', 5, '加入配菜', '加入豌豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['peas']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('huaiyang_shrimp_tofu', 6, '合炒入味', '把锅中食材合在一起，调味后看到虾仁豆腐的主味均匀裹在食材上。', 'combine_ingredients', array['shrimp', 'tofu', 'peas']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('huaiyang_shrimp_tofu', 7, '调整火候', '转中火让虾仁豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('huaiyang_shrimp_tofu', 8, '装盘检查', '确认虾仁豆腐虾仁由半透明转粉并自然卷起，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['shrimp', 'tofu', 'peas']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('garlic_spinach', 1, '整理食材', '菠菜切成大小接近的块或段，蒜切好备用，看一遍顺序，蒜蓉菠菜下锅后就不用临时找东西。', 'prep_ingredients', array['spinach', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('garlic_spinach', 2, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让蒜蓉菠菜状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
