  ('garlic_spinach', 4, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让蒜蓉菠菜状态更稳定。', 'combine_ingredients', array['spinach', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
