  ('cauliflower_ground_turkey', 1, '备好配料', '火鸡碎拨散，花椰菜切成大小接近的块或段，蒜切好备用，看一遍顺序，火鸡碎炒花椰菜下锅后就不用临时找东西。', 'prep_ingredients', array['cauliflower', 'ground_turkey', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
