  ('cauliflower_ground_turkey', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让火鸡碎炒花椰菜状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('cauliflower_ground_turkey', 4, '处理主料', '放入火鸡碎摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['ground_turkey']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
