  ('cauliflower_ground_turkey', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让火鸡碎炒花椰菜状态更稳定。', 'combine_ingredients', array['cauliflower', 'ground_turkey', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cauliflower_ground_turkey', 7, '调整火候', '转中火让火鸡碎炒花椰菜继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('cauliflower_ground_turkey', 8, '出锅确认', '确认火鸡碎炒花椰菜肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['cauliflower', 'ground_turkey', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('cabbage_chicken_thigh', 1, '备齐食材', '鸡腿肉切成薄片或小块，大白菜切成大小接近的块或段，姜切好备用，看一遍顺序，鸡腿肉炒大白菜下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_thigh', 'napa_cabbage', 'ginger']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
