  ('cabbage_chicken_thigh', 4, '处理主料', '放入鸡腿肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让鸡腿肉炒大白菜状态更稳定。', 'sear_meat', array['chicken_thigh']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
