  ('cabbage_chicken_thigh', 6, '合炒入味', '把锅中食材合在一起，调味后看到葱姜香气出来，锅里没有生辛味，让鸡腿肉炒大白菜状态更稳定。', 'combine_ingredients', array['chicken_thigh', 'napa_cabbage', 'ginger']::text[], array['pan', 'spatula']::text[], 3, null, ''),
