  ('cabbage_chicken_thigh', 8, '整理出餐', '确认鸡腿肉炒大白菜肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_thigh', 'napa_cabbage', 'ginger']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('carrot_potato_chicken', 1, '处理食材', '鸡腿肉切成薄片或小块，土豆、胡萝卜切成大小接近的块或段，看一遍顺序，胡萝卜土豆鸡块下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_thigh', 'potato', 'carrot']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('carrot_potato_chicken', 2, '清洗沥水', '土豆、胡萝卜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['potato', 'carrot']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('carrot_potato_chicken', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明胡萝卜土豆鸡块可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('carrot_potato_chicken', 4, '处理主料', '放入鸡腿肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让胡萝卜土豆鸡块状态更稳定。', 'sear_meat', array['chicken_thigh']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('carrot_potato_chicken', 5, '加入配菜', '加入土豆、胡萝卜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['potato', 'carrot']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('carrot_potato_chicken', 6, '合炒入味', '把锅中食材合在一起，调味后看到胡萝卜土豆鸡块的主味均匀裹在食材上。', 'combine_ingredients', array['chicken_thigh', 'potato', 'carrot']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('carrot_potato_chicken', 7, '调整火候', '转中火让胡萝卜土豆鸡块继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('carrot_potato_chicken', 8, '装盘检查', '确认胡萝卜土豆鸡块肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_thigh', 'potato', 'carrot']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('tomato_cauliflower_egg', 1, '整理食材', '鸡蛋打散到蛋清蛋黄融合，番茄、花椰菜切成大小接近的块或段，看一遍顺序，番茄花菜炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['tomato', 'cauliflower', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('tomato_cauliflower_egg', 2, '清洗沥水', '番茄、花椰菜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['tomato', 'cauliflower']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tomato_cauliflower_egg', 3, '起锅加油', '锅面热后加油，油能流动铺开，说明番茄花菜炒蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('tomato_cauliflower_egg', 4, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让番茄花菜炒蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tomato_cauliflower_egg', 5, '加入配菜', '加入番茄、花椰菜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['tomato', 'cauliflower']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tomato_cauliflower_egg', 6, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄花菜炒蛋状态更稳定。', 'combine_ingredients', array['tomato', 'cauliflower', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tomato_cauliflower_egg', 7, '调整火候', '转中火让番茄花菜炒蛋继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('tomato_cauliflower_egg', 8, '盛出收尾', '确认番茄花菜炒蛋蔬菜颜色变亮，边缘开始变软但仍有支撑感，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['tomato', 'cauliflower', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('mushroom_chicken_breast', 1, '备好配料', '鸡胸肉切成薄片或小块，蘑菇切成大小接近的块或段，蒜切好备用，看一遍顺序，蘑菇鸡胸肉下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_breast', 'mushroom', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('mushroom_chicken_breast', 2, '清洗沥水', '蘑菇冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['mushroom']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('mushroom_chicken_breast', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让蘑菇鸡胸肉状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('mushroom_chicken_breast', 4, '处理主料', '放入鸡胸肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让蘑菇鸡胸肉状态更稳定。', 'sear_meat', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('mushroom_chicken_breast', 5, '加入配菜', '加入蘑菇翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['mushroom']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('mushroom_chicken_breast', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让蘑菇鸡胸肉状态更稳定。', 'combine_ingredients', array['chicken_breast', 'mushroom', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('mushroom_chicken_breast', 7, '调整火候', '转中火让蘑菇鸡胸肉继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('mushroom_chicken_breast', 8, '出锅确认', '确认蘑菇鸡胸肉肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_breast', 'mushroom', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('shrimp_broccoli_garlic', 1, '备齐食材', '虾仁沥干到表面不挂水，西兰花切成大小接近的块或段，蒜切好备用，看一遍顺序，蒜香虾仁西兰花下锅后就不用临时找东西。', 'prep_ingredients', array['shrimp', 'broccoli', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('shrimp_broccoli_garlic', 2, '清洗沥水', '西兰花冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['broccoli']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('shrimp_broccoli_garlic', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让蒜香虾仁西兰花状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('shrimp_broccoli_garlic', 4, '处理主料', '放入虾仁摊开受热，看到虾仁由半透明转粉并自然卷起再翻动或拨到锅边，让蒜香虾仁西兰花状态更稳定。', 'sear_meat', array['shrimp']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('shrimp_broccoli_garlic', 5, '加入配菜', '加入西兰花翻炒，看到颜色变亮、边缘开始变软但还保留形状，让蒜香虾仁西兰花状态更稳定。', 'stir_fry', array['broccoli']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shrimp_broccoli_garlic', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让蒜香虾仁西兰花状态更稳定。', 'combine_ingredients', array['shrimp', 'broccoli', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shrimp_broccoli_garlic', 7, '调整火候', '转中火让蒜香虾仁西兰花继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('shrimp_broccoli_garlic', 8, '整理出餐', '确认蒜香虾仁西兰花虾仁由半透明转粉并自然卷起，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['shrimp', 'broccoli', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('cucumber_egg_light_stir', 1, '处理食材', '鸡蛋打散到蛋清蛋黄融合，黄瓜切好后保持清爽不出水，看一遍顺序，黄瓜炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['cucumber', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('cucumber_egg_light_stir', 2, '热锅下油', '锅面热后加油，油能流动铺开，说明黄瓜炒蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('cucumber_egg_light_stir', 3, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让黄瓜炒蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cucumber_egg_light_stir', 4, '加入配菜', '加入黄瓜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['cucumber']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cucumber_egg_light_stir', 5, '合炒入味', '把锅中食材合在一起，调味后看到黄瓜炒蛋的主味均匀裹在食材上。', 'combine_ingredients', array['cucumber', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cucumber_egg_light_stir', 6, '装盘检查', '确认黄瓜炒蛋蛋液边缘刚凝固、中间仍柔软，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['cucumber', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('bok_choy_mushroom', 1, '整理食材', '小白菜、蘑菇切成大小接近的块或段，蒜切好备用，看一遍顺序，小白菜炒蘑菇下锅后就不用临时找东西。', 'prep_ingredients', array['bok_choy', 'mushroom', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('bok_choy_mushroom', 2, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让小白菜炒蘑菇状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('bok_choy_mushroom', 3, '加入配菜', '加入小白菜、蘑菇翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['bok_choy', 'mushroom']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('bok_choy_mushroom', 4, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让小白菜炒蘑菇状态更稳定。', 'combine_ingredients', array['bok_choy', 'mushroom', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('bok_choy_mushroom', 5, '盛出收尾', '确认小白菜炒蘑菇蔬菜颜色变亮，边缘开始变软但仍有支撑感，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['bok_choy', 'mushroom', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('spicy_cabbage_tofu', 1, '备好配料', '豆腐切块后轻轻吸掉表面水分，卷心菜切成大小接近的块或段，看一遍顺序，辣油卷心菜豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['cabbage', 'tofu', 'chili_oil']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
