  ('spicy_cabbage_tofu', 3, '锅热入油', '锅面热后加油，油能流动铺开，说明辣油卷心菜豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('spicy_cabbage_tofu', 4, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让辣油卷心菜豆腐状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('spicy_cabbage_tofu', 5, '加入配菜', '加入卷心菜翻炒，看到颜色变亮、边缘开始变软但还保留形状，让辣油卷心菜豆腐状态更稳定。', 'stir_fry', array['cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('spicy_cabbage_tofu', 6, '合炒入味', '把锅中食材合在一起，调味后看到红亮酱香散开但没有糊底。', 'combine_ingredients', array['cabbage', 'tofu', 'chili_oil']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('spicy_cabbage_tofu', 7, '调整火候', '转中火让辣油卷心菜豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('spicy_cabbage_tofu', 8, '出锅确认', '确认辣油卷心菜豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['cabbage', 'tofu', 'chili_oil']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('pork_belly_napa_cabbage', 1, '备齐食材', '五花肉切成薄片或小块，大白菜切成大小接近的块或段，蒜切好备用，看一遍顺序，五花肉大白菜下锅后就不用临时找东西。', 'prep_ingredients', array['pork_belly', 'napa_cabbage', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
