  ('pork_belly_napa_cabbage', 4, '处理主料', '放入五花肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['pork_belly']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('pork_belly_napa_cabbage', 5, '加入配菜', '加入大白菜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['napa_cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('pork_belly_napa_cabbage', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让五花肉大白菜状态更稳定。', 'combine_ingredients', array['pork_belly', 'napa_cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
