  ('pork_belly_napa_cabbage', 8, '整理出餐', '确认五花肉大白菜肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['pork_belly', 'napa_cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('zucchini_egg_stir_fry', 1, '处理食材', '鸡蛋打散到蛋清蛋黄融合，西葫芦切成大小接近的块或段，蒜切好备用，看一遍顺序，西葫芦炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['zucchini', 'egg', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('zucchini_egg_stir_fry', 2, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让西葫芦炒蛋状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('zucchini_egg_stir_fry', 3, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让西葫芦炒蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('zucchini_egg_stir_fry', 4, '加入配菜', '加入西葫芦翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['zucchini']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('zucchini_egg_stir_fry', 5, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让西葫芦炒蛋状态更稳定。', 'combine_ingredients', array['zucchini', 'egg', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('zucchini_egg_stir_fry', 6, '装盘检查', '确认西葫芦炒蛋蔬菜颜色变亮，边缘开始变软但仍有支撑感，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['zucchini', 'egg', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('tomato_white_fish_pan', 1, '整理食材', '白鱼擦干并切成厚度接近的块，番茄切成大小接近的块或段，姜切好备用，看一遍顺序，番茄白鱼锅下锅后就不用临时找东西。', 'prep_ingredients', array['white_fish', 'tomato', 'ginger']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('tomato_white_fish_pan', 2, '清洗沥水', '番茄冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低，让番茄白鱼锅状态更稳定。', 'wash_ingredients', array['tomato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tomato_white_fish_pan', 3, '爆出香味', '锅热加油后放姜，闻到香气、边缘微微变色就进入下一步。', 'saute_aromatics', array['ginger']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('tomato_white_fish_pan', 4, '处理主料', '放入白鱼摊开受热，看到鱼肉由透明转白，能轻轻推动但不碎再翻动或拨到锅边。', 'pan_fry', array['white_fish']::text[], array['pan', 'spatula']::text[], 5, null, '鱼类步骤提醒轻推，避免频繁翻面导致散碎。'),
  ('tomato_white_fish_pan', 5, '加入配菜', '加入番茄翻炒，看到颜色变亮、边缘开始变软但还保留形状，让番茄白鱼锅状态更稳定。', 'stir_fry', array['tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tomato_white_fish_pan', 6, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄白鱼锅状态更稳定。', 'combine_ingredients', array['white_fish', 'tomato', 'ginger']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tomato_white_fish_pan', 7, '调整火候', '转中火让番茄白鱼锅继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('tomato_white_fish_pan', 8, '盛出收尾', '确认番茄白鱼锅鱼肉由透明转白，能轻轻推动但不碎，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['white_fish', 'tomato', 'ginger']::text[], array['pan', 'spatula']::text[], 1, null, '')
;

insert into _recipe_tutorial_steps_seed (
  recipe_key, step_number, title, body, action_key, ingredient_keys, equipment_keys, estimated_minutes, timer_seconds, assistant_context
