values
  ('edamame_corn_tofu', 1, '备好配料', '豆腐切块后轻轻吸掉表面水分，毛豆、玉米粒沥干，看一遍顺序，毛豆玉米豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['edamame', 'corn', 'tofu']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('edamame_corn_tofu', 2, '清洗沥水', '毛豆、玉米冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['edamame', 'corn']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('edamame_corn_tofu', 3, '锅热入油', '锅面热后加油，油能流动铺开，说明毛豆玉米豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('edamame_corn_tofu', 4, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让毛豆玉米豆腐状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('edamame_corn_tofu', 5, '加入配菜', '加入毛豆、玉米翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['edamame', 'corn']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('edamame_corn_tofu', 6, '合炒入味', '把锅中食材合在一起，调味后看到毛豆玉米豆腐的主味均匀裹在食材上。', 'combine_ingredients', array['edamame', 'corn', 'tofu']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('edamame_corn_tofu', 7, '调整火候', '转中火让毛豆玉米豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('edamame_corn_tofu', 8, '出锅确认', '确认毛豆玉米豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['edamame', 'corn', 'tofu']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('chicken_egg_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收鸡蛋鸡胸饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('chicken_egg_rice_bowl', 2, '切配浇头', '鸡蛋打散到蛋清蛋黄融合，鸡胸肉切成薄片或小块，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['chicken_breast', 'egg']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('chicken_egg_rice_bowl', 3, '做出底味', '锅热后先处理鸡胸肉、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，让鸡蛋鸡胸饭状态更稳定。', 'sear_meat', array['chicken_breast', 'egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('chicken_egg_rice_bowl', 4, '加入配菜', '加入剩余chicken breast、鸡蛋翻匀，鸡蛋鸡胸饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['chicken_breast', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('chicken_egg_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到鸡蛋鸡胸饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['chicken_breast', 'egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('chicken_egg_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让鸡蛋鸡胸饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_breast', 'egg']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('chicken_egg_rice_bowl', 7, '整理浇头', '把鸡蛋鸡胸饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_egg_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，鸡蛋鸡胸饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'chicken_breast', 'egg']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('beef_tomato_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收番茄牛肉碎盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('beef_tomato_rice_bowl', 2, '切配浇头', '牛肉碎拨散，番茄切成大小接近的块或段，洋葱切好备用，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['ground_beef', 'tomato', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('beef_tomato_rice_bowl', 3, '做出底味', '锅热后先处理牛肉碎，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['ground_beef']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('beef_tomato_rice_bowl', 4, '加入配菜', '加入剩余牛肉碎、tomato、onion翻匀，番茄牛肉碎盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['ground_beef', 'tomato', 'onion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('beef_tomato_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到番茄汁水变浓并包住主料，铲过锅底能短暂露出锅面，让番茄牛肉碎盖饭汤汁更稳定。', 'simmer', array['ground_beef', 'tomato', 'onion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('beef_tomato_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让番茄牛肉碎盖饭状态更稳定。', 'combine_ingredients', array['rice', 'ground_beef', 'tomato', 'onion']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('beef_tomato_rice_bowl', 7, '整理浇头', '把番茄牛肉碎盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_tomato_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，番茄牛肉碎盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'ground_beef', 'tomato', 'onion']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('tofu_vegetable_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收豆腐蔬菜饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('tofu_vegetable_rice_bowl', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，西兰花、胡萝卜切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['tofu', 'broccoli', 'carrot']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('tofu_vegetable_rice_bowl', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让豆腐蔬菜饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_vegetable_rice_bowl', 4, '加入配菜', '加入剩余tofu、broccoli、carrot翻匀，豆腐蔬菜饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['tofu', 'broccoli', 'carrot']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tofu_vegetable_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到豆腐蔬菜饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['tofu', 'broccoli', 'carrot']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_vegetable_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让豆腐蔬菜饭状态更稳定。', 'combine_ingredients', array['rice', 'tofu', 'broccoli', 'carrot']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('tofu_vegetable_rice_bowl', 7, '整理浇头', '把豆腐蔬菜饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('tofu_vegetable_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，豆腐蔬菜饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'tofu', 'broccoli', 'carrot']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('shrimp_corn_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，虾仁玉米炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('shrimp_corn_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，虾仁沥干到表面不挂水，玉米粒沥干，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['shrimp', 'corn', 'egg']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('shrimp_corn_fried_rice', 3, '先炒配料', '锅热加油后先处理虾仁、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，让虾仁玉米炒饭状态更稳定。', 'scramble_eggs', array['shrimp', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shrimp_corn_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让虾仁玉米炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shrimp_corn_fried_rice', 5, '合入配料', '把虾仁、玉米、鸡蛋和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'shrimp', 'corn', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shrimp_corn_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，虾仁玉米炒饭不出现湿团。', 'season', array['rice', 'shrimp', 'corn', 'egg']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('shrimp_corn_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让虾仁玉米炒饭状态更稳定。', 'check_doneness', array['rice', 'shrimp', 'corn', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('shrimp_corn_fried_rice', 8, '盛出炒饭', '把虾仁玉米炒饭盛入碗中，表面能看到配料均匀分布，外观整齐后上桌。', 'plate_dish', array['rice', 'shrimp', 'corn', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('tuna_cucumber_rice_bowl', 1, '松散米饭', '米饭加热或放到温热，压散到没有硬块，金枪鱼黄瓜饭吃起来才不夹生硬饭团。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('tuna_cucumber_rice_bowl', 2, '处理配料', '金枪鱼罐头沥干并拨散，黄瓜切好后保持清爽不出水，生食配料保持清爽，罐头食材不要带太多汤水。', 'prep_ingredients', array['canned_tuna', 'cucumber']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('tuna_cucumber_rice_bowl', 3, '调好拌汁', '把盐、酱油或轻口酱汁先调匀，尝到咸淡柔和再倒入饭碗。', 'mix_sauce', array[]::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_cucumber_rice_bowl', 4, '铺上配料', '把金枪鱼罐头、黄瓜铺在米饭上，颜色和口感分区清楚，拌起来更均匀。', 'combine_ingredients', array['rice', 'canned_tuna', 'cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tuna_cucumber_rice_bowl', 5, '轻拌饭碗', '从碗边往中间轻拌，看到米饭吸到酱汁但金枪鱼罐头、黄瓜仍有形状。', 'toss_salad', array['rice', 'canned_tuna', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_cucumber_rice_bowl', 6, '整理浇头', '把金枪鱼黄瓜饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('tuna_cucumber_rice_bowl', 7, '检查米饭', '拨开米饭看中心没有硬块，金枪鱼黄瓜饭盖上去后能吸汁但仍保持松散。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('tuna_cucumber_rice_bowl', 8, '整理出餐', '确认金枪鱼黄瓜饭不积水、主料分布均匀，就可以直接端出。', 'plate_dish', array['rice', 'canned_tuna', 'cucumber']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('mushroom_spinach_noodles', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让蘑菇菠菜拌面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('mushroom_spinach_noodles', 2, '处理配料', '蘑菇、菠菜切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['mushroom', 'spinach']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('mushroom_spinach_noodles', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给蘑菇菠菜拌面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('mushroom_spinach_noodles', 4, '做出浇头', '锅中处理蘑菇、菠菜，看到蔬菜颜色变亮，边缘开始变软但仍有支撑感再加调味。', 'stir_fry', array['mushroom', 'spinach']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('mushroom_spinach_noodles', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让蘑菇菠菜拌面质地更顺滑。', 'mix_sauce', array['noodles', 'mushroom', 'spinach']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('mushroom_spinach_noodles', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让蘑菇菠菜拌面状态更稳定。', 'combine_ingredients', array['noodles', 'mushroom', 'spinach']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('mushroom_spinach_noodles', 7, '检查口感', '夹起一筷子，面条有弹性、蘑菇、菠菜状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'mushroom', 'spinach']::text[], array['tongs']::text[], 1, null, ''),
