  ('sesame_tofu_noodle_bowl', 2, '处理配料', '豆腐切块后轻轻吸掉表面水分，黄瓜切好后保持清爽不出水，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['tofu', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
