  ('sesame_tofu_noodle_bowl', 4, '做出浇头', '锅中处理豆腐、黄瓜，看到豆腐边缘微黄，轻推时还能保持块状再加调味。', 'stir_fry', array['tofu', 'cucumber']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('sesame_tofu_noodle_bowl', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让芝麻豆腐黄瓜面质地更顺滑。', 'mix_sauce', array['noodles', 'tofu', 'cucumber']::text[], array['pan', 'spatula']::text[], 4, null, ''),
