  ('sesame_tofu_noodle_bowl', 7, '检查口感', '夹起一筷子，面条有弹性、豆腐、黄瓜状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'tofu', 'cucumber']::text[], array['tongs']::text[], 1, null, ''),
  ('sesame_tofu_noodle_bowl', 8, '装碗出餐', '把芝麻豆腐黄瓜面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'tofu', 'cucumber']::text[], array['tongs']::text[], 1, null, ''),
  ('curry_chicken_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收咖喱鸡肉饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('curry_chicken_rice', 2, '切配浇头', '鸡腿肉切成薄片或小块，土豆、胡萝卜切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['chicken_thigh', 'potato', 'carrot', 'curry_blocks']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('curry_chicken_rice', 3, '做出底味', '锅热后先处理鸡腿肉，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['chicken_thigh']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('curry_chicken_rice', 4, '加入配菜', '加入鸡腿肉、土豆、胡萝卜翻匀，咖喱鸡肉饭的浇头变色均匀、锅底水汽减少。', 'stir_fry', array['chicken_thigh', 'potato', 'carrot', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('curry_chicken_rice', 5, '收成浇头', '加调味或少量水，煮到咖喱融开并能挂在食材表面，铲过锅底能短暂露出锅面。', 'simmer', array['chicken_thigh', 'potato', 'carrot', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('curry_chicken_rice', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让咖喱鸡肉饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_thigh', 'potato', 'carrot', 'curry_blocks']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('curry_chicken_rice', 7, '整理浇头', '把咖喱鸡肉饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('curry_chicken_rice', 8, '检查米饭', '拨开米饭看中心没有硬块，咖喱鸡肉饭盖上去后能吸汁但仍保持松散。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('curry_chicken_rice', 9, '分区盖饭', '把主料铺在饭面不同区域，咖喱鸡肉饭每一口都能吃到米饭和浇头。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('curry_chicken_rice', 10, '收拢碗边', '沿碗边整理汤汁，咖喱鸡肉饭不外溢，米饭边缘能看到少量酱汁。', 'plate_dish', array[]::text[], array[]::text[], 1, null, ''),
  ('curry_chicken_rice', 11, '整理浇头', '把咖喱鸡肉饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('curry_chicken_rice', 12, '确认盖饭', '尝一口浇头和饭，咖喱鸡肉饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'chicken_thigh', 'potato', 'carrot', 'curry_blocks']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('vegetable_curry_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收蔬菜咖喱饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('vegetable_curry_rice', 2, '切配浇头', '土豆、胡萝卜切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['potato', 'carrot', 'curry_blocks']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('vegetable_curry_rice', 3, '做出底味', '锅热后先处理土豆、胡萝卜、咖喱块，看到蔬菜颜色变亮，边缘开始变软但仍有支撑感。', 'stir_fry', array['potato', 'carrot', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('vegetable_curry_rice', 4, '加入配菜', '加入剩余potato、carrot、curry blocks翻匀，蔬菜咖喱饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['potato', 'carrot', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('vegetable_curry_rice', 5, '收成浇头', '加调味或少量水，煮到咖喱融开并能挂在食材表面，铲过锅底能短暂露出锅面。', 'simmer', array['potato', 'carrot', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('vegetable_curry_rice', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让蔬菜咖喱饭状态更稳定。', 'combine_ingredients', array['rice', 'potato', 'carrot', 'curry_blocks']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('vegetable_curry_rice', 7, '整理浇头', '把蔬菜咖喱饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('vegetable_curry_rice', 8, '确认盖饭', '尝一口浇头和饭，蔬菜咖喱饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'potato', 'carrot', 'curry_blocks']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('canned_tuna_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，金枪鱼鸡蛋炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('canned_tuna_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，金枪鱼罐头沥干并拨散，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['canned_tuna', 'egg']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('canned_tuna_fried_rice', 3, '先炒配料', '锅热加油后先处理金枪鱼罐头、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，让金枪鱼鸡蛋炒饭状态更稳定。', 'scramble_eggs', array['canned_tuna', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('canned_tuna_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让金枪鱼鸡蛋炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('canned_tuna_fried_rice', 5, '合入配料', '把金枪鱼罐头、鸡蛋和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'canned_tuna', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('canned_tuna_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，金枪鱼鸡蛋炒饭不出现湿团。', 'season', array['rice', 'canned_tuna', 'egg']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('canned_tuna_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让金枪鱼鸡蛋炒饭状态更稳定。', 'check_doneness', array['rice', 'canned_tuna', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('canned_tuna_fried_rice', 8, '盛出炒饭', '把金枪鱼鸡蛋炒饭盛入碗中，表面能看到配料均匀分布。', 'plate_dish', array['rice', 'canned_tuna', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('ground_pork_corn_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收肉末玉米盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('ground_pork_corn_rice_bowl', 2, '切配浇头', '猪肉末拨散，玉米粒沥干，洋葱切好备用，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['ground_pork', 'corn', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('ground_pork_corn_rice_bowl', 3, '做出底味', '锅热后先处理猪肉末，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['ground_pork']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('ground_pork_corn_rice_bowl', 4, '加入配菜', '加入剩余猪肉末、玉米、onion翻匀，肉末玉米盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['ground_pork', 'corn', 'onion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('ground_pork_corn_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到肉末玉米盖饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['ground_pork', 'corn', 'onion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('ground_pork_corn_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让肉末玉米盖饭状态更稳定。', 'combine_ingredients', array['rice', 'ground_pork', 'corn', 'onion']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('ground_pork_corn_rice_bowl', 7, '整理浇头', '把肉末玉米盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('ground_pork_corn_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，肉末玉米盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'ground_pork', 'corn', 'onion']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('ramen_egg_spinach', 1, '烧水备面', '锅中水烧到持续冒泡，再放拉面，这样面条受热更均匀。', 'boil_water', array['ramen_noodles']::text[], array['pot']::text[], 3, null, ''),
  ('ramen_egg_spinach', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，菠菜切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['egg', 'spinach']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('ramen_egg_spinach', 3, '煮到弹牙', '拉面煮到能夹断但中心仍有弹性，捞出后轻轻沥水，再捞出处理。', 'boil_noodles', array['ramen_noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('ramen_egg_spinach', 4, '做出浇头', '锅中处理鸡蛋、菠菜，看到蛋液边缘刚凝固、中间仍柔软再加调味。', 'stir_fry', array['egg', 'spinach']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('ramen_egg_spinach', 5, '兑成汤底', '加入热水或汤底，煮到汤色均匀，菠菜鸡蛋拉面的香味散开。', 'simmer', array['ramen_noodles', 'egg', 'spinach']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('ramen_egg_spinach', 6, '合入面条', '把拉面放回锅里拌开，面条不成团，表面开始均匀挂汁。', 'combine_ingredients', array['ramen_noodles', 'egg', 'spinach']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('ramen_egg_spinach', 7, '检查口感', '夹起一筷子，面条有弹性、鸡蛋、菠菜状态合适，再决定是否补味。', 'check_doneness', array['ramen_noodles', 'egg', 'spinach']::text[], array['tongs']::text[], 1, null, ''),
  ('ramen_egg_spinach', 8, '装碗出餐', '把菠菜鸡蛋拉面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['ramen_noodles', 'egg', 'spinach']::text[], array['tongs']::text[], 1, null, ''),
  ('shrimp_tomato_noodles', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让番茄虾仁面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('shrimp_tomato_noodles', 2, '处理配料', '虾仁沥干到表面不挂水，番茄切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['shrimp', 'tomato']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('shrimp_tomato_noodles', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给番茄虾仁面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('shrimp_tomato_noodles', 4, '做出浇头', '锅中处理虾仁、番茄，看到虾仁由半透明转粉并自然卷起再加调味。', 'stir_fry', array['shrimp', 'tomato']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('shrimp_tomato_noodles', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让番茄虾仁面质地更顺滑。', 'mix_sauce', array['noodles', 'shrimp', 'tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shrimp_tomato_noodles', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让番茄虾仁面状态更稳定。', 'combine_ingredients', array['noodles', 'shrimp', 'tomato']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('shrimp_tomato_noodles', 7, '检查口感', '夹起一筷子，面条有弹性、虾仁、番茄状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'shrimp', 'tomato']::text[], array['tongs']::text[], 1, null, ''),
  ('shrimp_tomato_noodles', 8, '装碗出餐', '把番茄虾仁面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'shrimp', 'tomato']::text[], array['tongs']::text[], 1, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 1, '淘米加水', '把米淘到水色变清，按平时口感加水，米面铺平再放配料，让电饭煲鸡腿蔬菜饭米粒更稳定。', 'cook_rice', array['rice']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 2, '处理配料', '鸡腿肉切成薄片或小块，胡萝卜切成大小接近的块或段，洋葱切好备用，铺进电饭煲时尽量均匀，不要集中在一角。', 'cut_meat', array['chicken_thigh', 'carrot', 'onion']::text[], array['knife', 'cutting_board']::text[], 8, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 3, '铺料调味', '把鸡腿肉、胡萝卜、洋葱铺在米上，加调味后液面看起来均匀。', 'combine_ingredients', array['rice', 'chicken_thigh', 'carrot', 'onion']::text[], array['rice_cooker']::text[], 3, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 4, '启动煮饭', '按煮饭键加热，跳保温后不要立刻开盖，让水汽继续回到米粒里，让电饭煲鸡腿蔬菜饭米粒更稳定。', 'cook_rice', array['rice', 'chicken_thigh', 'carrot', 'onion']::text[], array['rice_cooker']::text[], 30, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 5, '焖后开盖', '焖几分钟再开盖，看到电饭煲鸡腿蔬菜饭米粒饱满、配料香气明显。', 'rest_food', array['rice', 'chicken_thigh', 'carrot', 'onion']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 6, '翻松米饭', '从锅边往中间翻松，米粒和配料分布均匀，不要把软料压碎，让电饭煲鸡腿蔬菜饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_thigh', 'carrot', 'onion']::text[], array['rice_cooker', 'spatula']::text[], 3, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 7, '检查水位', '合盖前看电饭煲鸡腿蔬菜饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 8, '焖饭吸味', '跳保温后让电饭煲鸡腿蔬菜饭继续焖一会儿，米粒会更容易吸到配料香气。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 9, '检查锅底', '翻动前看锅底没有明显积水，电饭煲鸡腿蔬菜饭米粒边缘已经饱满。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 10, '分散配料', '从锅边往中间翻，电饭煲鸡腿蔬菜饭配料分散开，软料不要被压成泥。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 11, '检查水位', '合盖前看电饭煲鸡腿蔬菜饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_rice_cooker_pilaf', 12, '确认盛出', '尝一口米饭软硬合适，电饭煲鸡腿蔬菜饭底部没有明显积水即可盛出。', 'check_doneness', array['rice', 'chicken_thigh', 'carrot', 'onion']::text[], array['rice_cooker']::text[], 1, null, ''),
  ('tofu_bok_choy_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收小白菜豆腐盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('tofu_bok_choy_rice_bowl', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，小白菜切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['tofu', 'bok_choy']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('tofu_bok_choy_rice_bowl', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让小白菜豆腐盖饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_bok_choy_rice_bowl', 4, '加入配菜', '加入剩余tofu、bok choy翻匀，小白菜豆腐盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['tofu', 'bok_choy']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tofu_bok_choy_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到小白菜豆腐盖饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['tofu', 'bok_choy']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_bok_choy_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让小白菜豆腐盖饭状态更稳定。', 'combine_ingredients', array['rice', 'tofu', 'bok_choy']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('tofu_bok_choy_rice_bowl', 7, '整理浇头', '把小白菜豆腐盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('tofu_bok_choy_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，小白菜豆腐盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'tofu', 'bok_choy']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('beef_shank_noodle_soup', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让牛腱汤面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('beef_shank_noodle_soup', 2, '处理配料', '牛腱切成薄片或小块，姜、葱花切好备用，配料状态先准备好，避免面条煮好后久放成团。', 'cut_meat', array['beef_shank', 'ginger', 'scallion']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('beef_shank_noodle_soup', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给牛腱汤面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('beef_shank_noodle_soup', 4, '做出浇头', '锅中处理牛腱、姜、葱花，看到肉类表面变色，锅底水汽明显减少再加调味。', 'sear_meat', array['beef_shank', 'ginger', 'scallion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('beef_shank_noodle_soup', 5, '兑成汤底', '加入热水或汤底，煮到汤色均匀，牛腱汤面的香味散开。', 'simmer', array['noodles', 'beef_shank', 'ginger', 'scallion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('beef_shank_noodle_soup', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让牛腱汤面状态更稳定。', 'combine_ingredients', array['noodles', 'beef_shank', 'ginger', 'scallion']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('beef_shank_noodle_soup', 7, '检查口感', '夹起一筷子，面条有弹性、牛腱、姜状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'beef_shank', 'ginger', 'scallion']::text[], array['tongs']::text[], 1, null, ''),
  ('beef_shank_noodle_soup', 8, '保留挂汁', '用少量面水调整牛腱汤面，面条表面有薄汁但碗底不积清水。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_shank_noodle_soup', 9, '拨散面条', '用筷子把牛腱汤面挑散，面条之间不粘连，配料能穿插在中间。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_shank_noodle_soup', 10, '检查汤汁', '观察牛腱汤面汤汁或酱汁浓淡，能挂在面上但不会糊成一团。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_shank_noodle_soup', 11, '补足香气', '出锅前补一点葱花或调味，牛腱汤面香气集中后再装碗。', 'season', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_shank_noodle_soup', 12, '装碗出餐', '把牛腱汤面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'beef_shank', 'ginger', 'scallion']::text[], array['tongs']::text[], 1, null, ''),
