  ('chicken_broccoli_pasta', 2, '处理配料', '鸡胸肉切成薄片或小块，西兰花切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'cut_meat', array['chicken_breast', 'broccoli']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
