  ('spinach_egg_toast', 1, '备好底胚', '面包放平，边缘没有破口或过湿，后面夹馅才不容易散开，让菠菜鸡蛋吐司状态更稳定。', 'prep_ingredients', array['bread']::text[], array['cutting_board']::text[], 1, null, ''),
  ('spinach_egg_toast', 2, '处理夹馅', '鸡蛋打散到蛋清蛋黄融合，菠菜切成大小接近的块或段，水分控制住，菠菜鸡蛋吐司卷起来才更稳。', 'slice_vegetables', array['egg', 'spinach']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('spinach_egg_toast', 3, '处理熟馅', '把需要加热的鸡蛋处理到蛋液边缘刚凝固、中间仍柔软，放到不烫手再组合，让菠菜鸡蛋吐司状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('spinach_egg_toast', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免菠菜鸡蛋吐司一卷就往外溢。', 'mix_sauce', array['bread', 'egg', 'spinach']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('spinach_egg_toast', 5, '铺料卷起', '把鸡蛋、菠菜放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['bread', 'egg', 'spinach']::text[], array['cutting_board']::text[], 3, null, ''),
