  ('chicken_avocado_wrap', 5, '铺料卷起', '把鸡胸肉、牛油果放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'chicken_breast', 'avocado']::text[], array['cutting_board']::text[], 3, null, ''),
  ('chicken_avocado_wrap', 6, '切分检查', '切开后看馅料没有集中滑出，鸡胸牛油果卷饼拿起时不松散即可。', 'plate_dish', array['tortilla', 'chicken_breast', 'avocado']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('black_bean_corn_wrap', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让黑豆玉米卷饼状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('black_bean_corn_wrap', 2, '处理夹馅', '黑豆罐头沥干并拨散，玉米粒沥干，水分控制住，黑豆玉米卷饼卷起来才更稳。', 'slice_vegetables', array['canned_black_beans', 'corn']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('black_bean_corn_wrap', 3, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免黑豆玉米卷饼一卷就往外溢。', 'mix_sauce', array['tortilla', 'canned_black_beans', 'corn']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('black_bean_corn_wrap', 4, '铺料卷起', '把黑豆罐头、玉米放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'canned_black_beans', 'corn']::text[], array['cutting_board']::text[], 3, null, ''),
  ('black_bean_corn_wrap', 5, '切分检查', '切开后看馅料没有集中滑出，黑豆玉米卷饼拿起时不松散即可。', 'plate_dish', array['tortilla', 'canned_black_beans', 'corn']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('chickpea_cucumber_salad_wrap', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让鹰嘴豆黄瓜卷饼状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('chickpea_cucumber_salad_wrap', 2, '处理夹馅', '鹰嘴豆罐头沥干并拨散，黄瓜切好后保持清爽不出水，水分控制住，鹰嘴豆黄瓜卷饼卷起来才更稳。', 'slice_vegetables', array['canned_chickpeas', 'cucumber']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('chickpea_cucumber_salad_wrap', 3, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免鹰嘴豆黄瓜卷饼一卷就往外溢。', 'mix_sauce', array['tortilla', 'canned_chickpeas', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('chickpea_cucumber_salad_wrap', 4, '铺料卷起', '把鹰嘴豆罐头、黄瓜放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'canned_chickpeas', 'cucumber']::text[], array['cutting_board']::text[], 3, null, ''),
