insert into _recipe_tutorial_steps_seed (
  recipe_key, step_number, title, body, action_key, ingredient_keys, equipment_keys, estimated_minutes, timer_seconds, assistant_context
)
values
  ('salmon_potato_plate', 1, '擦干食材', '三文鱼擦干并切成厚度接近的块，土豆、西兰花切成大小接近的块或段，表面水分少一点，三文鱼土豆盘边缘更容易变干爽。', 'prep_ingredients', array['salmon', 'potato', 'broccoli']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('salmon_potato_plate', 2, '抓匀调味', '加少量油、盐和调味料抓匀，食材表面能看到薄薄一层油光，让三文鱼土豆盘味道更均匀。', 'season', array['salmon', 'potato', 'broccoli']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('salmon_potato_plate', 3, '平铺炸篮', '把食材放进炸篮，尽量单层铺开，边缘留出热风流动空间，让三文鱼土豆盘受热更均匀。', 'air_fry', array['salmon', 'potato', 'broccoli']::text[], array['air_fryer']::text[], 2, null, ''),
  ('salmon_potato_plate', 4, '中途翻动', '加热到边缘开始上色时翻动一次，鱼肉由透明转白，能轻轻推动但不碎。', 'air_fry', array['salmon', 'potato', 'broccoli']::text[], array['air_fryer', 'tongs']::text[], 12, null, ''),
  ('salmon_potato_plate', 5, '出篮静置', '三文鱼土豆盘外层干爽、中心状态合适后取出，静置片刻再装盘。', 'rest_food', array['salmon', 'potato', 'broccoli']::text[], array['air_fryer', 'tongs']::text[], 2, null, ''),
  ('cod_tomato_pan', 1, '备齐食材', '鳕鱼擦干并切成厚度接近的块，番茄罐头沥干并拨散，洋葱切好备用，看一遍顺序，番茄鳕鱼锅下锅后就不用临时找东西。', 'prep_ingredients', array['cod', 'canned_tomato', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('cod_tomato_pan', 2, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让番茄鳕鱼锅状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('cod_tomato_pan', 3, '处理主料', '放入鳕鱼摊开受热，看到鱼肉由透明转白，能轻轻推动但不碎再翻动或拨到锅边。', 'pan_fry', array['cod']::text[], array['pan', 'spatula']::text[], 5, null, '鱼类步骤提醒轻推，避免频繁翻面导致散碎。'),
  ('cod_tomato_pan', 4, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄鳕鱼锅状态更稳定。', 'combine_ingredients', array['cod', 'canned_tomato', 'onion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cod_tomato_pan', 5, '调整火候', '转中火让番茄鳕鱼锅继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('cod_tomato_pan', 6, '观察主料', '夹起主要食材看颜色和质地，番茄鳕鱼锅没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('cod_tomato_pan', 7, '回锅收味', '把边缘食材推回锅心，番茄鳕鱼锅味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('cod_tomato_pan', 8, '整理出餐', '确认番茄鳕鱼锅鱼肉由透明转白，能轻轻推动但不碎，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['cod', 'canned_tomato', 'onion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('turkey_mushroom_pasta', 1, '烧水备面', '锅中水烧到持续冒泡，再放意面，这样面条受热更均匀，让火鸡蘑菇意面受热更均匀。', 'boil_water', array['pasta']::text[], array['pot']::text[], 3, null, ''),
  ('turkey_mushroom_pasta', 2, '处理配料', '火鸡碎拨散，蘑菇切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'cut_meat', array['ground_turkey', 'mushroom', 'pasta_sauce']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('turkey_mushroom_pasta', 3, '煮到弹牙', '意面煮到能夹断但中心仍有弹性，留一小勺面水再沥出，给火鸡蘑菇意面保留弹性。', 'boil_noodles', array['pasta']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('turkey_mushroom_pasta', 4, '做出浇头', '锅中处理火鸡碎、蘑菇、意面酱，看到肉类表面变色，锅底水汽明显减少再加调味。', 'sear_meat', array['ground_turkey', 'mushroom', 'pasta_sauce']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('turkey_mushroom_pasta', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让火鸡蘑菇意面质地更顺滑。', 'mix_sauce', array['pasta', 'ground_turkey', 'mushroom', 'pasta_sauce']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('turkey_mushroom_pasta', 6, '合入面条', '把意面放回锅里拌开，面条不成团，表面开始均匀挂汁，让火鸡蘑菇意面状态更稳定。', 'combine_ingredients', array['pasta', 'ground_turkey', 'mushroom', 'pasta_sauce']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('turkey_mushroom_pasta', 7, '检查口感', '夹起一筷子，面条有弹性、火鸡碎、蘑菇状态合适，再决定是否补味。', 'check_doneness', array['pasta', 'ground_turkey', 'mushroom', 'pasta_sauce']::text[], array['tongs']::text[], 1, null, ''),
  ('turkey_mushroom_pasta', 8, '装碗出餐', '把火鸡蘑菇意面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['pasta', 'ground_turkey', 'mushroom', 'pasta_sauce']::text[], array['tongs']::text[], 1, null, ''),
  ('sausage_pepper_tortilla', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让香肠彩椒卷饼状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('sausage_pepper_tortilla', 2, '处理夹馅', '彩椒切成大小接近的块或段，洋葱切好备用，水分控制住，香肠彩椒卷饼卷起来才更稳。', 'cut_meat', array['sausage', 'bell_pepper', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('sausage_pepper_tortilla', 3, '处理熟馅', '把需要加热的香肠处理到肉类表面变色，锅底水汽明显减少，放到不烫手再组合。', 'pan_fry', array['sausage']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('sausage_pepper_tortilla', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免香肠彩椒卷饼一卷就往外溢。', 'mix_sauce', array['tortilla', 'sausage', 'bell_pepper', 'onion']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('sausage_pepper_tortilla', 5, '铺料卷起', '把香肠、彩椒、洋葱放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'sausage', 'bell_pepper', 'onion']::text[], array['cutting_board']::text[], 3, null, ''),
  ('sausage_pepper_tortilla', 6, '切分检查', '切开后看馅料没有集中滑出，香肠彩椒卷饼拿起时不松散即可。', 'plate_dish', array['tortilla', 'sausage', 'bell_pepper', 'onion']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('banana_oat_pancake', 1, '调成面糊', '鸡蛋打散到蛋清蛋黄融合，香蕉切好后保持清爽不出水，把面糊拌到能缓慢流动，没有大片干粉。', 'mix_sauce', array['banana', 'oats', 'egg']::text[], array['mixing_bowl']::text[], 4, null, ''),
  ('banana_oat_pancake', 2, '热锅薄油', '平底锅加热后薄薄抹油，面糊落下能轻微定住边缘，说明香蕉燕麦煎饼可以开始摊饼。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('banana_oat_pancake', 3, '摊成圆饼', '倒入面糊摊开，看到香蕉燕麦煎饼边缘变干、中间有小气泡。', 'pan_fry', array['banana', 'oats', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('banana_oat_pancake', 4, '翻面煎透', '轻推香蕉燕麦煎饼能移动时翻面，另一面出现浅色焦点，饼身不湿黏即可离火。', 'pan_fry', array['banana', 'oats', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('banana_oat_pancake', 5, '切分上桌', '把香蕉燕麦煎饼切成方便入口的大小，内部不湿黏时装盘。', 'plate_dish', array['banana', 'oats', 'egg']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('apple_oat_bowl', 1, '切配入碗', '苹果切好后保持清爽不出水，放进微波容器后铺平，中间不要堆太厚。', 'prep_ingredients', array['oats', 'apple']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('apple_oat_bowl', 2, '加盖留缝', '容器盖上盖子或保鲜膜并留小缝，苹果燕麦碗加热时水汽能散出。', 'microwave', array['oats', 'apple']::text[], array['microwave']::text[], 1, null, ''),
  ('apple_oat_bowl', 3, '分段微波', '先短时间加热，取出搅动或翻面，中心冒热气后再判断是否补热，让苹果燕麦碗状态更稳定。', 'microwave', array['oats', 'apple']::text[], array['microwave']::text[], 4, null, ''),
  ('apple_oat_bowl', 4, '拌入调味', '加入调味后拌匀，看到苹果燕麦碗表面湿润但碗底不积太多水。', 'season', array['oats', 'apple']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('apple_oat_bowl', 5, '静置再吃', '静置片刻让苹果燕麦碗热度均匀，边缘不再滚烫，表面仍保持湿润时上桌。', 'rest_food', array['oats', 'apple']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('berry_granola_bowl', 1, '清洗沥干', '格兰诺拉、浆果处理后沥干，叶菜或水果表面不挂水，确认状态后继续。', 'wash_ingredients', array['granola', 'berries']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('berry_granola_bowl', 2, '切成入口', '浆果切好后保持清爽不出水，大小适合一勺入口，确认状态后继续。', 'slice_vegetables', array['granola', 'berries']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('berry_granola_bowl', 3, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进浆果格兰诺拉碗里。', 'mix_sauce', array['granola', 'berries']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('berry_granola_bowl', 4, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让浆果格兰诺拉碗保持清爽。', 'toss_salad', array['granola', 'berries']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('berry_granola_bowl', 5, '装盘检查', '浆果格兰诺拉碗看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['granola', 'berries']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('peanut_butter_apple_oats', 1, '切配入碗', '苹果切好后保持清爽不出水，放进微波容器后铺平，中间不要堆太厚。', 'prep_ingredients', array['oats', 'apple', 'peanut_butter']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('peanut_butter_apple_oats', 2, '加盖留缝', '容器盖上盖子或保鲜膜并留小缝，花生酱苹果燕麦加热时水汽能散出。', 'microwave', array['oats', 'apple', 'peanut_butter']::text[], array['microwave']::text[], 1, null, ''),
  ('peanut_butter_apple_oats', 3, '分段微波', '先短时间加热，取出搅动或翻面，中心冒热气后再判断是否补热，让花生酱苹果燕麦状态更稳定。', 'microwave', array['oats', 'apple', 'peanut_butter']::text[], array['microwave']::text[], 4, null, ''),
  ('peanut_butter_apple_oats', 4, '拌入调味', '加入调味后拌匀，看到花生酱苹果燕麦表面湿润但碗底不积太多水。', 'season', array['oats', 'apple', 'peanut_butter']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('peanut_butter_apple_oats', 5, '静置再吃', '静置片刻让花生酱苹果燕麦热度均匀，边缘不再滚烫，表面仍保持湿润时上桌。', 'rest_food', array['oats', 'apple', 'peanut_butter']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('sweet_potato_egg_hash', 1, '切配早餐', '鸡蛋打散到蛋清蛋黄融合，红薯切成大小接近的块或段，洋葱切好备用，大小接近，早晨快手处理时不容易漏步骤。', 'prep_ingredients', array['sweet_potato', 'egg', 'onion']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('sweet_potato_egg_hash', 2, '热锅处理', '锅热后先放需要加热的食材，看到蔬菜颜色变亮，边缘开始变软但仍有支撑感。', 'pan_fry', array['sweet_potato', 'egg', 'onion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('sweet_potato_egg_hash', 3, '合在一起', '把红薯鸡蛋早餐锅的主料合在锅里，翻到颜色均匀、没有明显生硬块。', 'combine_ingredients', array['sweet_potato', 'egg', 'onion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('sweet_potato_egg_hash', 4, '确认出餐', '尝一口确认口感，红薯鸡蛋早餐锅不湿塌也不干硬时盛出。', 'plate_dish', array['sweet_potato', 'egg', 'onion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('avocado_egg_bread', 1, '备好底胚', '面包放平，边缘没有破口或过湿，后面夹馅才不容易散开，让牛油果鸡蛋面包状态更稳定。', 'prep_ingredients', array['bread']::text[], array['cutting_board']::text[], 1, null, ''),
  ('avocado_egg_bread', 2, '处理夹馅', '鸡蛋打散到蛋清蛋黄融合，牛油果切好后保持清爽不出水，水分控制住，牛油果鸡蛋面包卷起来才更稳。', 'slice_vegetables', array['avocado', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('avocado_egg_bread', 3, '处理熟馅', '把需要加热的鸡蛋处理到蛋液边缘刚凝固、中间仍柔软，放到不烫手再组合，让牛油果鸡蛋面包状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('avocado_egg_bread', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免牛油果鸡蛋面包一卷就往外溢。', 'mix_sauce', array['bread', 'avocado', 'egg']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('avocado_egg_bread', 5, '铺料卷起', '把牛油果、鸡蛋放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['bread', 'avocado', 'egg']::text[], array['cutting_board']::text[], 3, null, ''),
  ('avocado_egg_bread', 6, '切分检查', '切开后看馅料没有集中滑出，牛油果鸡蛋面包拿起时不松散即可。', 'plate_dish', array['bread', 'avocado', 'egg']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('mango_oat_smoothie_bowl', 1, '处理水果', '芒果、香蕉切好后保持清爽不出水，水果块不要太大，搅打时更容易形成顺滑质地。', 'slice_vegetables', array['oats', 'mango', 'banana']::text[], array['knife', 'cutting_board']::text[], 3, null, ''),
  ('mango_oat_smoothie_bowl', 2, '加入杯中', '把燕麦、芒果、香蕉放入搅拌杯，干湿食材分层放，刀头附近先有湿润食材。', 'combine_ingredients', array['oats', 'mango', 'banana']::text[], array['blender']::text[], 2, null, ''),
  ('mango_oat_smoothie_bowl', 3, '搅打顺滑', '启动搅拌到芒果燕麦奶昔碗看不到大块水果，表面变得浓稠细腻。', 'combine_ingredients', array['oats', 'mango', 'banana']::text[], array['blender']::text[], 2, null, ''),
  ('mango_oat_smoothie_bowl', 4, '倒入碗中', '倒出后用勺子整理表面，质地能缓慢流动但不是清水状。', 'plate_dish', array['oats', 'mango', 'banana']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('mango_oat_smoothie_bowl', 5, '补上配料', '按喜好撒上少量燕麦或水果，芒果燕麦奶昔碗表面不塌陷即可。', 'plate_dish', array['oats', 'mango', 'banana']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('egg_corn_cucumber_salad', 1, '清洗沥干', '鸡蛋、玉米、黄瓜处理后沥干，叶菜或水果表面不挂水。', 'wash_ingredients', array['egg', 'corn', 'cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('egg_corn_cucumber_salad', 2, '处理蛋白', '把鸡蛋处理到蛋液边缘刚凝固、中间仍柔软，放凉一点再进沙拉。', 'boil_water', array['egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('egg_corn_cucumber_salad', 3, '切成入口', '玉米粒沥干，黄瓜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['egg', 'corn', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('egg_corn_cucumber_salad', 4, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进鸡蛋玉米黄瓜沙拉里。', 'mix_sauce', array['egg', 'corn', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('egg_corn_cucumber_salad', 5, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让鸡蛋玉米黄瓜沙拉保持清爽。', 'toss_salad', array['egg', 'corn', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('egg_corn_cucumber_salad', 6, '装盘检查', '鸡蛋玉米黄瓜沙拉看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['egg', 'corn', 'cucumber']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('tuna_apple_salad_bread', 1, '清洗沥干', '苹果、面包处理后沥干，叶菜或水果表面不挂水，确认状态后继续。', 'wash_ingredients', array['canned_tuna', 'apple', 'bread']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tuna_apple_salad_bread', 2, '沥干罐头', '金枪鱼罐头沥掉多余汤水并拨散，拌入后不容易让沙拉出水。', 'prep_ingredients', array['canned_tuna']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_apple_salad_bread', 3, '切成入口', '金枪鱼罐头沥干并拨散，苹果切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['canned_tuna', 'apple', 'bread']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('tuna_apple_salad_bread', 4, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进金枪鱼苹果沙拉配面包里。', 'mix_sauce', array['canned_tuna', 'apple', 'bread']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_apple_salad_bread', 5, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让金枪鱼苹果沙拉配面包保持清爽。', 'toss_salad', array['canned_tuna', 'apple', 'bread']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_apple_salad_bread', 6, '装盘检查', '金枪鱼苹果沙拉配面包看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['canned_tuna', 'apple', 'bread']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('mixed_nuts_fruit_toast', 1, '备好底胚', '面包放平，边缘没有破口或过湿，后面夹馅才不容易散开，让坚果水果吐司状态更稳定。', 'prep_ingredients', array['bread']::text[], array['cutting_board']::text[], 1, null, ''),
  ('mixed_nuts_fruit_toast', 2, '处理夹馅', '坚果切成大小接近的块或段，香蕉切好后保持清爽不出水，水分控制住，坚果水果吐司卷起来才更稳。', 'slice_vegetables', array['banana', 'mixed_nuts']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('mixed_nuts_fruit_toast', 3, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免坚果水果吐司一卷就往外溢。', 'mix_sauce', array['bread', 'banana', 'mixed_nuts']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('mixed_nuts_fruit_toast', 4, '铺料卷起', '把香蕉、坚果放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['bread', 'banana', 'mixed_nuts']::text[], array['cutting_board']::text[], 3, null, ''),
  ('mixed_nuts_fruit_toast', 5, '切分检查', '切开后看馅料没有集中滑出，坚果水果吐司拿起时不松散即可。', 'plate_dish', array['bread', 'banana', 'mixed_nuts']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('tomato_tofu_soup', 1, '切配汤料', '鸡蛋打散到蛋清蛋黄融合，豆腐切块后轻轻吸掉表面水分，番茄切成大小接近的块或段，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['tomato', 'tofu', 'egg']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('tomato_tofu_soup', 2, '先出香味', '锅中少量油处理豆腐、鸡蛋，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['tomato', 'tofu', 'egg']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('tomato_tofu_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让番茄豆腐蛋汤受热更均匀。', 'boil_water', array['tomato', 'tofu', 'egg']::text[], array['pot']::text[], 4, null, ''),
  ('tomato_tofu_soup', 4, '先煮耐煮', '先把番茄煮到出汁，汤底出现浅红色，再放豆腐会更入味。', 'simmer', array['tomato', 'tofu', 'egg']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('tomato_tofu_soup', 5, '再下易熟', '加入豆腐、鸡蛋，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['tomato', 'tofu', 'egg']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('tomato_tofu_soup', 6, '观察汤色', '小火煮到番茄豆腐蛋汤汤色更融合，主料状态达到豆腐边缘微黄，轻推时还能保持块状。', 'check_doneness', array['tomato', 'tofu', 'egg']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('tomato_tofu_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让番茄豆腐蛋汤味道更均匀。', 'season', array['tomato', 'tofu', 'egg']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('tomato_tofu_soup', 8, '盛出汤品', '把番茄豆腐蛋汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['tomato', 'tofu', 'egg']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('cabbage_pork_soup', 1, '切配汤料', '猪肉片切成薄片或小块，卷心菜切成大小接近的块或段，姜切好备用，块头不要太大，汤里入口会更顺。', 'cut_meat', array['cabbage', 'pork_slice', 'ginger']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('cabbage_pork_soup', 2, '先出香味', '锅中少量油处理姜，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('cabbage_pork_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让卷心菜肉片汤受热更均匀。', 'boil_water', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot']::text[], 4, null, ''),
  ('cabbage_pork_soup', 4, '先煮耐煮', '先让肉片在汤里散开，表面变色后再下卷心菜，汤味更清楚。', 'simmer', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('cabbage_pork_soup', 5, '再下易熟', '加入易熟食材，轻轻推开，避免把嫩食材搅碎，确认状态后继续，让卷心菜肉片汤状态更稳定。', 'combine_ingredients', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('cabbage_pork_soup', 6, '观察汤色', '小火煮到卷心菜肉片汤汤色更融合，主料状态达到肉类表面变色，锅底水汽明显减少。', 'check_doneness', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('cabbage_pork_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让卷心菜肉片汤味道更均匀。', 'season', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('cabbage_pork_soup', 8, '盛出汤品', '把卷心菜肉片汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['cabbage', 'pork_slice', 'ginger']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('chicken_corn_potato_soup', 1, '切配汤料', '鸡腿肉切成薄片或小块，土豆切块，玉米粒沥干，块头不要太大，汤里入口会更顺。', 'cut_meat', array['chicken_thigh', 'potato', 'corn']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('chicken_corn_potato_soup', 2, '先出香味', '锅中少量油处理鸡腿肉，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['chicken_thigh', 'potato', 'corn']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('chicken_corn_potato_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让鸡肉玉米土豆汤受热更均匀。', 'boil_water', array['chicken_thigh', 'potato', 'corn']::text[], array['pot']::text[], 4, null, ''),
  ('chicken_corn_potato_soup', 4, '先煮耐煮', '先放土豆、鸡腿肉，煮到边缘开始变软，汤色稳定后继续。', 'simmer', array['chicken_thigh', 'potato', 'corn']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('chicken_corn_potato_soup', 5, '再下易熟', '加入玉米，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['chicken_thigh', 'potato', 'corn']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('chicken_corn_potato_soup', 6, '观察汤色', '小火煮到鸡肉玉米土豆汤汤色更融合，主料状态达到肉类表面变色，锅底水汽明显减少。', 'check_doneness', array['chicken_thigh', 'potato', 'corn']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('chicken_corn_potato_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让鸡肉玉米土豆汤味道更均匀。', 'season', array['chicken_thigh', 'potato', 'corn']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('chicken_corn_potato_soup', 8, '撇去浮沫', '看到鸡肉玉米土豆汤汤面有浮沫时轻轻撇开，汤色会更清楚。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_corn_potato_soup', 9, '小火融合', '保持小火让鸡肉玉米土豆汤汤味融合，汤面平稳冒泡，主料不会被冲散。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_corn_potato_soup', 10, '检查软度', '用勺子轻压耐煮食材，鸡肉玉米土豆汤能被压动但没有完全散开。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_corn_potato_soup', 11, '静置入味', '关火后让鸡肉玉米土豆汤短暂静置，汤味回到食材里，再准备盛出。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_corn_potato_soup', 12, '盛出汤品', '把鸡肉玉米土豆汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['chicken_thigh', 'potato', 'corn']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('chickpea_tomato_stew', 1, '切配汤料', '鹰嘴豆罐头、番茄罐头沥干并拨散，洋葱切好备用，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('chickpea_tomato_stew', 2, '先出香味', '锅中少量油处理洋葱，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('chickpea_tomato_stew', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让鹰嘴豆番茄炖菜受热更均匀。', 'boil_water', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot']::text[], 4, null, ''),
  ('chickpea_tomato_stew', 4, '先煮耐煮', '先放鹰嘴豆罐头，煮到边缘开始变软，汤色稳定后继续。', 'simmer', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('chickpea_tomato_stew', 5, '再下易熟', '加入易熟食材，轻轻推开，避免把嫩食材搅碎，确认状态后继续，让鹰嘴豆番茄炖菜状态更稳定。', 'combine_ingredients', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('chickpea_tomato_stew', 6, '观察汤色', '小火煮到鹰嘴豆番茄炖菜汤色更融合，主料状态达到罐头食材热透或拌匀，不需要久炒。', 'check_doneness', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('chickpea_tomato_stew', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让鹰嘴豆番茄炖菜味道更均匀。', 'season', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('chickpea_tomato_stew', 8, '盛出汤品', '把鹰嘴豆番茄炖菜连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['canned_chickpeas', 'canned_tomato', 'onion']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('white_fish_tofu_soup', 1, '切配汤料', '白鱼擦干并切成厚度接近的块，豆腐切块后轻轻吸掉表面水分，姜切好备用，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['white_fish', 'tofu', 'ginger']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('white_fish_tofu_soup', 2, '先出香味', '锅中少量油处理姜，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['white_fish', 'tofu', 'ginger']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('white_fish_tofu_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让白鱼豆腐汤受热更均匀。', 'boil_water', array['white_fish', 'tofu', 'ginger']::text[], array['pot']::text[], 4, null, ''),
  ('white_fish_tofu_soup', 4, '先煮耐煮', '先让姜味进入汤底，再放白鱼和豆腐，后面轻推就不容易碎。', 'simmer', array['white_fish', 'tofu', 'ginger']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('white_fish_tofu_soup', 5, '再下易熟', '加入白鱼、豆腐，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['white_fish', 'tofu', 'ginger']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('white_fish_tofu_soup', 6, '观察汤色', '小火煮到白鱼豆腐汤汤色更融合，主料状态达到鱼肉由透明转白，能轻轻推动但不碎。', 'check_doneness', array['white_fish', 'tofu', 'ginger']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('white_fish_tofu_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让白鱼豆腐汤味道更均匀。', 'season', array['white_fish', 'tofu', 'ginger']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('white_fish_tofu_soup', 8, '盛出汤品', '把白鱼豆腐汤连汤带料盛出，碗里汤料比例均匀即可，外观整齐后上桌。', 'plate_dish', array['white_fish', 'tofu', 'ginger']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('shrimp_corn_egg_soup', 1, '切配汤料', '鸡蛋打散到蛋清蛋黄融合，虾仁沥干到表面不挂水，玉米粒沥干，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['shrimp', 'corn', 'egg']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('shrimp_corn_egg_soup', 2, '先出香味', '锅中少量油处理虾仁、鸡蛋，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['shrimp', 'corn', 'egg']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('shrimp_corn_egg_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让虾仁玉米蛋花汤受热更均匀。', 'boil_water', array['shrimp', 'corn', 'egg']::text[], array['pot']::text[], 4, null, ''),
  ('shrimp_corn_egg_soup', 4, '先煮耐煮', '先把玉米煮到甜味进入汤里，再放虾仁和蛋液，汤色会更柔和。', 'simmer', array['shrimp', 'corn', 'egg']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('shrimp_corn_egg_soup', 5, '再下易熟', '加入虾仁、玉米、鸡蛋，轻轻推开，避免把嫩食材搅碎。', 'combine_ingredients', array['shrimp', 'corn', 'egg']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('shrimp_corn_egg_soup', 6, '观察汤色', '小火煮到虾仁玉米蛋花汤汤色更融合，主料状态达到虾仁由半透明转粉并自然卷起。', 'check_doneness', array['shrimp', 'corn', 'egg']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('shrimp_corn_egg_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让虾仁玉米蛋花汤味道更均匀。', 'season', array['shrimp', 'corn', 'egg']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('shrimp_corn_egg_soup', 8, '盛出汤品', '把虾仁玉米蛋花汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['shrimp', 'corn', 'egg']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('beef_potato_carrot_stew', 1, '切配汤料', '牛腱切成薄片或小块，土豆、胡萝卜切成大小接近的块或段，洋葱切好备用，块头不要太大，汤里入口会更顺。', 'cut_meat', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('beef_potato_carrot_stew', 2, '先出香味', '锅中少量油处理洋葱，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('beef_potato_carrot_stew', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让牛腱土豆胡萝卜汤受热更均匀。', 'boil_water', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot']::text[], 4, null, ''),
  ('beef_potato_carrot_stew', 4, '先煮耐煮', '先放土豆、胡萝卜、牛腱，煮到边缘开始变软，汤色稳定后继续。', 'simmer', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('beef_potato_carrot_stew', 5, '再下易熟', '加入易熟食材，轻轻推开，避免把嫩食材搅碎，确认状态后继续，让牛腱土豆胡萝卜汤状态更稳定。', 'combine_ingredients', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('beef_potato_carrot_stew', 6, '观察汤色', '小火煮到牛腱土豆胡萝卜汤汤色更融合，主料状态达到肉类表面变色，锅底水汽明显减少。', 'check_doneness', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('beef_potato_carrot_stew', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让牛腱土豆胡萝卜汤味道更均匀。', 'season', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('beef_potato_carrot_stew', 8, '撇去浮沫', '看到牛腱土豆胡萝卜汤汤面有浮沫时轻轻撇开，汤色会更清楚。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_potato_carrot_stew', 9, '小火融合', '保持小火让牛腱土豆胡萝卜汤汤味融合，汤面平稳冒泡，主料不会被冲散。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_potato_carrot_stew', 10, '检查软度', '用勺子轻压耐煮食材，牛腱土豆胡萝卜汤能被压动但没有完全散开。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_potato_carrot_stew', 11, '静置入味', '关火后让牛腱土豆胡萝卜汤短暂静置，汤味回到食材里，再准备盛出。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('beef_potato_carrot_stew', 12, '盛出汤品', '把牛腱土豆胡萝卜汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['beef_shank', 'potato', 'carrot', 'onion']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('curry_tofu_vegetable_stew', 1, '切配汤料', '豆腐切块后轻轻吸掉表面水分，土豆切成大小接近的块或段，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['tofu', 'potato', 'curry_blocks']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('curry_tofu_vegetable_stew', 2, '先出香味', '锅中少量油处理豆腐，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['tofu', 'potato', 'curry_blocks']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('curry_tofu_vegetable_stew', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让咖喱豆腐蔬菜煲受热更均匀。', 'boil_water', array['tofu', 'potato', 'curry_blocks']::text[], array['pot']::text[], 4, null, ''),
  ('curry_tofu_vegetable_stew', 4, '先煮耐煮', '先把土豆煮到边缘变软，再加入豆腐，咖喱汤底更容易变浓。', 'simmer', array['tofu', 'potato', 'curry_blocks']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('curry_tofu_vegetable_stew', 5, '再下易熟', '加入豆腐，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['tofu', 'potato', 'curry_blocks']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('curry_tofu_vegetable_stew', 6, '观察汤色', '小火煮到咖喱豆腐蔬菜煲汤色更融合，主料状态达到豆腐边缘微黄，轻推时还能保持块状。', 'check_doneness', array['tofu', 'potato', 'curry_blocks']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('curry_tofu_vegetable_stew', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让咖喱豆腐蔬菜煲味道更均匀。', 'season', array['tofu', 'potato', 'curry_blocks']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('curry_tofu_vegetable_stew', 8, '盛出汤品', '把咖喱豆腐蔬菜煲连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['tofu', 'potato', 'curry_blocks']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('pumpkin_chickpea_soup', 1, '切配汤料', '鹰嘴豆罐头沥干并拨散，南瓜切成大小接近的块或段，洋葱切好备用，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['pumpkin', 'canned_chickpeas', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
