  ('pumpkin_chickpea_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让南瓜鹰嘴豆汤受热更均匀。', 'boil_water', array['pumpkin', 'canned_chickpeas', 'onion']::text[], array['pot']::text[], 4, null, ''),
  ('pumpkin_chickpea_soup', 4, '先煮耐煮', '先把南瓜煮到边缘能被勺子压动，再放鹰嘴豆一起融合。', 'simmer', array['pumpkin', 'canned_chickpeas', 'onion']::text[], array['pot', 'ladle']::text[], 10, null, ''),
