  ('pumpkin_chickpea_soup', 6, '观察汤色', '小火煮到南瓜鹰嘴豆汤汤色更融合，主料状态达到罐头食材热透或拌匀，不需要久炒。', 'check_doneness', array['pumpkin', 'canned_chickpeas', 'onion']::text[], array['pot', 'ladle']::text[], 5, null, ''),
