  ('pumpkin_chickpea_soup', 11, '静置入味', '关火后让南瓜鹰嘴豆汤短暂静置，汤味回到食材里，再准备盛出。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('pumpkin_chickpea_soup', 12, '盛出汤品', '把南瓜鹰嘴豆汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['pumpkin', 'canned_chickpeas', 'onion']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('winter_melon_shrimp_soup', 1, '切配汤料', '虾仁沥干到表面不挂水，冬瓜切成大小接近的块或段，姜切好备用，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['winter_melon', 'shrimp', 'ginger']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('winter_melon_shrimp_soup', 2, '先出香味', '锅中少量油处理姜，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['winter_melon', 'shrimp', 'ginger']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('winter_melon_shrimp_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让冬瓜虾仁汤受热更均匀。', 'boil_water', array['winter_melon', 'shrimp', 'ginger']::text[], array['pot']::text[], 4, null, ''),
  ('winter_melon_shrimp_soup', 4, '先煮耐煮', '先把冬瓜煮到边缘半透明，再放虾仁，汤味会更清甜，口感也更分明。', 'simmer', array['winter_melon', 'shrimp', 'ginger']::text[], array['pot', 'ladle']::text[], 10, null, ''),
