  ('winter_melon_shrimp_soup', 6, '观察汤色', '小火煮到冬瓜虾仁汤汤色更融合，主料状态达到虾仁由半透明转粉并自然卷起。', 'check_doneness', array['winter_melon', 'shrimp', 'ginger']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('winter_melon_shrimp_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让冬瓜虾仁汤味道更均匀。', 'season', array['winter_melon', 'shrimp', 'ginger']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('winter_melon_shrimp_soup', 8, '盛出汤品', '把冬瓜虾仁汤连汤带料盛出，碗里汤料比例均匀即可，外观整齐后上桌。', 'plate_dish', array['winter_melon', 'shrimp', 'ginger']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('fridge_cleanout_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，冰箱清理炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('fridge_cleanout_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，冷冻杂蔬保持颗粒分散，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['egg', 'frozen_mixed_vegetables']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('fridge_cleanout_fried_rice', 3, '先炒配料', '锅热加油后先处理鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，再离火，让冰箱清理炒饭状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('fridge_cleanout_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让冰箱清理炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('fridge_cleanout_fried_rice', 5, '合入配料', '把鸡蛋、冷冻杂蔬和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'egg', 'frozen_mixed_vegetables']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('fridge_cleanout_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，冰箱清理炒饭不出现湿团。', 'season', array['rice', 'egg', 'frozen_mixed_vegetables']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('fridge_cleanout_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让冰箱清理炒饭状态更稳定。', 'check_doneness', array['rice', 'egg', 'frozen_mixed_vegetables']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('fridge_cleanout_fried_rice', 8, '盛出炒饭', '把冰箱清理炒饭盛入碗中，表面能看到配料均匀分布，外观整齐后上桌。', 'plate_dish', array['rice', 'egg', 'frozen_mixed_vegetables']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('frozen_broccoli_chicken_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收冷冻西兰花鸡胸饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('frozen_broccoli_chicken_bowl', 2, '切配浇头', '鸡胸肉切成薄片或小块，冷冻西兰花切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['chicken_breast', 'frozen_broccoli']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('frozen_broccoli_chicken_bowl', 3, '做出底味', '锅热后先处理鸡胸肉，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('frozen_broccoli_chicken_bowl', 4, '加入配菜', '加入剩余chicken breast、frozen broccoli翻匀，冷冻西兰花鸡胸饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['chicken_breast', 'frozen_broccoli']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('frozen_broccoli_chicken_bowl', 5, '收成浇头', '加调味或少量水，煮到冷冻西兰花鸡胸饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['chicken_breast', 'frozen_broccoli']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('frozen_broccoli_chicken_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让冷冻西兰花鸡胸饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_breast', 'frozen_broccoli']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('frozen_broccoli_chicken_bowl', 7, '整理浇头', '把冷冻西兰花鸡胸饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('frozen_broccoli_chicken_bowl', 8, '确认盖饭', '尝一口浇头和饭，冷冻西兰花鸡胸饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'chicken_breast', 'frozen_broccoli']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('canned_tomato_pasta_cleanout', 1, '烧水备面', '锅中水烧到持续冒泡，再放意面，这样面条受热更均匀，让罐头番茄清冰箱意面受热更均匀。', 'boil_water', array['pasta']::text[], array['pot']::text[], 3, null, ''),
  ('canned_tomato_pasta_cleanout', 2, '处理配料', '番茄罐头沥干并拨散，洋葱切好备用，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['canned_tomato', 'onion']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('canned_tomato_pasta_cleanout', 3, '煮到弹牙', '意面煮到能夹断但中心仍有弹性，留一小勺面水再沥出，给罐头番茄清冰箱意面保留弹性。', 'boil_noodles', array['pasta']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('canned_tomato_pasta_cleanout', 4, '做出浇头', '锅中处理番茄罐头、洋葱，看到罐头食材热透或拌匀，不需要久炒再加调味。', 'stir_fry', array['canned_tomato', 'onion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('canned_tomato_pasta_cleanout', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让罐头番茄清冰箱意面质地更顺滑。', 'mix_sauce', array['pasta', 'canned_tomato', 'onion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('canned_tomato_pasta_cleanout', 6, '合入面条', '把意面放回锅里拌开，面条不成团，表面开始均匀挂汁，让罐头番茄清冰箱意面状态更稳定。', 'combine_ingredients', array['pasta', 'canned_tomato', 'onion']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('canned_tomato_pasta_cleanout', 7, '检查口感', '夹起一筷子，面条有弹性、番茄罐头、洋葱状态合适，再决定是否补味。', 'check_doneness', array['pasta', 'canned_tomato', 'onion']::text[], array['tongs']::text[], 1, null, ''),
  ('canned_tomato_pasta_cleanout', 8, '装碗出餐', '把罐头番茄清冰箱意面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['pasta', 'canned_tomato', 'onion']::text[], array['tongs']::text[], 1, null, ''),
  ('frozen_spinach_egg_noodles', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让冷冻菠菜鸡蛋面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('frozen_spinach_egg_noodles', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，冷冻菠菜化开后挤掉多余水，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['frozen_spinach', 'egg']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('frozen_spinach_egg_noodles', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给冷冻菠菜鸡蛋面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('frozen_spinach_egg_noodles', 4, '做出浇头', '锅中处理冷冻菠菜、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软再加调味。', 'stir_fry', array['frozen_spinach', 'egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('frozen_spinach_egg_noodles', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让冷冻菠菜鸡蛋面质地更顺滑。', 'mix_sauce', array['noodles', 'frozen_spinach', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('frozen_spinach_egg_noodles', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让冷冻菠菜鸡蛋面状态更稳定。', 'combine_ingredients', array['noodles', 'frozen_spinach', 'egg']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('frozen_spinach_egg_noodles', 7, '检查口感', '夹起一筷子，面条有弹性、冷冻菠菜、鸡蛋状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'frozen_spinach', 'egg']::text[], array['tongs']::text[], 1, null, ''),
  ('frozen_spinach_egg_noodles', 8, '装碗出餐', '把冷冻菠菜鸡蛋面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'frozen_spinach', 'egg']::text[], array['tongs']::text[], 1, null, ''),
  ('tortilla_breakfast_wrap', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让冷冻蔬菜鸡蛋卷饼状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('tortilla_breakfast_wrap', 2, '处理夹馅', '鸡蛋打散到蛋清蛋黄融合，冷冻杂蔬保持颗粒分散，水分控制住，冷冻蔬菜鸡蛋卷饼卷起来才更稳。', 'slice_vegetables', array['egg', 'frozen_mixed_vegetables']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('tortilla_breakfast_wrap', 3, '处理熟馅', '把需要加热的鸡蛋处理到蛋液边缘刚凝固、中间仍柔软，放到不烫手再组合，让冷冻蔬菜鸡蛋卷饼状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tortilla_breakfast_wrap', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免冷冻蔬菜鸡蛋卷饼一卷就往外溢。', 'mix_sauce', array['tortilla', 'egg', 'frozen_mixed_vegetables']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tortilla_breakfast_wrap', 5, '铺料卷起', '把鸡蛋、冷冻杂蔬放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'egg', 'frozen_mixed_vegetables']::text[], array['cutting_board']::text[], 3, null, ''),
  ('tortilla_breakfast_wrap', 6, '切分检查', '切开后看馅料没有集中滑出，冷冻蔬菜鸡蛋卷饼拿起时不松散即可。', 'plate_dish', array['tortilla', 'egg', 'frozen_mixed_vegetables']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('canned_black_bean_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收黑豆玉米饭碗的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('canned_black_bean_rice_bowl', 2, '切配浇头', '黑豆罐头、玉米罐头沥干并拨散，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['canned_black_beans', 'canned_corn']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('canned_black_bean_rice_bowl', 3, '做出底味', '锅热后先处理黑豆罐头、玉米罐头，看到罐头食材热透或拌匀，不需要久炒。', 'stir_fry', array['canned_black_beans', 'canned_corn']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('canned_black_bean_rice_bowl', 4, '加入配菜', '加入剩余canned black beans、玉米罐头翻匀，黑豆玉米饭碗的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['canned_black_beans', 'canned_corn']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('canned_black_bean_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到黑豆玉米饭碗的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['canned_black_beans', 'canned_corn']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('canned_black_bean_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让黑豆玉米饭碗状态更稳定。', 'combine_ingredients', array['rice', 'canned_black_beans', 'canned_corn']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('canned_black_bean_rice_bowl', 7, '整理浇头', '把黑豆玉米饭碗浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('canned_black_bean_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，黑豆玉米饭碗咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'canned_black_beans', 'canned_corn']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('tofu_frozen_pea_curry_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收豆腐冷冻豌豆咖喱饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('tofu_frozen_pea_curry_rice', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，冷冻豌豆沥干，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['tofu', 'frozen_peas', 'curry_blocks']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('tofu_frozen_pea_curry_rice', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让豆腐冷冻豌豆咖喱饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_frozen_pea_curry_rice', 4, '加入配菜', '加入剩余tofu、冷冻豌豆、curry blocks翻匀，豆腐冷冻豌豆咖喱饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['tofu', 'frozen_peas', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tofu_frozen_pea_curry_rice', 5, '收成浇头', '加调味或少量水，煮到咖喱融开并能挂在食材表面，铲过锅底能短暂露出锅面。', 'simmer', array['tofu', 'frozen_peas', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_frozen_pea_curry_rice', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让豆腐冷冻豌豆咖喱饭状态更稳定。', 'combine_ingredients', array['rice', 'tofu', 'frozen_peas', 'curry_blocks']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('tofu_frozen_pea_curry_rice', 7, '整理浇头', '把豆腐冷冻豌豆咖喱饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('tofu_frozen_pea_curry_rice', 8, '确认盖饭', '尝一口浇头和饭，豆腐冷冻豌豆咖喱饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'tofu', 'frozen_peas', 'curry_blocks']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('one_pot_udon_cleanout', 1, '烧水备面', '锅中水烧到持续冒泡，再放乌冬面，这样面条受热更均匀，让一锅清冰箱乌冬受热更均匀。', 'boil_water', array['udon_noodles']::text[], array['pot']::text[], 3, null, ''),
  ('one_pot_udon_cleanout', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，冷冻杂蔬保持颗粒分散，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['frozen_mixed_vegetables', 'egg']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('one_pot_udon_cleanout', 3, '煮到弹牙', '乌冬面煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给一锅清冰箱乌冬保留弹性。', 'boil_noodles', array['udon_noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('one_pot_udon_cleanout', 4, '做出浇头', '锅中处理冷冻杂蔬、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软再加调味。', 'stir_fry', array['frozen_mixed_vegetables', 'egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('one_pot_udon_cleanout', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让一锅清冰箱乌冬质地更顺滑。', 'mix_sauce', array['udon_noodles', 'frozen_mixed_vegetables', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('one_pot_udon_cleanout', 6, '合入面条', '把乌冬面放回锅里拌开，面条不成团，表面开始均匀挂汁，让一锅清冰箱乌冬状态更稳定。', 'combine_ingredients', array['udon_noodles', 'frozen_mixed_vegetables', 'egg']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('one_pot_udon_cleanout', 7, '检查口感', '夹起一筷子，面条有弹性、冷冻杂蔬、鸡蛋状态合适，再决定是否补味。', 'check_doneness', array['udon_noodles', 'frozen_mixed_vegetables', 'egg']::text[], array['tongs']::text[], 1, null, ''),
  ('one_pot_udon_cleanout', 8, '装碗出餐', '把一锅清冰箱乌冬盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['udon_noodles', 'frozen_mixed_vegetables', 'egg']::text[], array['tongs']::text[], 1, null, ''),
  ('tomato_mushroom_toast', 1, '备好底胚', '面包放平，边缘没有破口或过湿，后面夹馅才不容易散开，让番茄蘑菇烤吐司状态更稳定。', 'prep_ingredients', array['bread']::text[], array['cutting_board']::text[], 1, null, ''),
  ('tomato_mushroom_toast', 2, '处理夹馅', '蘑菇切成大小接近的块或段，水分控制住，番茄蘑菇烤吐司卷起来才更稳。', 'slice_vegetables', array['tomato_paste', 'mushroom']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('tomato_mushroom_toast', 3, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免番茄蘑菇烤吐司一卷就往外溢。', 'mix_sauce', array['bread', 'tomato_paste', 'mushroom']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tomato_mushroom_toast', 4, '铺料卷起', '把番茄膏、蘑菇放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['bread', 'tomato_paste', 'mushroom']::text[], array['cutting_board']::text[], 3, null, ''),
  ('tomato_mushroom_toast', 5, '切分检查', '切开后看馅料没有集中滑出，番茄蘑菇烤吐司拿起时不松散即可。', 'plate_dish', array['bread', 'tomato_paste', 'mushroom']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('microwave_sweet_potato_tuna', 1, '切配入碗', '金枪鱼罐头沥干并拨散，红薯切块，玉米粒沥干，放进微波容器后铺平，中间不要堆太厚。', 'prep_ingredients', array['sweet_potato', 'canned_tuna', 'corn']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('microwave_sweet_potato_tuna', 2, '加盖留缝', '容器盖上盖子或保鲜膜并留小缝，微波红薯金枪鱼加热时水汽能散出。', 'microwave', array['sweet_potato', 'canned_tuna', 'corn']::text[], array['microwave']::text[], 1, null, ''),
  ('microwave_sweet_potato_tuna', 3, '分段微波', '先短时间加热，取出搅动或翻面，中心冒热气后再判断是否补热，让微波红薯金枪鱼状态更稳定。', 'microwave', array['sweet_potato', 'canned_tuna', 'corn']::text[], array['microwave']::text[], 4, null, ''),
  ('microwave_sweet_potato_tuna', 4, '拌入调味', '加入调味后拌匀，看到微波红薯金枪鱼表面湿润但碗底不积太多水。', 'season', array['sweet_potato', 'canned_tuna', 'corn']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('microwave_sweet_potato_tuna', 5, '静置再吃', '静置片刻让微波红薯金枪鱼热度均匀，边缘不再滚烫，表面仍保持湿润时上桌。', 'rest_food', array['sweet_potato', 'canned_tuna', 'corn']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('onion_egg_stir_fry', 1, '处理食材', '鸡蛋打散到蛋清蛋黄融合，洋葱切好备用，看一遍顺序，洋葱炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['onion', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('onion_egg_stir_fry', 2, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让洋葱炒蛋状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('onion_egg_stir_fry', 3, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让洋葱炒蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('onion_egg_stir_fry', 4, '合炒入味', '把锅中食材合在一起，调味后看到洋葱炒蛋的主味均匀裹在食材上。', 'combine_ingredients', array['onion', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('onion_egg_stir_fry', 5, '装盘检查', '确认洋葱炒蛋蛋液边缘刚凝固、中间仍柔软，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['onion', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('carrot_egg_stir_fry', 1, '整理食材', '鸡蛋打散到蛋清蛋黄融合，胡萝卜切成大小接近的块或段，看一遍顺序，胡萝卜炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['carrot', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('carrot_egg_stir_fry', 2, '起锅加油', '锅面热后加油，油能流动铺开，说明胡萝卜炒蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, '')
;

