  ('pan_fried_scallion_tofu', 1, '备好配料', '豆腐切块后轻轻吸掉表面水分，葱花切好备用，看一遍顺序，葱香煎豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['tofu', 'scallion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
