  ('pan_fried_scallion_tofu', 3, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让葱香煎豆腐状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('pan_fried_scallion_tofu', 4, '合炒入味', '把锅中食材合在一起，调味后看到葱姜香气出来，锅里没有生辛味，让葱香煎豆腐状态更稳定。', 'combine_ingredients', array['tofu', 'scallion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('pan_fried_scallion_tofu', 5, '调整火候', '转中火让葱香煎豆腐继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('pan_fried_scallion_tofu', 6, '观察主料', '夹起主要食材看颜色和质地，葱香煎豆腐没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('pan_fried_scallion_tofu', 7, '回锅收味', '把边缘食材推回锅心，葱香煎豆腐味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('pan_fried_scallion_tofu', 8, '出锅确认', '确认葱香煎豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['tofu', 'scallion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('soy_sauce_tofu_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收酱油豆腐盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('soy_sauce_tofu_rice_bowl', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，葱花切好备用，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['tofu', 'scallion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('soy_sauce_tofu_rice_bowl', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让酱油豆腐盖饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('soy_sauce_tofu_rice_bowl', 4, '加入配菜', '加入剩余tofu、scallion翻匀，酱油豆腐盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['tofu', 'scallion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('soy_sauce_tofu_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到葱姜香气出来，锅里没有生辛味，铲过锅底能短暂露出锅面。', 'simmer', array['tofu', 'scallion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('soy_sauce_tofu_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让酱油豆腐盖饭状态更稳定。', 'combine_ingredients', array['rice', 'tofu', 'scallion']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('soy_sauce_tofu_rice_bowl', 7, '整理浇头', '把酱油豆腐盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('soy_sauce_tofu_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，酱油豆腐盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'tofu', 'scallion']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('tomato_tofu_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收番茄豆腐盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('tomato_tofu_rice_bowl', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，番茄切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['tomato', 'tofu']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('tomato_tofu_rice_bowl', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让番茄豆腐盖饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tomato_tofu_rice_bowl', 4, '加入配菜', '加入剩余tomato、tofu翻匀，番茄豆腐盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['tomato', 'tofu']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tomato_tofu_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到番茄汁水变浓并包住主料，铲过锅底能短暂露出锅面，让番茄豆腐盖饭汤汁更稳定。', 'simmer', array['tomato', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tomato_tofu_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让番茄豆腐盖饭状态更稳定。', 'combine_ingredients', array['rice', 'tomato', 'tofu']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('tomato_tofu_rice_bowl', 7, '整理浇头', '把番茄豆腐盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('tomato_tofu_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，番茄豆腐盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'tomato', 'tofu']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('ground_pork_tofu_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收肉末豆腐盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('ground_pork_tofu_rice_bowl', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，猪肉末拨散，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['ground_pork', 'tofu']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('ground_pork_tofu_rice_bowl', 3, '做出底味', '锅热后先处理猪肉末、豆腐，看到豆腐边缘微黄，轻推时还能保持块状。', 'sear_meat', array['ground_pork', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('ground_pork_tofu_rice_bowl', 4, '加入配菜', '加入剩余猪肉末、tofu翻匀，肉末豆腐盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['ground_pork', 'tofu']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('ground_pork_tofu_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到肉末豆腐盖饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['ground_pork', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('ground_pork_tofu_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让肉末豆腐盖饭状态更稳定。', 'combine_ingredients', array['rice', 'ground_pork', 'tofu']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('ground_pork_tofu_rice_bowl', 7, '整理浇头', '把肉末豆腐盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('ground_pork_tofu_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，肉末豆腐盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'ground_pork', 'tofu']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('ground_beef_potato_stir_fry', 1, '备好配料', '牛肉碎拨散，土豆切成大小接近的块或段，洋葱切好备用，看一遍顺序，牛肉碎炒土豆丁下锅后就不用临时找东西。', 'prep_ingredients', array['ground_beef', 'potato', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('ground_beef_potato_stir_fry', 2, '清洗沥水', '土豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['potato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('ground_beef_potato_stir_fry', 3, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让牛肉碎炒土豆丁状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('ground_beef_potato_stir_fry', 4, '处理主料', '放入牛肉碎摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['ground_beef']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('ground_beef_potato_stir_fry', 5, '加入配菜', '加入土豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['potato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('ground_beef_potato_stir_fry', 6, '合炒入味', '把锅中食材合在一起，调味后看到牛肉碎炒土豆丁的主味均匀裹在食材上。', 'combine_ingredients', array['ground_beef', 'potato', 'onion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('ground_beef_potato_stir_fry', 7, '调整火候', '转中火让牛肉碎炒土豆丁继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('ground_beef_potato_stir_fry', 8, '出锅确认', '确认牛肉碎炒土豆丁肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['ground_beef', 'potato', 'onion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('chicken_thigh_onion_stir_fry', 1, '备齐食材', '鸡腿肉切成薄片或小块，洋葱切好备用，看一遍顺序，洋葱鸡腿肉下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_thigh', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('chicken_thigh_onion_stir_fry', 2, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让洋葱鸡腿肉状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('chicken_thigh_onion_stir_fry', 3, '处理主料', '放入鸡腿肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让洋葱鸡腿肉状态更稳定。', 'sear_meat', array['chicken_thigh']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('chicken_thigh_onion_stir_fry', 4, '合炒入味', '把锅中食材合在一起，调味后看到洋葱鸡腿肉的主味均匀裹在食材上。', 'combine_ingredients', array['chicken_thigh', 'onion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('chicken_thigh_onion_stir_fry', 5, '调整火候', '转中火让洋葱鸡腿肉继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_onion_stir_fry', 6, '观察主料', '夹起主要食材看颜色和质地，洋葱鸡腿肉没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_onion_stir_fry', 7, '回锅收味', '把边缘食材推回锅心，洋葱鸡腿肉味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_thigh_onion_stir_fry', 8, '整理出餐', '确认洋葱鸡腿肉肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_thigh', 'onion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('tomato_chicken_breast', 1, '处理食材', '鸡胸肉切成薄片或小块，番茄切成大小接近的块或段，看一遍顺序，番茄鸡胸肉下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_breast', 'tomato']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('tomato_chicken_breast', 2, '清洗沥水', '番茄冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低，让番茄鸡胸肉状态更稳定。', 'wash_ingredients', array['tomato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tomato_chicken_breast', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明番茄鸡胸肉可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('tomato_chicken_breast', 4, '处理主料', '放入鸡胸肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让番茄鸡胸肉状态更稳定。', 'sear_meat', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('tomato_chicken_breast', 5, '加入配菜', '加入番茄翻炒，看到颜色变亮、边缘开始变软但还保留形状，让番茄鸡胸肉状态更稳定。', 'stir_fry', array['tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tomato_chicken_breast', 6, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄鸡胸肉状态更稳定。', 'combine_ingredients', array['chicken_breast', 'tomato']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('tomato_chicken_breast', 7, '调整火候', '转中火让番茄鸡胸肉继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('tomato_chicken_breast', 8, '装盘检查', '确认番茄鸡胸肉肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_breast', 'tomato']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('cucumber_chicken_breast', 1, '整理食材', '鸡胸肉切成薄片或小块，黄瓜切好后保持清爽不出水，看一遍顺序，黄瓜鸡胸肉下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_breast', 'cucumber']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('cucumber_chicken_breast', 2, '清洗沥水', '黄瓜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('cucumber_chicken_breast', 3, '起锅加油', '锅面热后加油，油能流动铺开，说明黄瓜鸡胸肉可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('cucumber_chicken_breast', 4, '处理主料', '放入鸡胸肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让黄瓜鸡胸肉状态更稳定。', 'sear_meat', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('cucumber_chicken_breast', 5, '加入配菜', '加入黄瓜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['cucumber']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cucumber_chicken_breast', 6, '合炒入味', '把锅中食材合在一起，调味后看到黄瓜鸡胸肉的主味均匀裹在食材上。', 'combine_ingredients', array['chicken_breast', 'cucumber']::text[], array['pan', 'spatula']::text[], 3, null, ''),
