  ('cucumber_chicken_breast', 8, '盛出收尾', '确认黄瓜鸡胸肉肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_breast', 'cucumber']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('bell_pepper_pork_slice', 1, '备好配料', '猪肉片切成薄片或小块，彩椒切成大小接近的块或段，洋葱切好备用，看一遍顺序，彩椒猪肉片下锅后就不用临时找东西。', 'prep_ingredients', array['pork_slice', 'bell_pepper', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('bell_pepper_pork_slice', 2, '清洗沥水', '彩椒冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['bell_pepper']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('bell_pepper_pork_slice', 3, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让彩椒猪肉片状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('bell_pepper_pork_slice', 4, '处理主料', '放入猪肉片摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['pork_slice']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
