  ('bell_pepper_beef_slice', 1, '备齐食材', '牛肉片切成薄片或小块，彩椒切成大小接近的块或段，看一遍顺序，彩椒牛肉片下锅后就不用临时找东西。', 'prep_ingredients', array['beef_slice', 'bell_pepper']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
