  ('bell_pepper_beef_slice', 7, '调整火候', '转中火让彩椒牛肉片继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('bell_pepper_beef_slice', 8, '整理出餐', '确认彩椒牛肉片肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['beef_slice', 'bell_pepper']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('shrimp_cucumber_stir_fry', 1, '处理食材', '虾仁沥干到表面不挂水，黄瓜切好后保持清爽不出水，看一遍顺序，黄瓜虾仁下锅后就不用临时找东西。', 'prep_ingredients', array['shrimp', 'cucumber']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('shrimp_cucumber_stir_fry', 2, '清洗沥水', '黄瓜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('shrimp_cucumber_stir_fry', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明黄瓜虾仁可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('shrimp_cucumber_stir_fry', 4, '处理主料', '放入虾仁摊开受热，看到虾仁由半透明转粉并自然卷起再翻动或拨到锅边，让黄瓜虾仁状态更稳定。', 'sear_meat', array['shrimp']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('shrimp_cucumber_stir_fry', 5, '加入配菜', '加入黄瓜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['cucumber']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shrimp_cucumber_stir_fry', 6, '合炒入味', '把锅中食材合在一起，调味后看到黄瓜虾仁的主味均匀裹在食材上。', 'combine_ingredients', array['shrimp', 'cucumber']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shrimp_cucumber_stir_fry', 7, '调整火候', '转中火让黄瓜虾仁继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('shrimp_cucumber_stir_fry', 8, '装盘检查', '确认黄瓜虾仁虾仁由半透明转粉并自然卷起，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['shrimp', 'cucumber']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('shrimp_cabbage_stir_fry', 1, '整理食材', '虾仁沥干到表面不挂水，卷心菜切成大小接近的块或段，蒜切好备用，看一遍顺序，虾仁炒卷心菜下锅后就不用临时找东西。', 'prep_ingredients', array['shrimp', 'cabbage', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('shrimp_cabbage_stir_fry', 2, '清洗沥水', '卷心菜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['cabbage']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('shrimp_cabbage_stir_fry', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让虾仁炒卷心菜状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('shrimp_cabbage_stir_fry', 4, '处理主料', '放入虾仁摊开受热，看到虾仁由半透明转粉并自然卷起再翻动或拨到锅边，让虾仁炒卷心菜状态更稳定。', 'sear_meat', array['shrimp']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('shrimp_cabbage_stir_fry', 5, '加入配菜', '加入卷心菜翻炒，看到颜色变亮、边缘开始变软但还保留形状，让虾仁炒卷心菜状态更稳定。', 'stir_fry', array['cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('shrimp_cabbage_stir_fry', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让虾仁炒卷心菜状态更稳定。', 'combine_ingredients', array['shrimp', 'cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('shrimp_cabbage_stir_fry', 7, '调整火候', '转中火让虾仁炒卷心菜继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('shrimp_cabbage_stir_fry', 8, '盛出收尾', '确认虾仁炒卷心菜虾仁由半透明转粉并自然卷起，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['shrimp', 'cabbage', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('white_fish_tomato_tofu_pan', 1, '备好配料', '白鱼擦干切块，豆腐吸水，番茄切小块，确认嫩食材都能轻拿轻放。', 'prep_ingredients', array['white_fish', 'tomato', 'tofu']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('white_fish_tomato_tofu_pan', 2, '清洗沥水', '番茄冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低，让番茄豆腐白鱼状态更稳定。', 'wash_ingredients', array['tomato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('white_fish_tomato_tofu_pan', 3, '锅热入油', '锅面热后加油，油能流动铺开，说明番茄豆腐白鱼可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('white_fish_tomato_tofu_pan', 4, '处理主料', '放入白鱼、豆腐摊开受热，看到鱼肉由透明转白，能轻轻推动但不碎再翻动或拨到锅边。', 'pan_fry', array['white_fish', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, '鱼类步骤提醒轻推，避免频繁翻面导致散碎。'),
  ('white_fish_tomato_tofu_pan', 5, '加入配菜', '加入番茄翻炒，看到颜色变亮、边缘开始变软但还保留形状，让番茄豆腐白鱼状态更稳定。', 'stir_fry', array['tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('white_fish_tomato_tofu_pan', 6, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让番茄豆腐白鱼状态更稳定。', 'combine_ingredients', array['white_fish', 'tomato', 'tofu']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('white_fish_tomato_tofu_pan', 7, '调整火候', '转中火让番茄豆腐白鱼继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('white_fish_tomato_tofu_pan', 8, '出锅确认', '确认番茄豆腐白鱼鱼肉由透明转白，能轻轻推动但不碎，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['white_fish', 'tomato', 'tofu']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('canned_tuna_cabbage_stir_fry', 1, '备齐食材', '金枪鱼罐头沥干并拨散，卷心菜切成大小接近的块或段，看一遍顺序，金枪鱼炒卷心菜下锅后就不用临时找东西。', 'prep_ingredients', array['canned_tuna', 'cabbage']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('canned_tuna_cabbage_stir_fry', 2, '热锅铺油', '锅面热后加油，油能流动铺开，说明金枪鱼炒卷心菜可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('canned_tuna_cabbage_stir_fry', 3, '处理主料', '放入金枪鱼罐头摊开受热，看到罐头食材热透或拌匀，不需要久炒再翻动或拨到锅边。', 'sear_meat', array['canned_tuna']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('canned_tuna_cabbage_stir_fry', 4, '加入配菜', '加入卷心菜翻炒，看到颜色变亮、边缘开始变软但还保留形状，让金枪鱼炒卷心菜状态更稳定。', 'stir_fry', array['cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('canned_tuna_cabbage_stir_fry', 5, '合炒入味', '把锅中食材合在一起，调味后看到金枪鱼炒卷心菜的主味均匀裹在食材上。', 'combine_ingredients', array['canned_tuna', 'cabbage']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('canned_tuna_cabbage_stir_fry', 6, '整理出餐', '确认金枪鱼炒卷心菜罐头食材热透或拌匀，不需要久炒，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['canned_tuna', 'cabbage']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('bacon_cabbage_stir_fry', 1, '处理食材', '卷心菜切成大小接近的块或段，看一遍顺序，培根炒卷心菜下锅后就不用临时找东西。', 'prep_ingredients', array['bacon', 'cabbage']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('bacon_cabbage_stir_fry', 2, '热锅下油', '锅面热后加油，油能流动铺开，说明培根炒卷心菜可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('bacon_cabbage_stir_fry', 3, '处理主料', '放入培根摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['bacon']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('bacon_cabbage_stir_fry', 4, '加入配菜', '加入卷心菜翻炒，看到颜色变亮、边缘开始变软但还保留形状，让培根炒卷心菜状态更稳定。', 'stir_fry', array['cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('bacon_cabbage_stir_fry', 5, '合炒入味', '把锅中食材合在一起，调味后看到培根炒卷心菜的主味均匀裹在食材上。', 'combine_ingredients', array['bacon', 'cabbage']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('bacon_cabbage_stir_fry', 6, '装盘检查', '确认培根炒卷心菜肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['bacon', 'cabbage']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('sausage_potato_pan', 1, '整理食材', '土豆切成大小接近的块或段，洋葱切好备用，看一遍顺序，香肠土豆锅下锅后就不用临时找东西。', 'prep_ingredients', array['sausage', 'potato', 'onion']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('sausage_potato_pan', 2, '清洗沥水', '土豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['potato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('sausage_potato_pan', 3, '爆出香味', '锅热加油后放洋葱，闻到香气、边缘微微变色就进入下一步，让香肠土豆锅状态更稳定。', 'saute_aromatics', array['onion']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('sausage_potato_pan', 4, '处理主料', '放入香肠摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['sausage']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('sausage_potato_pan', 5, '加入配菜', '加入土豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['potato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('sausage_potato_pan', 6, '合炒入味', '把锅中食材合在一起，调味后看到香肠土豆锅的主味均匀裹在食材上。', 'combine_ingredients', array['sausage', 'potato', 'onion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('sausage_potato_pan', 7, '调整火候', '转中火让香肠土豆锅继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('sausage_potato_pan', 8, '盛出收尾', '确认香肠土豆锅肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['sausage', 'potato', 'onion']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('ground_turkey_tomato_egg', 1, '备好配料', '鸡蛋打散到蛋清蛋黄融合，火鸡碎拨散，番茄切成大小接近的块或段，看一遍顺序，火鸡碎番茄蛋下锅后就不用临时找东西。', 'prep_ingredients', array['ground_turkey', 'tomato', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('ground_turkey_tomato_egg', 2, '清洗沥水', '番茄冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低，让火鸡碎番茄蛋状态更稳定。', 'wash_ingredients', array['tomato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('ground_turkey_tomato_egg', 3, '锅热入油', '锅面热后加油，油能流动铺开，说明火鸡碎番茄蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('ground_turkey_tomato_egg', 4, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让火鸡碎番茄蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('ground_turkey_tomato_egg', 5, '处理主料', '放入火鸡碎摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['ground_turkey']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('ground_turkey_tomato_egg', 6, '加入配菜', '加入番茄翻炒，看到颜色变亮、边缘开始变软但还保留形状，让火鸡碎番茄蛋状态更稳定。', 'stir_fry', array['tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('ground_turkey_tomato_egg', 7, '合炒入味', '把锅中食材合在一起，调味后看到番茄汁水变浓并包住主料，让火鸡碎番茄蛋状态更稳定。', 'combine_ingredients', array['ground_turkey', 'tomato', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('ground_turkey_tomato_egg', 8, '出锅确认', '确认火鸡碎番茄蛋肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['ground_turkey', 'tomato', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('edamame_egg_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，毛豆鸡蛋炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('edamame_egg_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，毛豆沥干，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['edamame', 'egg']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('edamame_egg_fried_rice', 3, '先炒配料', '锅热加油后先处理鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，再离火，让毛豆鸡蛋炒饭状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('edamame_egg_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让毛豆鸡蛋炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('edamame_egg_fried_rice', 5, '合入配料', '把毛豆、鸡蛋和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'edamame', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('edamame_egg_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，毛豆鸡蛋炒饭不出现湿团。', 'season', array['rice', 'edamame', 'egg']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('edamame_egg_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让毛豆鸡蛋炒饭状态更稳定。', 'check_doneness', array['rice', 'edamame', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('edamame_egg_fried_rice', 8, '盛出炒饭', '把毛豆鸡蛋炒饭盛入碗中，表面能看到配料均匀分布，外观整齐后上桌。', 'plate_dish', array['rice', 'edamame', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('carrot_pea_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，胡萝卜豌豆炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('carrot_pea_fried_rice', 2, '处理配料', '胡萝卜、豌豆沥干，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['carrot', 'peas']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('carrot_pea_fried_rice', 3, '先炒配料', '锅热加油后先处理胡萝卜、豌豆，看到蔬菜颜色变亮，边缘开始变软但仍有支撑感。', 'stir_fry', array['carrot', 'peas']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('carrot_pea_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让胡萝卜豌豆炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('carrot_pea_fried_rice', 5, '合入配料', '把胡萝卜、豌豆和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'carrot', 'peas']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('carrot_pea_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，胡萝卜豌豆炒饭不出现湿团。', 'season', array['rice', 'carrot', 'peas']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('carrot_pea_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让胡萝卜豌豆炒饭状态更稳定。', 'check_doneness', array['rice', 'carrot', 'peas']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('carrot_pea_fried_rice', 8, '盛出炒饭', '把胡萝卜豌豆炒饭盛入碗中，表面能看到配料均匀分布。', 'plate_dish', array['rice', 'carrot', 'peas']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('broccoli_egg_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，西兰花鸡蛋炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('broccoli_egg_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，西兰花切成大小接近的块或段，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['broccoli', 'egg']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('broccoli_egg_fried_rice', 3, '先炒配料', '锅热加油后先处理鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，再离火，让西兰花鸡蛋炒饭状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('broccoli_egg_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让西兰花鸡蛋炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('broccoli_egg_fried_rice', 5, '合入配料', '把西兰花、鸡蛋和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'broccoli', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('broccoli_egg_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，西兰花鸡蛋炒饭不出现湿团。', 'season', array['rice', 'broccoli', 'egg']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('broccoli_egg_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让西兰花鸡蛋炒饭状态更稳定。', 'check_doneness', array['rice', 'broccoli', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('broccoli_egg_fried_rice', 8, '盛出炒饭', '把西兰花鸡蛋炒饭盛入碗中，表面能看到配料均匀分布。', 'plate_dish', array['rice', 'broccoli', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('cabbage_egg_noodles', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让卷心菜鸡蛋面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('cabbage_egg_noodles', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，卷心菜切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['cabbage', 'egg']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('cabbage_egg_noodles', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给卷心菜鸡蛋面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('cabbage_egg_noodles', 4, '做出浇头', '锅中处理卷心菜、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软再加调味。', 'stir_fry', array['cabbage', 'egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('cabbage_egg_noodles', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让卷心菜鸡蛋面质地更顺滑。', 'mix_sauce', array['noodles', 'cabbage', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cabbage_egg_noodles', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让卷心菜鸡蛋面状态更稳定。', 'combine_ingredients', array['noodles', 'cabbage', 'egg']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('cabbage_egg_noodles', 7, '检查口感', '夹起一筷子，面条有弹性、卷心菜、鸡蛋状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'cabbage', 'egg']::text[], array['tongs']::text[], 1, null, ''),
  ('cabbage_egg_noodles', 8, '装碗出餐', '把卷心菜鸡蛋面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'cabbage', 'egg']::text[], array['tongs']::text[], 1, null, ''),
