  ('cabbage_carrot_ramen', 3, '煮到弹牙', '拉面煮到能夹断但中心仍有弹性，捞出后轻轻沥水，再捞出处理。', 'boil_noodles', array['ramen_noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('cabbage_carrot_ramen', 4, '做出浇头', '锅中处理卷心菜、胡萝卜，看到蔬菜颜色变亮，边缘开始变软但仍有支撑感再加调味。', 'stir_fry', array['cabbage', 'carrot']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('cabbage_carrot_ramen', 5, '兑成汤底', '加入热水或汤底，煮到汤色均匀，卷心菜胡萝卜拉面的香味散开。', 'simmer', array['ramen_noodles', 'cabbage', 'carrot']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cabbage_carrot_ramen', 6, '合入面条', '把拉面放回锅里拌开，面条不成团，表面开始均匀挂汁。', 'combine_ingredients', array['ramen_noodles', 'cabbage', 'carrot']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('cabbage_carrot_ramen', 7, '检查口感', '夹起一筷子，面条有弹性、卷心菜、胡萝卜状态合适，再决定是否补味。', 'check_doneness', array['ramen_noodles', 'cabbage', 'carrot']::text[], array['tongs']::text[], 1, null, ''),
  ('cabbage_carrot_ramen', 8, '装碗出餐', '把卷心菜胡萝卜拉面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['ramen_noodles', 'cabbage', 'carrot']::text[], array['tongs']::text[], 1, null, ''),
  ('tofu_mushroom_udon', 1, '烧水备面', '锅中水烧到持续冒泡，再放乌冬面，这样面条受热更均匀，让豆腐蘑菇乌冬受热更均匀。', 'boil_water', array['udon_noodles']::text[], array['pot']::text[], 3, null, ''),
  ('tofu_mushroom_udon', 2, '处理配料', '豆腐切块后轻轻吸掉表面水分，蘑菇切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['tofu', 'mushroom']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('tofu_mushroom_udon', 3, '煮到弹牙', '乌冬面煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给豆腐蘑菇乌冬保留弹性。', 'boil_noodles', array['udon_noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('tofu_mushroom_udon', 4, '做出浇头', '锅中处理豆腐、蘑菇，看到豆腐边缘微黄，轻推时还能保持块状再加调味。', 'stir_fry', array['tofu', 'mushroom']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_mushroom_udon', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让豆腐蘑菇乌冬质地更顺滑。', 'mix_sauce', array['udon_noodles', 'tofu', 'mushroom']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('tofu_mushroom_udon', 6, '合入面条', '把乌冬面放回锅里拌开，面条不成团，表面开始均匀挂汁，让豆腐蘑菇乌冬状态更稳定。', 'combine_ingredients', array['udon_noodles', 'tofu', 'mushroom']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('tofu_mushroom_udon', 7, '检查口感', '夹起一筷子，面条有弹性、豆腐、蘑菇状态合适，再决定是否补味。', 'check_doneness', array['udon_noodles', 'tofu', 'mushroom']::text[], array['tongs']::text[], 1, null, '')
;

