  ('spinach_egg_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，菠菜鸡蛋饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'spinach', 'egg']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('mushroom_beef_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收蘑菇牛肉盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('mushroom_beef_rice_bowl', 2, '切配浇头', '牛肉片切成薄片或小块，蘑菇切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['beef_slice', 'mushroom']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('mushroom_beef_rice_bowl', 3, '做出底味', '锅热后先处理牛肉片，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['beef_slice']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('mushroom_beef_rice_bowl', 4, '加入配菜', '加入剩余beef slice、mushroom翻匀，蘑菇牛肉盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['beef_slice', 'mushroom']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('mushroom_beef_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到蘑菇牛肉盖饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['beef_slice', 'mushroom']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('mushroom_beef_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让蘑菇牛肉盖饭状态更稳定。', 'combine_ingredients', array['rice', 'beef_slice', 'mushroom']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('mushroom_beef_rice_bowl', 7, '整理浇头', '把蘑菇牛肉盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('mushroom_beef_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，蘑菇牛肉盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'beef_slice', 'mushroom']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('onion_pork_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收洋葱猪肉盖饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('onion_pork_rice_bowl', 2, '切配浇头', '猪肉片切成薄片或小块，洋葱切好备用，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['pork_slice', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('onion_pork_rice_bowl', 3, '做出底味', '锅热后先处理猪肉片，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['pork_slice']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('onion_pork_rice_bowl', 4, '加入配菜', '加入剩余pork slice、onion翻匀，洋葱猪肉盖饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['pork_slice', 'onion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('onion_pork_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到洋葱猪肉盖饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['pork_slice', 'onion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('onion_pork_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让洋葱猪肉盖饭状态更稳定。', 'combine_ingredients', array['rice', 'pork_slice', 'onion']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('onion_pork_rice_bowl', 7, '整理浇头', '把洋葱猪肉盖饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('onion_pork_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，洋葱猪肉盖饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'pork_slice', 'onion']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('scallion_egg_udon', 1, '烧水备面', '锅中水烧到持续冒泡，再放乌冬面，这样面条受热更均匀，让葱花鸡蛋乌冬受热更均匀。', 'boil_water', array['udon_noodles']::text[], array['pot']::text[], 3, null, ''),
  ('scallion_egg_udon', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，葱花切好备用，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['egg', 'scallion']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('scallion_egg_udon', 3, '煮到弹牙', '乌冬面煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给葱花鸡蛋乌冬保留弹性。', 'boil_noodles', array['udon_noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('scallion_egg_udon', 4, '做出浇头', '锅中处理鸡蛋、葱花，看到蛋液边缘刚凝固、中间仍柔软再加调味。', 'stir_fry', array['egg', 'scallion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('scallion_egg_udon', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让葱花鸡蛋乌冬质地更顺滑。', 'mix_sauce', array['udon_noodles', 'egg', 'scallion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('scallion_egg_udon', 6, '合入面条', '把乌冬面放回锅里拌开，面条不成团，表面开始均匀挂汁，让葱花鸡蛋乌冬状态更稳定。', 'combine_ingredients', array['udon_noodles', 'egg', 'scallion']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('scallion_egg_udon', 7, '检查口感', '夹起一筷子，面条有弹性、鸡蛋、葱花状态合适，再决定是否补味。', 'check_doneness', array['udon_noodles', 'egg', 'scallion']::text[], array['tongs']::text[], 1, null, ''),
  ('scallion_egg_udon', 8, '装碗出餐', '把葱花鸡蛋乌冬盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['udon_noodles', 'egg', 'scallion']::text[], array['tongs']::text[], 1, null, ''),
  ('green_bean_chicken', 1, '备齐食材', '鸡胸肉切成薄片或小块，四季豆切成大小接近的块或段，蒜切好备用，看一遍顺序，四季豆鸡胸肉下锅后就不用临时找东西。', 'prep_ingredients', array['green_beans', 'chicken_breast', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('green_bean_chicken', 2, '清洗沥水', '四季豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['green_beans']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('green_bean_chicken', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让四季豆鸡胸肉状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('green_bean_chicken', 4, '处理主料', '放入鸡胸肉摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让四季豆鸡胸肉状态更稳定。', 'sear_meat', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('green_bean_chicken', 5, '加入配菜', '加入四季豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['green_beans']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('green_bean_chicken', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让四季豆鸡胸肉状态更稳定。', 'combine_ingredients', array['green_beans', 'chicken_breast', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('green_bean_chicken', 7, '调整火候', '转中火让四季豆鸡胸肉继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('green_bean_chicken', 8, '整理出餐', '确认四季豆鸡胸肉肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['green_beans', 'chicken_breast', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('green_bean_beef', 1, '处理食材', '牛肉片切成薄片或小块，四季豆切成大小接近的块或段，蒜切好备用，看一遍顺序，四季豆牛肉片下锅后就不用临时找东西。', 'prep_ingredients', array['green_beans', 'beef_slice', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('green_bean_beef', 2, '清洗沥水', '四季豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['green_beans']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('green_bean_beef', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让四季豆牛肉片状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('green_bean_beef', 4, '处理主料', '放入牛肉片摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边，让四季豆牛肉片状态更稳定。', 'sear_meat', array['beef_slice']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('green_bean_beef', 5, '加入配菜', '加入四季豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['green_beans']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('green_bean_beef', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让四季豆牛肉片状态更稳定。', 'combine_ingredients', array['green_beans', 'beef_slice', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('green_bean_beef', 7, '调整火候', '转中火让四季豆牛肉片继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('green_bean_beef', 8, '装盘检查', '确认四季豆牛肉片肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['green_beans', 'beef_slice', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('cauliflower_egg_stir_fry', 1, '整理食材', '鸡蛋打散到蛋清蛋黄融合，花椰菜切成大小接近的块或段，看一遍顺序，花椰菜炒蛋下锅后就不用临时找东西。', 'prep_ingredients', array['cauliflower', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('cauliflower_egg_stir_fry', 2, '清洗沥水', '花椰菜冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['cauliflower']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('cauliflower_egg_stir_fry', 3, '起锅加油', '锅面热后加油，油能流动铺开，说明花椰菜炒蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('cauliflower_egg_stir_fry', 4, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让花椰菜炒蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cauliflower_egg_stir_fry', 5, '加入配菜', '加入花椰菜翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['cauliflower']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cauliflower_egg_stir_fry', 6, '合炒入味', '把锅中食材合在一起，调味后看到花椰菜炒蛋的主味均匀裹在食材上。', 'combine_ingredients', array['cauliflower', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cauliflower_egg_stir_fry', 7, '调整火候', '转中火让花椰菜炒蛋继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('cauliflower_egg_stir_fry', 8, '盛出收尾', '确认花椰菜炒蛋蛋液边缘刚凝固、中间仍柔软，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['cauliflower', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('corn_egg_pancake', 1, '调成面糊', '鸡蛋打散到蛋清蛋黄融合，玉米粒沥干，把面糊拌到能缓慢流动，没有大片干粉。', 'mix_sauce', array['corn', 'egg', 'flour']::text[], array['mixing_bowl']::text[], 4, null, ''),
  ('corn_egg_pancake', 2, '热锅薄油', '平底锅加热后薄薄抹油，面糊落下能轻微定住边缘，说明玉米鸡蛋饼可以开始摊饼。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('corn_egg_pancake', 3, '摊成圆饼', '倒入面糊摊开，看到玉米鸡蛋饼边缘变干、中间有小气泡。', 'pan_fry', array['corn', 'egg', 'flour']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('corn_egg_pancake', 4, '翻面煎透', '轻推玉米鸡蛋饼能移动时翻面，另一面出现浅色焦点，饼身不湿黏即可离火。', 'pan_fry', array['corn', 'egg', 'flour']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('corn_egg_pancake', 5, '切分上桌', '把玉米鸡蛋饼切成方便入口的大小，内部不湿黏时装盘。', 'plate_dish', array['corn', 'egg', 'flour']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('scallion_flour_pancake', 1, '调成面糊', '葱花切好备用，把面糊拌到能缓慢流动，没有大片干粉。', 'mix_sauce', array['flour', 'scallion']::text[], array['mixing_bowl']::text[], 4, null, ''),
  ('scallion_flour_pancake', 2, '热锅薄油', '平底锅加热后薄薄抹油，面糊落下能轻微定住边缘，说明简易葱花饼可以开始摊饼。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('scallion_flour_pancake', 3, '摊成圆饼', '倒入面糊摊开，看到简易葱花饼边缘变干、中间有小气泡。', 'pan_fry', array['flour', 'scallion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('scallion_flour_pancake', 4, '翻面煎透', '轻推简易葱花饼能移动时翻面，另一面出现浅色焦点，饼身不湿黏即可离火。', 'pan_fry', array['flour', 'scallion']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('scallion_flour_pancake', 5, '切分上桌', '把简易葱花饼切成方便入口的大小，内部不湿黏时装盘。', 'plate_dish', array['flour', 'scallion']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('cabbage_egg_pancake', 1, '调成面糊', '鸡蛋打散到蛋清蛋黄融合，卷心菜切成大小接近的块或段，把面糊拌到能缓慢流动，没有大片干粉。', 'mix_sauce', array['cabbage', 'egg', 'flour']::text[], array['mixing_bowl']::text[], 4, null, ''),
  ('cabbage_egg_pancake', 2, '热锅薄油', '平底锅加热后薄薄抹油，面糊落下能轻微定住边缘，说明卷心菜鸡蛋饼可以开始摊饼。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('cabbage_egg_pancake', 3, '摊成圆饼', '倒入面糊摊开，看到卷心菜鸡蛋饼边缘变干、中间有小气泡。', 'pan_fry', array['cabbage', 'egg', 'flour']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cabbage_egg_pancake', 4, '翻面煎透', '轻推卷心菜鸡蛋饼能移动时翻面，另一面出现浅色焦点，饼身不湿黏即可离火。', 'pan_fry', array['cabbage', 'egg', 'flour']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('cabbage_egg_pancake', 5, '切分上桌', '把卷心菜鸡蛋饼切成方便入口的大小，内部不湿黏时装盘。', 'plate_dish', array['cabbage', 'egg', 'flour']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('potato_egg_pancake', 1, '调成面糊', '鸡蛋打散到蛋清蛋黄融合，土豆切成大小接近的块或段，把面糊拌到能缓慢流动，没有大片干粉。', 'mix_sauce', array['potato', 'egg', 'flour']::text[], array['mixing_bowl']::text[], 4, null, ''),
  ('potato_egg_pancake', 2, '热锅薄油', '平底锅加热后薄薄抹油，面糊落下能轻微定住边缘，说明土豆鸡蛋饼可以开始摊饼。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('potato_egg_pancake', 3, '摊成圆饼', '倒入面糊摊开，看到土豆鸡蛋饼边缘变干、中间有小气泡。', 'pan_fry', array['potato', 'egg', 'flour']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('potato_egg_pancake', 4, '翻面煎透', '轻推土豆鸡蛋饼能移动时翻面，另一面出现浅色焦点，饼身不湿黏即可离火。', 'pan_fry', array['potato', 'egg', 'flour']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('potato_egg_pancake', 5, '切分上桌', '把土豆鸡蛋饼切成方便入口的大小，内部不湿黏时装盘。', 'plate_dish', array['potato', 'egg', 'flour']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('sweet_potato_oat_pancake', 1, '调成面糊', '鸡蛋打散到蛋清蛋黄融合，红薯切成大小接近的块或段，把面糊拌到能缓慢流动，没有大片干粉。', 'mix_sauce', array['sweet_potato', 'oats', 'egg']::text[], array['mixing_bowl']::text[], 4, null, ''),
  ('sweet_potato_oat_pancake', 2, '热锅薄油', '平底锅加热后薄薄抹油，面糊落下能轻微定住边缘，说明红薯燕麦饼可以开始摊饼。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('sweet_potato_oat_pancake', 3, '摊成圆饼', '倒入面糊摊开，看到红薯燕麦饼边缘变干、中间有小气泡。', 'pan_fry', array['sweet_potato', 'oats', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('sweet_potato_oat_pancake', 4, '翻面煎透', '轻推红薯燕麦饼能移动时翻面，另一面出现浅色焦点，饼身不湿黏即可离火。', 'pan_fry', array['sweet_potato', 'oats', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('sweet_potato_oat_pancake', 5, '切分上桌', '把红薯燕麦饼切成方便入口的大小，内部不湿黏时装盘。', 'plate_dish', array['sweet_potato', 'oats', 'egg']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('steamed_egg_custard', 1, '切配汤料', '鸡蛋打散到蛋清蛋黄融合，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['egg']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('steamed_egg_custard', 2, '先出香味', '锅中少量油处理鸡蛋，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['egg']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('steamed_egg_custard', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让家常蒸蛋受热更均匀。', 'boil_water', array['egg']::text[], array['pot']::text[], 4, null, ''),
  ('steamed_egg_custard', 4, '先煮耐煮', '先让水汽稳定后再上锅，蛋液表面轻轻晃动但没有大泡即可。', 'simmer', array['egg']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('steamed_egg_custard', 5, '再下易熟', '加入鸡蛋，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['egg']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('steamed_egg_custard', 6, '观察汤色', '小火煮到家常蒸蛋汤色更融合，主料状态达到蛋液边缘刚凝固、中间仍柔软。', 'check_doneness', array['egg']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('steamed_egg_custard', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让家常蒸蛋味道更均匀。', 'season', array['egg']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('steamed_egg_custard', 8, '盛出汤品', '把家常蒸蛋连汤带料盛出，碗里汤料比例均匀即可，外观整齐后上桌。', 'plate_dish', array['egg']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('microwave_tofu_egg', 1, '切配入碗', '鸡蛋打散到蛋清蛋黄融合，豆腐切块后轻轻吸掉表面水分，放进微波容器后铺平，中间不要堆太厚。', 'prep_ingredients', array['tofu', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('microwave_tofu_egg', 2, '加盖留缝', '容器盖上盖子或保鲜膜并留小缝，微波豆腐蒸蛋加热时水汽能散出。', 'microwave', array['tofu', 'egg']::text[], array['microwave']::text[], 1, null, ''),
  ('microwave_tofu_egg', 3, '分段微波', '先短时间加热，取出搅动或翻面，中心冒热气后再判断是否补热，让微波豆腐蒸蛋状态更稳定。', 'microwave', array['tofu', 'egg']::text[], array['microwave']::text[], 4, null, ''),
  ('microwave_tofu_egg', 4, '拌入调味', '加入调味后拌匀，看到微波豆腐蒸蛋表面湿润但碗底不积太多水。', 'season', array['tofu', 'egg']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('microwave_tofu_egg', 5, '静置再吃', '静置片刻让微波豆腐蒸蛋热度均匀，边缘不再滚烫，表面仍保持湿润时上桌。', 'rest_food', array['tofu', 'egg']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('rice_cooker_tomato_rice', 1, '淘米加水', '把米淘到水色变清，按平时口感加水，米面铺平再放配料，让电饭煲番茄饭米粒更稳定。', 'cook_rice', array['rice']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_tomato_rice', 2, '处理配料', '番茄切块，冷冻杂蔬保持颗粒分散，铺进电饭煲时尽量均匀，不要集中在一角。', 'slice_vegetables', array['tomato', 'frozen_mixed_vegetables']::text[], array['knife', 'cutting_board']::text[], 8, null, ''),
  ('rice_cooker_tomato_rice', 3, '铺料调味', '把番茄、冷冻杂蔬铺在米上，加调味后液面看起来均匀。', 'combine_ingredients', array['rice', 'tomato', 'frozen_mixed_vegetables']::text[], array['rice_cooker']::text[], 3, null, ''),
  ('rice_cooker_tomato_rice', 4, '启动煮饭', '按煮饭键加热，跳保温后不要立刻开盖，让水汽继续回到米粒里，让电饭煲番茄饭米粒更稳定。', 'cook_rice', array['rice', 'tomato', 'frozen_mixed_vegetables']::text[], array['rice_cooker']::text[], 30, null, ''),
  ('rice_cooker_tomato_rice', 5, '焖后开盖', '焖几分钟再开盖，看到电饭煲番茄饭米粒饱满、配料香气明显。', 'rest_food', array['rice', 'tomato', 'frozen_mixed_vegetables']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_tomato_rice', 6, '翻松米饭', '从锅边往中间翻松，米粒和配料分布均匀，不要把软料压碎，让电饭煲番茄饭状态更稳定。', 'combine_ingredients', array['rice', 'tomato', 'frozen_mixed_vegetables']::text[], array['rice_cooker', 'spatula']::text[], 3, null, ''),
  ('rice_cooker_tomato_rice', 7, '检查水位', '合盖前看电饭煲番茄饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_tomato_rice', 8, '焖饭吸味', '跳保温后让电饭煲番茄饭继续焖一会儿，米粒会更容易吸到配料香气。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_tomato_rice', 9, '检查锅底', '翻动前看锅底没有明显积水，电饭煲番茄饭米粒边缘已经饱满。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_tomato_rice', 10, '分散配料', '从锅边往中间翻，电饭煲番茄饭配料分散开，软料不要被压成泥。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_tomato_rice', 11, '检查水位', '合盖前看电饭煲番茄饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_tomato_rice', 12, '确认盛出', '尝一口米饭软硬合适，电饭煲番茄饭底部没有明显积水即可盛出。', 'check_doneness', array['rice', 'tomato', 'frozen_mixed_vegetables']::text[], array['rice_cooker']::text[], 1, null, ''),
  ('rice_cooker_mushroom_chicken', 1, '淘米加水', '把米淘到水色变清，按平时口感加水，米面铺平再放配料，让电饭煲蘑菇鸡肉饭米粒更稳定。', 'cook_rice', array['rice']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_mushroom_chicken', 2, '处理配料', '鸡腿肉切成薄片或小块，蘑菇切成大小接近的块或段，铺进电饭煲时尽量均匀，不要集中在一角。', 'cut_meat', array['chicken_thigh', 'mushroom']::text[], array['knife', 'cutting_board']::text[], 8, null, ''),
  ('rice_cooker_mushroom_chicken', 3, '铺料调味', '把鸡腿肉、蘑菇铺在米上，加调味后液面看起来均匀，确认状态后继续。', 'combine_ingredients', array['rice', 'chicken_thigh', 'mushroom']::text[], array['rice_cooker']::text[], 3, null, ''),
  ('rice_cooker_mushroom_chicken', 4, '启动煮饭', '按煮饭键加热，跳保温后不要立刻开盖，让水汽继续回到米粒里，让电饭煲蘑菇鸡肉饭米粒更稳定。', 'cook_rice', array['rice', 'chicken_thigh', 'mushroom']::text[], array['rice_cooker']::text[], 30, null, ''),
  ('rice_cooker_mushroom_chicken', 5, '焖后开盖', '焖几分钟再开盖，看到电饭煲蘑菇鸡肉饭米粒饱满、配料香气明显。', 'rest_food', array['rice', 'chicken_thigh', 'mushroom']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_mushroom_chicken', 6, '翻松米饭', '从锅边往中间翻松，米粒和配料分布均匀，不要把软料压碎，让电饭煲蘑菇鸡肉饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_thigh', 'mushroom']::text[], array['rice_cooker', 'spatula']::text[], 3, null, ''),
  ('rice_cooker_mushroom_chicken', 7, '检查水位', '合盖前看电饭煲蘑菇鸡肉饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_mushroom_chicken', 8, '焖饭吸味', '跳保温后让电饭煲蘑菇鸡肉饭继续焖一会儿，米粒会更容易吸到配料香气。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_mushroom_chicken', 9, '检查锅底', '翻动前看锅底没有明显积水，电饭煲蘑菇鸡肉饭米粒边缘已经饱满。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_mushroom_chicken', 10, '分散配料', '从锅边往中间翻，电饭煲蘑菇鸡肉饭配料分散开，软料不要被压成泥。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_mushroom_chicken', 11, '检查水位', '合盖前看电饭煲蘑菇鸡肉饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_mushroom_chicken', 12, '确认盛出', '尝一口米饭软硬合适，电饭煲蘑菇鸡肉饭底部没有明显积水即可盛出。', 'check_doneness', array['rice', 'chicken_thigh', 'mushroom']::text[], array['rice_cooker']::text[], 1, null, ''),
  ('rice_cooker_corn_egg_rice', 1, '淘米加水', '把米淘到水色变清，按平时口感加水，米面铺平再放配料，让电饭煲玉米鸡蛋饭米粒更稳定。', 'cook_rice', array['rice']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_corn_egg_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，玉米粒沥干，铺进电饭煲时尽量均匀，不要集中在一角。', 'slice_vegetables', array['corn', 'egg']::text[], array['knife', 'cutting_board']::text[], 8, null, ''),
  ('rice_cooker_corn_egg_rice', 3, '铺料调味', '把玉米、鸡蛋铺在米上，加调味后液面看起来均匀，确认状态后继续。', 'combine_ingredients', array['rice', 'corn', 'egg']::text[], array['rice_cooker']::text[], 3, null, ''),
  ('rice_cooker_corn_egg_rice', 4, '启动煮饭', '按煮饭键加热，跳保温后不要立刻开盖，让水汽继续回到米粒里，让电饭煲玉米鸡蛋饭米粒更稳定。', 'cook_rice', array['rice', 'corn', 'egg']::text[], array['rice_cooker']::text[], 30, null, ''),
  ('rice_cooker_corn_egg_rice', 5, '焖后开盖', '焖几分钟再开盖，看到电饭煲玉米鸡蛋饭米粒饱满、配料香气明显。', 'rest_food', array['rice', 'corn', 'egg']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_corn_egg_rice', 6, '翻松米饭', '从锅边往中间翻松，米粒和配料分布均匀，不要把软料压碎，让电饭煲玉米鸡蛋饭状态更稳定。', 'combine_ingredients', array['rice', 'corn', 'egg']::text[], array['rice_cooker', 'spatula']::text[], 3, null, ''),
  ('rice_cooker_corn_egg_rice', 7, '检查水位', '合盖前看电饭煲玉米鸡蛋饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_corn_egg_rice', 8, '焖饭吸味', '跳保温后让电饭煲玉米鸡蛋饭继续焖一会儿，米粒会更容易吸到配料香气。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
