  ('rice_cooker_corn_egg_rice', 10, '分散配料', '从锅边往中间翻，电饭煲玉米鸡蛋饭配料分散开，软料不要被压成泥。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
