  ('rice_cooker_corn_egg_rice', 12, '确认盛出', '尝一口米饭软硬合适，电饭煲玉米鸡蛋饭底部没有明显积水即可盛出。', 'check_doneness', array['rice', 'corn', 'egg']::text[], array['rice_cooker']::text[], 1, null, ''),
  ('bok_choy_noodle_soup', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让小白菜汤面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('bok_choy_noodle_soup', 2, '处理配料', '小白菜切成大小接近的块或段，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['bok_choy']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('bok_choy_noodle_soup', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给小白菜汤面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('bok_choy_noodle_soup', 4, '做出浇头', '锅中处理小白菜，看到蔬菜颜色变亮，边缘开始变软但仍有支撑感再加调味。', 'stir_fry', array['bok_choy']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('bok_choy_noodle_soup', 5, '兑成汤底', '加入热水或汤底，煮到汤色均匀，小白菜汤面的香味散开。', 'simmer', array['noodles', 'bok_choy']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('bok_choy_noodle_soup', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让小白菜汤面状态更稳定。', 'combine_ingredients', array['noodles', 'bok_choy']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('bok_choy_noodle_soup', 7, '检查口感', '夹起一筷子，面条有弹性、小白菜状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'bok_choy']::text[], array['tongs']::text[], 1, null, ''),
  ('bok_choy_noodle_soup', 8, '装碗出餐', '把小白菜汤面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'bok_choy']::text[], array['tongs']::text[], 1, null, ''),
  ('miso_tofu_noodles', 1, '烧水备面', '锅中水烧到持续冒泡，再放面条，这样面条受热更均匀，让味噌豆腐面受热更均匀。', 'boil_water', array['noodles']::text[], array['pot']::text[], 3, null, ''),
  ('miso_tofu_noodles', 2, '处理配料', '豆腐切块后轻轻吸掉表面水分，配料状态先准备好，避免面条煮好后久放成团。', 'slice_vegetables', array['tofu', 'miso']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('miso_tofu_noodles', 3, '煮到弹牙', '面条煮到能夹断但中心仍有弹性，捞出后轻轻沥水，给味噌豆腐面保留弹性。', 'boil_noodles', array['noodles']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('miso_tofu_noodles', 4, '做出浇头', '锅中处理豆腐、味噌，看到豆腐边缘微黄，轻推时还能保持块状再加调味。', 'stir_fry', array['tofu', 'miso']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('miso_tofu_noodles', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让味噌豆腐面质地更顺滑。', 'mix_sauce', array['noodles', 'tofu', 'miso']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('miso_tofu_noodles', 6, '合入面条', '把面条放回锅里拌开，面条不成团，表面开始均匀挂汁，让味噌豆腐面状态更稳定。', 'combine_ingredients', array['noodles', 'tofu', 'miso']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('miso_tofu_noodles', 7, '检查口感', '夹起一筷子，面条有弹性、豆腐、味噌状态合适，再决定是否补味。', 'check_doneness', array['noodles', 'tofu', 'miso']::text[], array['tongs']::text[], 1, null, ''),
  ('miso_tofu_noodles', 8, '装碗出餐', '把味噌豆腐面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['noodles', 'tofu', 'miso']::text[], array['tongs']::text[], 1, null, ''),
  ('gochujang_tofu_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收辣酱豆腐饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('gochujang_tofu_rice_bowl', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['tofu', 'gochujang']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('gochujang_tofu_rice_bowl', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让辣酱豆腐饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('gochujang_tofu_rice_bowl', 4, '加入配菜', '加入剩余tofu、gochujang翻匀，辣酱豆腐饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['tofu', 'gochujang']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('gochujang_tofu_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到红亮酱香散开但没有糊底，铲过锅底能短暂露出锅面。', 'simmer', array['tofu', 'gochujang']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('gochujang_tofu_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让辣酱豆腐饭状态更稳定。', 'combine_ingredients', array['rice', 'tofu', 'gochujang']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('gochujang_tofu_rice_bowl', 7, '整理浇头', '把辣酱豆腐饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('gochujang_tofu_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，辣酱豆腐饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'tofu', 'gochujang']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('curry_egg_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，咖喱鸡蛋炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('curry_egg_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，配料水分少一点，后面米饭不容易炒湿。', 'slice_vegetables', array['egg', 'curry_blocks']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('curry_egg_fried_rice', 3, '先炒配料', '锅热加油后先处理鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，再离火，让咖喱鸡蛋炒饭状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('curry_egg_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让咖喱鸡蛋炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('curry_egg_fried_rice', 5, '合入配料', '把鸡蛋、咖喱块和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'egg', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('curry_egg_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，咖喱鸡蛋炒饭不出现湿团。', 'season', array['rice', 'egg', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('curry_egg_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让咖喱鸡蛋炒饭状态更稳定。', 'check_doneness', array['rice', 'egg', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('curry_egg_fried_rice', 8, '盛出炒饭', '把咖喱鸡蛋炒饭盛入碗中，表面能看到配料均匀分布，外观整齐后上桌。', 'plate_dish', array['rice', 'egg', 'curry_blocks']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('air_fryer_chicken_potato', 1, '擦干食材', '鸡腿肉切成薄片或小块，土豆切成大小接近的块或段，表面水分少一点，空气炸锅鸡肉土豆边缘更容易变干爽。', 'prep_ingredients', array['chicken_thigh', 'potato']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('air_fryer_chicken_potato', 2, '抓匀调味', '加少量油、盐和调味料抓匀，食材表面能看到薄薄一层油光，让空气炸锅鸡肉土豆味道更均匀。', 'season', array['chicken_thigh', 'potato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('air_fryer_chicken_potato', 3, '平铺炸篮', '把食材放进炸篮，尽量单层铺开，边缘留出热风流动空间，让空气炸锅鸡肉土豆受热更均匀。', 'air_fry', array['chicken_thigh', 'potato']::text[], array['air_fryer']::text[], 2, null, ''),
  ('air_fryer_chicken_potato', 4, '中途翻动', '加热到边缘开始上色时翻动一次，肉类表面变色，锅底水汽明显减少。', 'air_fry', array['chicken_thigh', 'potato']::text[], array['air_fryer', 'tongs']::text[], 12, null, ''),
  ('air_fryer_chicken_potato', 5, '出篮静置', '空气炸锅鸡肉土豆外层干爽、中心状态合适后取出，静置片刻再装盘。', 'rest_food', array['chicken_thigh', 'potato']::text[], array['air_fryer', 'tongs']::text[], 2, null, ''),
  ('air_fryer_tofu_broccoli', 1, '擦干食材', '豆腐切块后轻轻吸掉表面水分，西兰花切成大小接近的块或段，表面水分少一点，空气炸锅豆腐西兰花边缘更容易变干爽。', 'prep_ingredients', array['tofu', 'broccoli']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('air_fryer_tofu_broccoli', 2, '抓匀调味', '加少量油、盐和调味料抓匀，食材表面能看到薄薄一层油光，让空气炸锅豆腐西兰花味道更均匀。', 'season', array['tofu', 'broccoli']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('air_fryer_tofu_broccoli', 3, '平铺炸篮', '把食材放进炸篮，尽量单层铺开，边缘留出热风流动空间，让空气炸锅豆腐西兰花受热更均匀。', 'air_fry', array['tofu', 'broccoli']::text[], array['air_fryer']::text[], 2, null, ''),
  ('air_fryer_tofu_broccoli', 4, '中途翻动', '加热到边缘开始上色时翻动一次，豆腐边缘微黄，轻推时还能保持块状。', 'air_fry', array['tofu', 'broccoli']::text[], array['air_fryer', 'tongs']::text[], 12, null, ''),
  ('air_fryer_tofu_broccoli', 5, '出篮静置', '空气炸锅豆腐西兰花外层干爽、中心状态合适后取出，静置片刻再装盘。', 'rest_food', array['tofu', 'broccoli']::text[], array['air_fryer', 'tongs']::text[], 2, null, ''),
  ('air_fryer_sweet_potato_egg', 1, '擦干食材', '鸡蛋打散到蛋清蛋黄融合，红薯切成大小接近的块或段，表面水分少一点，空气炸锅红薯鸡蛋盘边缘更容易变干爽。', 'prep_ingredients', array['sweet_potato', 'egg']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('air_fryer_sweet_potato_egg', 2, '抓匀调味', '加少量油、盐和调味料抓匀，食材表面能看到薄薄一层油光，让空气炸锅红薯鸡蛋盘味道更均匀。', 'season', array['sweet_potato', 'egg']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('air_fryer_sweet_potato_egg', 3, '平铺炸篮', '把食材放进炸篮，尽量单层铺开，边缘留出热风流动空间，让空气炸锅红薯鸡蛋盘受热更均匀。', 'air_fry', array['sweet_potato', 'egg']::text[], array['air_fryer']::text[], 2, null, ''),
  ('air_fryer_sweet_potato_egg', 4, '中途翻动', '加热到边缘开始上色时翻动一次，蛋液边缘刚凝固、中间仍柔软。', 'air_fry', array['sweet_potato', 'egg']::text[], array['air_fryer', 'tongs']::text[], 12, null, ''),
  ('air_fryer_sweet_potato_egg', 5, '出篮静置', '空气炸锅红薯鸡蛋盘外层干爽、中心状态合适后取出，静置片刻再装盘。', 'rest_food', array['sweet_potato', 'egg']::text[], array['air_fryer', 'tongs']::text[], 2, null, ''),
  ('tuna_potato_salad', 1, '清洗沥干', '土豆、黄瓜处理后沥干，叶菜或水果表面不挂水，确认状态后继续。', 'wash_ingredients', array['canned_tuna', 'potato', 'cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tuna_potato_salad', 2, '沥干罐头', '金枪鱼罐头沥掉多余汤水并拨散，拌入后不容易让沙拉出水。', 'prep_ingredients', array['canned_tuna']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_potato_salad', 3, '切成入口', '金枪鱼罐头沥干并拨散，土豆切成大小接近的块或段，黄瓜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['canned_tuna', 'potato', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('tuna_potato_salad', 4, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进金枪鱼土豆沙拉里。', 'mix_sauce', array['canned_tuna', 'potato', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_potato_salad', 5, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让金枪鱼土豆沙拉保持清爽。', 'toss_salad', array['canned_tuna', 'potato', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tuna_potato_salad', 6, '装盘检查', '金枪鱼土豆沙拉看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['canned_tuna', 'potato', 'cucumber']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('cold_tofu_cucumber_salad', 1, '清洗沥干', '豆腐、黄瓜处理后沥干，叶菜或水果表面不挂水，确认状态后继续。', 'wash_ingredients', array['tofu', 'cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('cold_tofu_cucumber_salad', 2, '切成入口', '豆腐切块后轻轻吸掉表面水分，黄瓜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['tofu', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('cold_tofu_cucumber_salad', 3, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进黄瓜拌豆腐里。', 'mix_sauce', array['tofu', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('cold_tofu_cucumber_salad', 4, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让黄瓜拌豆腐保持清爽。', 'toss_salad', array['tofu', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('cold_tofu_cucumber_salad', 5, '装盘检查', '黄瓜拌豆腐看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['tofu', 'cucumber']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('tomato_cucumber_salad', 1, '清洗沥干', '番茄、黄瓜处理后沥干，叶菜或水果表面不挂水，确认状态后继续。', 'wash_ingredients', array['tomato', 'cucumber']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('tomato_cucumber_salad', 2, '切成入口', '番茄切成大小接近的块或段，黄瓜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['tomato', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('tomato_cucumber_salad', 3, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进番茄黄瓜沙拉里。', 'mix_sauce', array['tomato', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tomato_cucumber_salad', 4, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让番茄黄瓜沙拉保持清爽。', 'toss_salad', array['tomato', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tomato_cucumber_salad', 5, '装盘检查', '番茄黄瓜沙拉看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['tomato', 'cucumber']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('avocado_egg_salad_toast', 1, '备好底胚', '面包放平，边缘没有破口或过湿，后面夹馅才不容易散开，让牛油果鸡蛋沙拉吐司状态更稳定。', 'prep_ingredients', array['bread']::text[], array['cutting_board']::text[], 1, null, ''),
  ('avocado_egg_salad_toast', 2, '处理夹馅', '鸡蛋打散到蛋清蛋黄融合，牛油果切好后保持清爽不出水，水分控制住，牛油果鸡蛋沙拉吐司卷起来才更稳。', 'slice_vegetables', array['avocado', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('avocado_egg_salad_toast', 3, '处理熟馅', '把需要加热的鸡蛋处理到蛋液边缘刚凝固、中间仍柔软，放到不烫手再组合，让牛油果鸡蛋沙拉吐司状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('avocado_egg_salad_toast', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免牛油果鸡蛋沙拉吐司一卷就往外溢。', 'mix_sauce', array['bread', 'avocado', 'egg']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('avocado_egg_salad_toast', 5, '铺料卷起', '把牛油果、鸡蛋放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['bread', 'avocado', 'egg']::text[], array['cutting_board']::text[], 3, null, ''),
  ('avocado_egg_salad_toast', 6, '切分检查', '切开后看馅料没有集中滑出，牛油果鸡蛋沙拉吐司拿起时不松散即可。', 'plate_dish', array['bread', 'avocado', 'egg']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('chickpea_spinach_stew', 1, '切配汤料', '鹰嘴豆罐头、番茄罐头沥干并拨散，菠菜切成大小接近的块或段，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('chickpea_spinach_stew', 2, '先出香味', '锅中少量油处理菠菜，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('chickpea_spinach_stew', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让鹰嘴豆菠菜炖菜受热更均匀。', 'boil_water', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot']::text[], 4, null, ''),
  ('chickpea_spinach_stew', 4, '先煮耐煮', '先放鹰嘴豆罐头，煮到边缘开始变软，汤色稳定后继续。', 'simmer', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('chickpea_spinach_stew', 5, '再下易熟', '加入菠菜，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('chickpea_spinach_stew', 6, '观察汤色', '小火煮到鹰嘴豆菠菜炖菜汤色更融合，主料状态达到罐头食材热透或拌匀，不需要久炒。', 'check_doneness', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('chickpea_spinach_stew', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让鹰嘴豆菠菜炖菜味道更均匀。', 'season', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('chickpea_spinach_stew', 8, '盛出汤品', '把鹰嘴豆菠菜炖菜连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['canned_chickpeas', 'spinach', 'canned_tomato']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('black_bean_tomato_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收黑豆番茄饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('black_bean_tomato_rice', 2, '切配浇头', '黑豆罐头沥干并拨散，番茄切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['canned_black_beans', 'tomato']::text[], array['knife', 'cutting_board']::text[], 6, null, '')
;

