  ('tuna_spinach_pasta', 7, '检查口感', '夹起一筷子，面条有弹性、金枪鱼罐头、菠菜状态合适，再决定是否补味。', 'check_doneness', array['pasta', 'canned_tuna', 'spinach']::text[], array['tongs']::text[], 1, null, ''),
  ('tuna_spinach_pasta', 8, '装碗出餐', '把金枪鱼菠菜意面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['pasta', 'canned_tuna', 'spinach']::text[], array['tongs']::text[], 1, null, ''),
  ('chicken_tomato_pasta', 1, '烧水备面', '锅中水烧到持续冒泡，再放意面，这样面条受热更均匀，让鸡肉番茄意面受热更均匀。', 'boil_water', array['pasta']::text[], array['pot']::text[], 3, null, ''),
  ('chicken_tomato_pasta', 2, '处理配料', '鸡胸肉切成薄片或小块，番茄罐头沥干并拨散，配料状态先准备好，避免面条煮好后久放成团。', 'cut_meat', array['chicken_breast', 'canned_tomato']::text[], array['knife', 'cutting_board']::text[], 5, null, ''),
  ('chicken_tomato_pasta', 3, '煮到弹牙', '意面煮到能夹断但中心仍有弹性，留一小勺面水再沥出，给鸡肉番茄意面保留弹性。', 'boil_noodles', array['pasta']::text[], array['pot', 'tongs']::text[], 6, null, ''),
  ('chicken_tomato_pasta', 4, '做出浇头', '锅中处理鸡胸肉、番茄罐头，看到肉类表面变色，锅底水汽明显减少再加调味。', 'sear_meat', array['chicken_breast', 'canned_tomato']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('chicken_tomato_pasta', 5, '调成酱汁', '加入酱料和少量面水，推到酱汁变顺滑，能薄薄挂在铲面，让鸡肉番茄意面质地更顺滑。', 'mix_sauce', array['pasta', 'chicken_breast', 'canned_tomato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('chicken_tomato_pasta', 6, '合入面条', '把意面放回锅里拌开，面条不成团，表面开始均匀挂汁，让鸡肉番茄意面状态更稳定。', 'combine_ingredients', array['pasta', 'chicken_breast', 'canned_tomato']::text[], array['pan', 'tongs']::text[], 3, null, ''),
  ('chicken_tomato_pasta', 7, '检查口感', '夹起一筷子，面条有弹性、鸡胸肉、番茄罐头状态合适，再决定是否补味。', 'check_doneness', array['pasta', 'chicken_breast', 'canned_tomato']::text[], array['tongs']::text[], 1, null, ''),
  ('chicken_tomato_pasta', 8, '装碗出餐', '把鸡肉番茄意面盛出，面条和配料交错分布，碗底不要只剩清水。', 'plate_dish', array['pasta', 'chicken_breast', 'canned_tomato']::text[], array['tongs']::text[], 1, null, ''),
  ('salmon_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收三文鱼饭碗的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('salmon_rice_bowl', 2, '切配浇头', '三文鱼擦干并切成厚度接近的块，黄瓜切好后保持清爽不出水，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['salmon', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('salmon_rice_bowl', 3, '做出底味', '锅热后先处理三文鱼，看到鱼肉由透明转白，能轻轻推动但不碎。', 'stir_fry', array['salmon']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('salmon_rice_bowl', 4, '加入配菜', '加入剩余salmon、cucumber翻匀，三文鱼饭碗的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['salmon', 'cucumber']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('salmon_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到三文鱼饭碗的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['salmon', 'cucumber']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('salmon_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让三文鱼饭碗状态更稳定。', 'combine_ingredients', array['rice', 'salmon', 'cucumber']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('salmon_rice_bowl', 7, '整理浇头', '把三文鱼饭碗浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('salmon_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，三文鱼饭碗咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'salmon', 'cucumber']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('shrimp_avocado_wrap', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让虾仁牛油果卷饼状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('shrimp_avocado_wrap', 2, '处理夹馅', '虾仁沥干到表面不挂水，牛油果切好后保持清爽不出水，水分控制住，虾仁牛油果卷饼卷起来才更稳。', 'slice_vegetables', array['shrimp', 'avocado']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('shrimp_avocado_wrap', 3, '处理熟馅', '把需要加热的虾仁处理到虾仁由半透明转粉并自然卷起，放到不烫手再组合。', 'scramble_eggs', array['shrimp']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('shrimp_avocado_wrap', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免虾仁牛油果卷饼一卷就往外溢。', 'mix_sauce', array['tortilla', 'shrimp', 'avocado']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('shrimp_avocado_wrap', 5, '铺料卷起', '把虾仁、牛油果放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'shrimp', 'avocado']::text[], array['cutting_board']::text[], 3, null, ''),
  ('shrimp_avocado_wrap', 6, '切分检查', '切开后看馅料没有集中滑出，虾仁牛油果卷饼拿起时不松散即可。', 'plate_dish', array['tortilla', 'shrimp', 'avocado']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('tofu_lettuce_wrap', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让豆腐生菜卷状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('tofu_lettuce_wrap', 2, '处理夹馅', '豆腐切块后轻轻吸掉表面水分，生菜切好后保持清爽不出水，水分控制住，豆腐生菜卷卷起来才更稳。', 'slice_vegetables', array['tofu', 'lettuce']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('tofu_lettuce_wrap', 3, '处理熟馅', '把需要加热的豆腐处理到豆腐边缘微黄，轻推时还能保持块状，放到不烫手再组合。', 'scramble_eggs', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('tofu_lettuce_wrap', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免豆腐生菜卷一卷就往外溢。', 'mix_sauce', array['tortilla', 'tofu', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('tofu_lettuce_wrap', 5, '铺料卷起', '把豆腐、生菜放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'tofu', 'lettuce']::text[], array['cutting_board']::text[], 3, null, ''),
  ('tofu_lettuce_wrap', 6, '切分检查', '切开后看馅料没有集中滑出，豆腐生菜卷拿起时不松散即可。', 'plate_dish', array['tortilla', 'tofu', 'lettuce']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('egg_lettuce_toast', 1, '备好底胚', '面包放平，边缘没有破口或过湿，后面夹馅才不容易散开，让鸡蛋生菜吐司状态更稳定。', 'prep_ingredients', array['bread']::text[], array['cutting_board']::text[], 1, null, ''),
  ('egg_lettuce_toast', 2, '处理夹馅', '鸡蛋打散到蛋清蛋黄融合，生菜切好后保持清爽不出水，水分控制住，鸡蛋生菜吐司卷起来才更稳。', 'slice_vegetables', array['egg', 'lettuce']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('egg_lettuce_toast', 3, '处理熟馅', '把需要加热的鸡蛋处理到蛋液边缘刚凝固、中间仍柔软，放到不烫手再组合，让鸡蛋生菜吐司状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('egg_lettuce_toast', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免鸡蛋生菜吐司一卷就往外溢。', 'mix_sauce', array['bread', 'egg', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('egg_lettuce_toast', 5, '铺料卷起', '把鸡蛋、生菜放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['bread', 'egg', 'lettuce']::text[], array['cutting_board']::text[], 3, null, ''),
  ('egg_lettuce_toast', 6, '切分检查', '切开后看馅料没有集中滑出，鸡蛋生菜吐司拿起时不松散即可。', 'plate_dish', array['bread', 'egg', 'lettuce']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('banana_apple_oat_bowl', 1, '切配入碗', '香蕉、苹果切好后保持清爽不出水，放进微波容器后铺平，中间不要堆太厚。', 'prep_ingredients', array['oats', 'banana', 'apple']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('banana_apple_oat_bowl', 2, '加盖留缝', '容器盖上盖子或保鲜膜并留小缝，香蕉苹果燕麦碗加热时水汽能散出。', 'microwave', array['oats', 'banana', 'apple']::text[], array['microwave']::text[], 1, null, ''),
  ('banana_apple_oat_bowl', 3, '分段微波', '先短时间加热，取出搅动或翻面，中心冒热气后再判断是否补热，让香蕉苹果燕麦碗状态更稳定。', 'microwave', array['oats', 'banana', 'apple']::text[], array['microwave']::text[], 4, null, ''),
  ('banana_apple_oat_bowl', 4, '拌入调味', '加入调味后拌匀，看到香蕉苹果燕麦碗表面湿润但碗底不积太多水。', 'season', array['oats', 'banana', 'apple']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('banana_apple_oat_bowl', 5, '静置再吃', '静置片刻让香蕉苹果燕麦碗热度均匀，边缘不再滚烫，表面仍保持湿润时上桌。', 'rest_food', array['oats', 'banana', 'apple']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('peanut_raisin_oats', 1, '切配入碗', '葡萄干切成大小接近的块或段，放进微波容器后铺平，中间不要堆太厚。', 'prep_ingredients', array['oats', 'peanut_butter', 'raisins']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('peanut_raisin_oats', 2, '加盖留缝', '容器盖上盖子或保鲜膜并留小缝，花生酱葡萄干燕麦加热时水汽能散出。', 'microwave', array['oats', 'peanut_butter', 'raisins']::text[], array['microwave']::text[], 1, null, ''),
  ('peanut_raisin_oats', 3, '分段微波', '先短时间加热，取出搅动或翻面，中心冒热气后再判断是否补热，让花生酱葡萄干燕麦状态更稳定。', 'microwave', array['oats', 'peanut_butter', 'raisins']::text[], array['microwave']::text[], 4, null, ''),
  ('peanut_raisin_oats', 4, '拌入调味', '加入调味后拌匀，看到花生酱葡萄干燕麦表面湿润但碗底不积太多水。', 'season', array['oats', 'peanut_butter', 'raisins']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('peanut_raisin_oats', 5, '静置再吃', '静置片刻让花生酱葡萄干燕麦热度均匀，边缘不再滚烫，表面仍保持湿润时上桌。', 'rest_food', array['oats', 'peanut_butter', 'raisins']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('orange_chicken_salad', 1, '清洗沥干', '鸡胸肉、橙子、生菜处理后沥干，叶菜或水果表面不挂水。', 'wash_ingredients', array['chicken_breast', 'orange', 'lettuce']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('orange_chicken_salad', 2, '处理蛋白', '把鸡胸肉处理到肉类表面变色，锅底水汽明显减少，放凉一点再进沙拉。', 'pan_fry', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('orange_chicken_salad', 3, '切成入口', '橙子、生菜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['chicken_breast', 'orange', 'lettuce']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('orange_chicken_salad', 4, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进橙香鸡胸沙拉里。', 'mix_sauce', array['chicken_breast', 'orange', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('orange_chicken_salad', 5, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让橙香鸡胸沙拉保持清爽。', 'toss_salad', array['chicken_breast', 'orange', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('orange_chicken_salad', 6, '装盘检查', '橙香鸡胸沙拉看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['chicken_breast', 'orange', 'lettuce']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('grape_chicken_salad', 1, '清洗沥干', '鸡胸肉、葡萄、生菜处理后沥干，叶菜或水果表面不挂水。', 'wash_ingredients', array['chicken_breast', 'grapes', 'lettuce']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('grape_chicken_salad', 2, '处理蛋白', '把鸡胸肉处理到肉类表面变色，锅底水汽明显减少，放凉一点再进沙拉。', 'pan_fry', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('grape_chicken_salad', 3, '切成入口', '葡萄、生菜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['chicken_breast', 'grapes', 'lettuce']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('grape_chicken_salad', 4, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进葡萄鸡胸沙拉里。', 'mix_sauce', array['chicken_breast', 'grapes', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('grape_chicken_salad', 5, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让葡萄鸡胸沙拉保持清爽。', 'toss_salad', array['chicken_breast', 'grapes', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('grape_chicken_salad', 6, '装盘检查', '葡萄鸡胸沙拉看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['chicken_breast', 'grapes', 'lettuce']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('pear_tuna_salad', 1, '清洗沥干', '梨、生菜处理后沥干，叶菜或水果表面不挂水，确认状态后继续。', 'wash_ingredients', array['canned_tuna', 'pear', 'lettuce']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('pear_tuna_salad', 2, '沥干罐头', '金枪鱼罐头沥掉多余汤水并拨散，拌入后不容易让沙拉出水。', 'prep_ingredients', array['canned_tuna']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('pear_tuna_salad', 3, '切成入口', '金枪鱼罐头沥干并拨散，梨、生菜切好后保持清爽不出水，大小适合一勺入口。', 'slice_vegetables', array['canned_tuna', 'pear', 'lettuce']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('pear_tuna_salad', 4, '调好酱汁', '先把酱汁调匀，尝到酸甜咸淡平衡，再倒进梨子金枪鱼沙拉里。', 'mix_sauce', array['canned_tuna', 'pear', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('pear_tuna_salad', 5, '轻轻拌匀', '从碗底往上翻拌，看到酱汁薄薄裹住食材，但叶菜和水果不被压烂，让梨子金枪鱼沙拉保持清爽。', 'toss_salad', array['canned_tuna', 'pear', 'lettuce']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('pear_tuna_salad', 6, '装盘检查', '梨子金枪鱼沙拉看起来清爽、不积水，主料分布均匀时就可以端出。', 'plate_dish', array['canned_tuna', 'pear', 'lettuce']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('pineapple_chicken_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收菠萝鸡肉饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('pineapple_chicken_rice', 2, '切配浇头', '鸡胸肉切成薄片或小块，菠萝罐头沥干并拨散，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['chicken_breast', 'canned_pineapple']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('pineapple_chicken_rice', 3, '做出底味', '锅热后先处理鸡胸肉，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('pineapple_chicken_rice', 4, '加入配菜', '加入剩余chicken breast、canned pineapple翻匀，菠萝鸡肉饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['chicken_breast', 'canned_pineapple']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('pineapple_chicken_rice', 5, '收成浇头', '加调味或少量水，煮到菠萝鸡肉饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['chicken_breast', 'canned_pineapple']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('pineapple_chicken_rice', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让菠萝鸡肉饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_breast', 'canned_pineapple']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('pineapple_chicken_rice', 7, '整理浇头', '把菠萝鸡肉饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('pineapple_chicken_rice', 8, '确认盖饭', '尝一口浇头和饭，菠萝鸡肉饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'chicken_breast', 'canned_pineapple']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('cabbage_sausage_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收卷心菜香肠饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('cabbage_sausage_rice', 2, '切配浇头', '卷心菜切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['sausage', 'cabbage']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('cabbage_sausage_rice', 3, '做出底味', '锅热后先处理香肠，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['sausage']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('cabbage_sausage_rice', 4, '加入配菜', '加入剩余sausage、cabbage翻匀，卷心菜香肠饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['sausage', 'cabbage']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cabbage_sausage_rice', 5, '收成浇头', '加调味或少量水，煮到卷心菜香肠饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['sausage', 'cabbage']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('cabbage_sausage_rice', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让卷心菜香肠饭状态更稳定。', 'combine_ingredients', array['rice', 'sausage', 'cabbage']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('cabbage_sausage_rice', 7, '整理浇头', '把卷心菜香肠饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('cabbage_sausage_rice', 8, '确认盖饭', '尝一口浇头和饭，卷心菜香肠饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'sausage', 'cabbage']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('bacon_egg_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，培根鸡蛋炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('bacon_egg_fried_rice', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，配料水分少一点，后面米饭不容易炒湿。', 'cut_meat', array['bacon', 'egg']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('bacon_egg_fried_rice', 3, '先炒配料', '锅热加油后先处理培根、鸡蛋，看到蛋液边缘刚凝固、中间仍柔软，让培根鸡蛋炒饭状态更稳定。', 'scramble_eggs', array['bacon', 'egg']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('bacon_egg_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让培根鸡蛋炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('bacon_egg_fried_rice', 5, '合入配料', '把培根、鸡蛋和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'bacon', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('bacon_egg_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，培根鸡蛋炒饭不出现湿团。', 'season', array['rice', 'bacon', 'egg']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('bacon_egg_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让培根鸡蛋炒饭状态更稳定。', 'check_doneness', array['rice', 'bacon', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('bacon_egg_fried_rice', 8, '盛出炒饭', '把培根鸡蛋炒饭盛入碗中，表面能看到配料均匀分布，外观整齐后上桌。', 'plate_dish', array['rice', 'bacon', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('chicken_wings_potato_pan', 1, '处理食材', '鸡翅切成薄片或小块，土豆切成大小接近的块或段，看一遍顺序，鸡翅土豆锅下锅后就不用临时找东西。', 'prep_ingredients', array['chicken_wings', 'potato']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('chicken_wings_potato_pan', 2, '清洗沥水', '土豆冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['potato']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('chicken_wings_potato_pan', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明鸡翅土豆锅可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('chicken_wings_potato_pan', 4, '处理主料', '放入鸡翅摊开受热，看到肉类表面变色，锅底水汽明显减少再翻动或拨到锅边。', 'sear_meat', array['chicken_wings']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('chicken_wings_potato_pan', 5, '加入配菜', '加入土豆翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['potato']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('chicken_wings_potato_pan', 6, '合炒入味', '把锅中食材合在一起，调味后看到鸡翅土豆锅的主味均匀裹在食材上。', 'combine_ingredients', array['chicken_wings', 'potato']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('chicken_wings_potato_pan', 7, '调整火候', '转中火让鸡翅土豆锅继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_wings_potato_pan', 8, '观察主料', '夹起主要食材看颜色和质地，鸡翅土豆锅没有明显生硬感再进入收尾。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_wings_potato_pan', 9, '回锅收味', '把边缘食材推回锅心，鸡翅土豆锅味道重新裹匀，锅底不留大量水汽。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_wings_potato_pan', 10, '试味调整', '尝一小口汤汁或配菜，鸡翅土豆锅咸淡清楚但不过重，再决定是否补味。', 'season', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_wings_potato_pan', 11, '调整火候', '转中火让鸡翅土豆锅继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('chicken_wings_potato_pan', 12, '装盘检查', '确认鸡翅土豆锅肉类表面变色，锅底水汽明显减少，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['chicken_wings', 'potato']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 1, '淘米加水', '把米淘到水色变清，按平时口感加水，米面铺平再放配料，让电饭煲酱油鸡腿饭米粒更稳定。', 'cook_rice', array['rice']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 2, '处理配料', '鸡腿切成薄片或小块，姜切好备用，铺进电饭煲时尽量均匀，不要集中在一角。', 'cut_meat', array['chicken_drumstick', 'ginger']::text[], array['knife', 'cutting_board']::text[], 8, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 3, '铺料调味', '把鸡腿、姜铺在米上，加调味后液面看起来均匀，确认状态后继续。', 'combine_ingredients', array['rice', 'chicken_drumstick', 'ginger']::text[], array['rice_cooker']::text[], 3, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 4, '启动煮饭', '按煮饭键加热，跳保温后不要立刻开盖，让水汽继续回到米粒里，让电饭煲酱油鸡腿饭米粒更稳定。', 'cook_rice', array['rice', 'chicken_drumstick', 'ginger']::text[], array['rice_cooker']::text[], 30, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 5, '焖后开盖', '焖几分钟再开盖，看到电饭煲酱油鸡腿饭米粒饱满、配料香气明显。', 'rest_food', array['rice', 'chicken_drumstick', 'ginger']::text[], array['rice_cooker']::text[], 5, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 6, '翻松米饭', '从锅边往中间翻松，米粒和配料分布均匀，不要把软料压碎，让电饭煲酱油鸡腿饭状态更稳定。', 'combine_ingredients', array['rice', 'chicken_drumstick', 'ginger']::text[], array['rice_cooker', 'spatula']::text[], 3, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 7, '检查水位', '合盖前看电饭煲酱油鸡腿饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 8, '焖饭吸味', '跳保温后让电饭煲酱油鸡腿饭继续焖一会儿，米粒会更容易吸到配料香气。', 'rest_food', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 9, '检查锅底', '翻动前看锅底没有明显积水，电饭煲酱油鸡腿饭米粒边缘已经饱满。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 10, '分散配料', '从锅边往中间翻，电饭煲酱油鸡腿饭配料分散开，软料不要被压成泥。', 'combine_ingredients', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 11, '检查水位', '合盖前看电饭煲酱油鸡腿饭水位均匀，米面平整，配料没有堆成高包。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('rice_cooker_drumstick_soy_chicken', 12, '确认盛出', '尝一口米饭软硬合适，电饭煲酱油鸡腿饭底部没有明显积水即可盛出。', 'check_doneness', array['rice', 'chicken_drumstick', 'ginger']::text[], array['rice_cooker']::text[], 1, null, ''),
  ('pork_chop_onion_pan', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收洋葱猪排饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('pork_chop_onion_pan', 2, '切配浇头', '猪排切成薄片或小块，洋葱切好备用，大小接近，盖到饭上时每一口都能吃到主料。', 'cut_meat', array['pork_chop', 'onion']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('pork_chop_onion_pan', 3, '做出底味', '锅热后先处理猪排，看到肉类表面变色，锅底水汽明显减少。', 'sear_meat', array['pork_chop']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('pork_chop_onion_pan', 4, '加入配菜', '加入剩余pork chop、onion翻匀，洋葱猪排饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['pork_chop', 'onion']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('pork_chop_onion_pan', 5, '收成浇头', '加调味或少量水，煮到洋葱猪排饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['pork_chop', 'onion']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('pork_chop_onion_pan', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让洋葱猪排饭状态更稳定。', 'combine_ingredients', array['rice', 'pork_chop', 'onion']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('pork_chop_onion_pan', 7, '整理浇头', '把洋葱猪排饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('pork_chop_onion_pan', 8, '确认盖饭', '尝一口浇头和饭，洋葱猪排饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'pork_chop', 'onion']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('turkey_breast_cucumber_wrap', 1, '备好底胚', '卷饼皮放平，边缘没有破口或过湿，后面夹馅才不容易散开，让火鸡胸黄瓜卷饼状态更稳定。', 'prep_ingredients', array['tortilla']::text[], array['cutting_board']::text[], 1, null, ''),
  ('turkey_breast_cucumber_wrap', 2, '处理夹馅', '火鸡胸肉切成薄片或小块，黄瓜切好后保持清爽不出水，水分控制住，火鸡胸黄瓜卷饼卷起来才更稳。', 'cut_meat', array['turkey_breast', 'cucumber']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('turkey_breast_cucumber_wrap', 3, '处理熟馅', '把需要加热的火鸡胸肉处理到肉类表面变色，锅底水汽明显减少，放到不烫手再组合。', 'pan_fry', array['turkey_breast']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('turkey_breast_cucumber_wrap', 4, '涂抹底味', '把酱料薄薄涂开，边缘留一点空位，避免火鸡胸黄瓜卷饼一卷就往外溢。', 'mix_sauce', array['tortilla', 'turkey_breast', 'cucumber']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('turkey_breast_cucumber_wrap', 5, '铺料卷起', '把火鸡胸肉、黄瓜放在中线附近，压紧后卷起或合上，结构能保持住。', 'combine_ingredients', array['tortilla', 'turkey_breast', 'cucumber']::text[], array['cutting_board']::text[], 3, null, ''),
  ('turkey_breast_cucumber_wrap', 6, '切分检查', '切开后看馅料没有集中滑出，火鸡胸黄瓜卷饼拿起时不松散即可。', 'plate_dish', array['tortilla', 'turkey_breast', 'cucumber']::text[], array['knife', 'cutting_board']::text[], 1, null, ''),
  ('scallop_corn_egg_stir_fry', 1, '处理食材', '鸡蛋打散到蛋清蛋黄融合，扇贝擦干表面水分，玉米粒沥干，看一遍顺序，扇贝玉米滑蛋下锅后就不用临时找东西。', 'prep_ingredients', array['scallops', 'corn', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('scallop_corn_egg_stir_fry', 2, '清洗沥水', '玉米冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['corn']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('scallop_corn_egg_stir_fry', 3, '热锅下油', '锅面热后加油，油能流动铺开，说明扇贝玉米滑蛋可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('scallop_corn_egg_stir_fry', 4, '炒成嫩蛋', '蛋液入锅后用铲子轻推，边缘刚凝固、中间仍柔软时先盛出，让扇贝玉米滑蛋状态更稳定。', 'scramble_eggs', array['egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('scallop_corn_egg_stir_fry', 5, '处理主料', '放入扇贝摊开受热，看到扇贝表面变白、中心仍显得饱满再翻动或拨到锅边。', 'sear_meat', array['scallops']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('scallop_corn_egg_stir_fry', 6, '加入配菜', '加入玉米翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['corn']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('scallop_corn_egg_stir_fry', 7, '合炒入味', '把锅中食材合在一起，调味后看到扇贝玉米滑蛋的主味均匀裹在食材上。', 'combine_ingredients', array['scallops', 'corn', 'egg']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('scallop_corn_egg_stir_fry', 8, '装盘检查', '确认扇贝玉米滑蛋扇贝表面变白、中心仍显得饱满，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['scallops', 'corn', 'egg']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 1, '松散米饭', '米饭加热或放到温热，压散到没有硬块，蟹肉棒黄瓜鸡蛋饭吃起来才不夹生硬饭团。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 2, '处理配料', '鸡蛋打散到蛋清蛋黄融合，蟹肉棒沥干并拨散，黄瓜切好后保持清爽不出水，生食配料保持清爽，罐头食材不要带太多汤水。', 'prep_ingredients', array['imitation_crab', 'cucumber', 'egg']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 5, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 3, '调好拌汁', '把盐、酱油或轻口酱汁先调匀，尝到咸淡柔和再倒入饭碗。', 'mix_sauce', array[]::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 4, '铺上配料', '把蟹肉棒、黄瓜、鸡蛋铺在米饭上，颜色和口感分区清楚，拌起来更均匀。', 'combine_ingredients', array['rice', 'imitation_crab', 'cucumber', 'egg']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 5, '轻拌饭碗', '从碗边往中间轻拌，看到米饭吸到酱汁但蟹肉棒、黄瓜仍有形状。', 'toss_salad', array['rice', 'imitation_crab', 'cucumber', 'egg']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 6, '整理浇头', '把蟹肉棒黄瓜鸡蛋饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 7, '检查米饭', '拨开米饭看中心没有硬块，蟹肉棒黄瓜鸡蛋饭盖上去后能吸汁但仍保持松散。', 'check_doneness', array[]::text[], array[]::text[], 1, null, ''),
  ('imitation_crab_cucumber_egg_bowl', 8, '整理出餐', '确认蟹肉棒黄瓜鸡蛋饭不积水、主料分布均匀，就可以直接端出。', 'plate_dish', array['rice', 'imitation_crab', 'cucumber', 'egg']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('cod_broccoli_rice_bowl', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收鳕鱼西兰花饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('cod_broccoli_rice_bowl', 2, '切配浇头', '鳕鱼擦干并切成厚度接近的块，西兰花切成大小接近的块或段，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['cod', 'broccoli']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('cod_broccoli_rice_bowl', 3, '做出底味', '锅热后先处理鳕鱼，看到鱼肉由透明转白，能轻轻推动但不碎。', 'stir_fry', array['cod']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('cod_broccoli_rice_bowl', 4, '加入配菜', '加入剩余cod、broccoli翻匀，鳕鱼西兰花饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['cod', 'broccoli']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('cod_broccoli_rice_bowl', 5, '收成浇头', '加调味或少量水，煮到鳕鱼西兰花饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['cod', 'broccoli']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('cod_broccoli_rice_bowl', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让鳕鱼西兰花饭状态更稳定。', 'combine_ingredients', array['rice', 'cod', 'broccoli']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('cod_broccoli_rice_bowl', 7, '整理浇头', '把鳕鱼西兰花饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('cod_broccoli_rice_bowl', 8, '确认盖饭', '尝一口浇头和饭，鳕鱼西兰花饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'cod', 'broccoli']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('frozen_corn_egg_soup', 1, '切配汤料', '鸡蛋打散到蛋清蛋黄融合，冷冻玉米粒沥干，块头不要太大，汤里入口会更顺。', 'slice_vegetables', array['frozen_corn', 'egg']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('frozen_corn_egg_soup', 2, '先出香味', '锅中少量油处理鸡蛋，香味出来但不要炒焦，确认状态后继续。', 'saute_aromatics', array['frozen_corn', 'egg']::text[], array['pot', 'spatula']::text[], 3, null, ''),
  ('frozen_corn_egg_soup', 3, '加入汤底', '加入清水或汤底，锅中液面没过主要食材，煮开后汤色开始变均匀，让冷冻玉米蛋花汤受热更均匀。', 'boil_water', array['frozen_corn', 'egg']::text[], array['pot']::text[], 4, null, ''),
  ('frozen_corn_egg_soup', 4, '先煮耐煮', '先把冷冻玉米煮到颗粒散开，再淋蛋液，汤面会更均匀。', 'simmer', array['frozen_corn', 'egg']::text[], array['pot', 'ladle']::text[], 10, null, ''),
  ('frozen_corn_egg_soup', 5, '再下易熟', '加入鸡蛋，轻轻推开，避免把嫩食材搅碎，确认状态后继续。', 'combine_ingredients', array['frozen_corn', 'egg']::text[], array['pot', 'ladle']::text[], 4, null, ''),
  ('frozen_corn_egg_soup', 6, '观察汤色', '小火煮到冷冻玉米蛋花汤汤色更融合，主料状态达到蛋液边缘刚凝固、中间仍柔软。', 'check_doneness', array['frozen_corn', 'egg']::text[], array['pot', 'ladle']::text[], 5, null, ''),
  ('frozen_corn_egg_soup', 7, '调味收口', '加盐或酱料后尝汤，味道清楚但不过重，汤面没有大量浮沫，让冷冻玉米蛋花汤味道更均匀。', 'season', array['frozen_corn', 'egg']::text[], array['pot', 'ladle']::text[], 2, null, ''),
  ('frozen_corn_egg_soup', 8, '盛出汤品', '把冷冻玉米蛋花汤连汤带料盛出，碗里汤料比例均匀即可。', 'plate_dish', array['frozen_corn', 'egg']::text[], array['pot', 'ladle']::text[], 1, null, ''),
  ('frozen_mixed_vegetable_tofu', 1, '处理食材', '豆腐切块后轻轻吸掉表面水分，冷冻杂蔬保持颗粒分散，看一遍顺序，冷冻杂蔬炒豆腐下锅后就不用临时找东西。', 'prep_ingredients', array['frozen_mixed_vegetables', 'tofu']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('frozen_mixed_vegetable_tofu', 2, '热锅下油', '锅面热后加油，油能流动铺开，说明冷冻杂蔬炒豆腐可以开始下主料。', 'heat_pan', array[]::text[], array['pan']::text[], 2, null, ''),
  ('frozen_mixed_vegetable_tofu', 3, '处理主料', '放入豆腐摊开受热，看到豆腐边缘微黄，轻推时还能保持块状再翻动或拨到锅边，让冷冻杂蔬炒豆腐状态更稳定。', 'sear_meat', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, '肉类或海鲜先摊开，有助于减少出水。'),
  ('frozen_mixed_vegetable_tofu', 4, '加入配菜', '加入冷冻杂蔬翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['frozen_mixed_vegetables']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('frozen_mixed_vegetable_tofu', 5, '合炒入味', '把锅中食材合在一起，调味后看到冷冻杂蔬炒豆腐的主味均匀裹在食材上。', 'combine_ingredients', array['frozen_mixed_vegetables', 'tofu']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('frozen_mixed_vegetable_tofu', 6, '装盘检查', '确认冷冻杂蔬炒豆腐豆腐边缘微黄，轻推时还能保持块状，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['frozen_mixed_vegetables', 'tofu']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('frozen_pea_chicken_fried_rice', 1, '拨散米饭', '把熟米饭压散，看到大饭团分开，冷冻豌豆鸡肉炒饭才容易炒到粒粒分明。', 'prep_ingredients', array['rice']::text[], array['mixing_bowl']::text[], 2, null, ''),
  ('frozen_pea_chicken_fried_rice', 2, '处理配料', '鸡胸肉切成薄片或小块，冷冻豌豆沥干，配料水分少一点，后面米饭不容易炒湿。', 'cut_meat', array['frozen_peas', 'chicken_breast']::text[], array['knife', 'cutting_board']::text[], 4, null, ''),
  ('frozen_pea_chicken_fried_rice', 3, '先炒配料', '锅热加油后先处理鸡胸肉，看到肉类表面变色，锅底水汽明显减少。', 'stir_fry', array['chicken_breast']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('frozen_pea_chicken_fried_rice', 4, '压散米饭', '米饭入锅后用铲背压开，饭粒从成团变松散，锅底水汽减少，让冷冻豌豆鸡肉炒饭状态更稳定。', 'stir_fry', array['rice']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('frozen_pea_chicken_fried_rice', 5, '合入配料', '把冷冻豌豆、鸡胸肉和米饭翻匀，颜色分布均匀，不要让配料堆在一侧。', 'combine_ingredients', array['rice', 'frozen_peas', 'chicken_breast']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('frozen_pea_chicken_fried_rice', 6, '调味均匀', '沿锅边加少量调味，翻到每勺米饭都有香气，冷冻豌豆鸡肉炒饭不出现湿团。', 'season', array['rice', 'frozen_peas', 'chicken_breast']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('frozen_pea_chicken_fried_rice', 7, '检查米粒', '铲起一勺能自然散开，米粒表面有油亮感但不粘成块，就可以关火，让冷冻豌豆鸡肉炒饭状态更稳定。', 'check_doneness', array['rice', 'frozen_peas', 'chicken_breast']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('frozen_pea_chicken_fried_rice', 8, '盛出炒饭', '把冷冻豌豆鸡肉炒饭盛入碗中，表面能看到配料均匀分布。', 'plate_dish', array['rice', 'frozen_peas', 'chicken_breast']::text[], array['pan', 'spatula']::text[], 1, null, ''),
  ('canned_mushroom_tofu_rice', 1, '准备米饭', '米饭煮好或加热到松软，压散到没有硬块，方便吸收罐头蘑菇豆腐饭的浇头。', 'cook_rice', array['rice']::text[], array['rice_cooker', 'mixing_bowl']::text[], 3, null, ''),
  ('canned_mushroom_tofu_rice', 2, '切配浇头', '豆腐切块后轻轻吸掉表面水分，蘑菇罐头沥干并拨散，大小接近，盖到饭上时每一口都能吃到主料。', 'slice_vegetables', array['canned_mushroom', 'tofu']::text[], array['knife', 'cutting_board']::text[], 6, null, ''),
  ('canned_mushroom_tofu_rice', 3, '做出底味', '锅热后先处理豆腐，看到豆腐边缘微黄，轻推时还能保持块状，让罐头蘑菇豆腐饭状态更稳定。', 'stir_fry', array['tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('canned_mushroom_tofu_rice', 4, '加入配菜', '加入剩余canned mushroom、tofu翻匀，罐头蘑菇豆腐饭的浇头颜色均匀、锅底水汽减少。', 'stir_fry', array['canned_mushroom', 'tofu']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('canned_mushroom_tofu_rice', 5, '收成浇头', '加调味或少量水，煮到罐头蘑菇豆腐饭的主味均匀裹在食材上，铲过锅底能短暂露出锅面。', 'simmer', array['canned_mushroom', 'tofu']::text[], array['pan', 'spatula']::text[], 5, null, ''),
  ('canned_mushroom_tofu_rice', 6, '浇到饭上', '把浇头盖在米饭上，边缘能看到米饭吸到少量汤汁但没有泡软，让罐头蘑菇豆腐饭状态更稳定。', 'combine_ingredients', array['rice', 'canned_mushroom', 'tofu']::text[], array['mixing_bowl', 'spatula']::text[], 2, null, ''),
  ('canned_mushroom_tofu_rice', 7, '整理浇头', '把罐头蘑菇豆腐饭浇头推匀，汤汁能挂住食材，盖饭时不会一边干一边湿。', 'simmer', array[]::text[], array[]::text[], 1, null, ''),
  ('canned_mushroom_tofu_rice', 8, '确认盖饭', '尝一口浇头和饭，罐头蘑菇豆腐饭咸淡合适、米饭仍松散时就可以出餐。', 'check_doneness', array['rice', 'canned_mushroom', 'tofu']::text[], array['mixing_bowl']::text[], 1, null, ''),
  ('lemon_garlic_white_fish', 1, '备齐食材', '白鱼擦干并切成厚度接近的块，柠檬切好后保持清爽不出水，蒜切好备用，看一遍顺序，柠檬蒜香白鱼下锅后就不用临时找东西。', 'prep_ingredients', array['white_fish', 'lemon', 'garlic']::text[], array['knife', 'cutting_board', 'mixing_bowl']::text[], 4, null, ''),
  ('lemon_garlic_white_fish', 2, '清洗沥水', '柠檬冲洗后沥到表面少水，炒的时候不容易把锅温一下子压低。', 'wash_ingredients', array['lemon']::text[], array['mixing_bowl']::text[], 3, null, ''),
  ('lemon_garlic_white_fish', 3, '爆出香味', '锅热加油后放蒜，闻到香气、边缘微微变色就进入下一步，让柠檬蒜香白鱼状态更稳定。', 'saute_aromatics', array['garlic']::text[], array['pan', 'spatula']::text[], 2, null, ''),
  ('lemon_garlic_white_fish', 4, '处理主料', '放入白鱼摊开受热，看到鱼肉由透明转白，能轻轻推动但不碎再翻动或拨到锅边。', 'pan_fry', array['white_fish']::text[], array['pan', 'spatula']::text[], 5, null, '鱼类步骤提醒轻推，避免频繁翻面导致散碎。'),
  ('lemon_garlic_white_fish', 5, '加入配菜', '加入柠檬翻炒，看到颜色变亮、边缘开始变软但还保留形状。', 'stir_fry', array['lemon']::text[], array['pan', 'spatula']::text[], 4, null, ''),
  ('lemon_garlic_white_fish', 6, '合炒入味', '把锅中食材合在一起，调味后看到蒜香明显但蒜末没有发黑，让柠檬蒜香白鱼状态更稳定。', 'combine_ingredients', array['white_fish', 'lemon', 'garlic']::text[], array['pan', 'spatula']::text[], 3, null, ''),
  ('lemon_garlic_white_fish', 7, '调整火候', '转中火让柠檬蒜香白鱼继续受热，锅底有少量汁水但不糊，主料状态更稳定。', 'stir_fry', array[]::text[], array[]::text[], 1, null, ''),
  ('lemon_garlic_white_fish', 8, '整理出餐', '确认柠檬蒜香白鱼鱼肉由透明转白，能轻轻推动但不碎，口味合适后盛出，避免继续闷在锅里。', 'plate_dish', array['white_fish', 'lemon', 'garlic']::text[], array['pan', 'spatula']::text[], 1, null, '')
;

delete from public.recipe_steps rs
using public.recipes r, _recipe_cooking_step_recipe_keys k
where rs.recipe_id = r.id
  and r.recipe_key = k.recipe_key;

insert into public.recipe_steps (
  recipe_id,
  step_number,
  title,
  body,
  estimated_minutes,
  timer_seconds,
  ingredient_keys,
  equipment_keys,
  tips
)
select
  r.id,
  s.step_number,
  s.title,
  s.body,
  s.estimated_minutes,
  s.timer_seconds,
  s.ingredient_keys,
  s.equipment_keys,
  s.tips
from _recipe_steps_seed s
join public.recipes r on r.recipe_key = s.recipe_key
order by r.recipe_key, s.step_number;

delete from public.recipe_tutorial_steps ts
using public.recipes r, _recipe_cooking_step_recipe_keys k
where ts.recipe_id = r.id
  and r.recipe_key = k.recipe_key;

insert into public.recipe_tutorial_steps (
  recipe_id,
  step_number,
  title,
  body,
  action_key,
  ingredient_keys,
  equipment_keys,
  estimated_minutes,
  timer_seconds,
  assistant_context
)
select
  r.id,
  s.step_number,
  s.title,
  s.body,
  s.action_key,
  s.ingredient_keys,
  s.equipment_keys,
  s.estimated_minutes,
  s.timer_seconds,
  s.assistant_context
from _recipe_tutorial_steps_seed s
join public.recipes r on r.recipe_key = s.recipe_key
order by r.recipe_key, s.step_number;

commit;
